window.AI_CURRICULUM_5 = [{"id":"travellers1_5","index":0,"name":"We the Travellers - I","subtitle":"Computational Thinking — Chapter 1","emoji":"🚌","palette":{"from":"#60a5fa","to":"#1e3a8a"},"lessons":[{"id":"wt1","title":"The Forward-Only Bus Route","icon":"🚌","kind":"lesson","story":"Captain Mira's bus has only one gear: forward! Help her track exactly which stops she's crossed so far on the Coastal Line before the evening fog rolls in.","teach":[{"title":"Sequences and Order","body":"A route is a sequence — a fixed list of stops in one order. When travel is 'forward only', once you pass a stop you can never go back to it, so you always know exactly what's ahead and what's behind.","visual":"➡️"}],"questions":[{"kind":"mcq","prompt":"A bus travels forward only through 5 towns in a straight line: Rampur → Sitapur → Ganjpur → Lakhpur → Meerpur. It is currently stopped at Ganjpur. Which towns has it already stopped at, including Ganjpur?","options":["Ganjpur, Lakhpur, and Meerpur","Rampur, Sitapur, and Ganjpur","All five towns","Only Rampur and Ganjpur"],"answer":1,"explain":"Forward-only travel means the bus passes towns strictly in order, so at Ganjpur it has already visited Rampur and Sitapur too."},{"kind":"numeric","prompt":"A bus line has 8 towns in a row, numbered 1 to 8. The bus starts at town 1 and travels forward only, stopping at every single town. After making 5 stops, at which town number is it?","answer":5,"explain":"Stopping at every town means stop number = town number, so 5 stops means it is at town 5."},{"kind":"mcq","prompt":"A bus travels forward only through 6 towns in order: A, B, C, D, E, F. It stops ONLY at every alternate town, starting with A. Which towns does it stop at?","options":["A, C, and E","A, D, and F","A, B, and C","B, D, and F"],"answer":0,"explain":"Starting at A and skipping one town each time gives A, C, E — the 1st, 3rd and 5th towns."},{"kind":"numeric","prompt":"A forward-only train stops at every one of 9 stations in a line. It has already stopped at all stations except the last 3. How many stations has it stopped at so far?","answer":6,"explain":"9 total stations minus the last 3 it has not reached yet leaves 6 stations already visited."},{"kind":"mcq","prompt":"Two buses run on the same forward-only line of towns: W, X, Y, Z. Bus 1 has stopped at W and X so far. Bus 2 started later and has stopped only at W. Which bus is further along the route?","options":["Bus 1","Bus 2","Both are at the same point","Cannot be determined"],"answer":0,"explain":"Bus 1 has already passed X, which comes after W, so it is further along the forward-only route."}]},{"id":"wt2","title":"Distance, Speed and Time","icon":"⏱️","kind":"lesson","story":"The Explorer's Club needs a navigator! Rani's jeep, bike, and boat all move at different speeds — figure out how far, how fast, and how long each journey takes.","teach":[{"title":"Distance = Speed × Time","body":"If you know how fast something travels (speed) and for how long (time), you can multiply them to find the distance covered. Flip the formula around to find speed or time instead, if you know the other two.","visual":"🧮"}],"questions":[{"kind":"numeric","prompt":"A cyclist rides at a steady speed of 8 km per hour for 3 hours. How many kilometres does she cover in total?","answer":24,"explain":"Distance = Speed × Time = 8 × 3 = 24 km."},{"kind":"numeric","prompt":"A van travels 60 km at a steady speed, taking exactly 2 hours. What is its speed in km per hour?","answer":30,"explain":"Speed = Distance ÷ Time = 60 ÷ 2 = 30 km/h."},{"kind":"numeric","prompt":"A tortoise walks at 5 metres per minute. How many minutes will it take to cover 45 metres?","answer":9,"explain":"Time = Distance ÷ Speed = 45 ÷ 5 = 9 minutes."},{"kind":"mcq","prompt":"A bus travels the first 40 km in 1 hour, then slows down and covers only 20 km in the next hour. What is its AVERAGE speed over the whole 2-hour trip?","options":["20 km/h","60 km/h","30 km/h","40 km/h"],"answer":2,"explain":"Total distance 60 km over total time 2 hours gives an average speed of 60 ÷ 2 = 30 km/h."},{"kind":"numeric","prompt":"A car travels at 45 km/h for 2 hours and then at 30 km/h for 1 more hour. What total distance does it cover?","answer":120,"explain":"First leg: 45×2=90 km. Second leg: 30×1=30 km. Total = 90+30 = 120 km."}]},{"id":"wt3","title":"Planning the Shortest Route","icon":"🗺️","kind":"lesson","story":"Deep in Puzzle Valley, every path between villages has a distance sign nailed to a tree. Plan the shortest route for the mail carrier so no letter arrives late!","teach":[{"title":"Comparing Paths","body":"When there is more than one way to get somewhere, a computational thinker lists every possible route, adds up the distance for each one, and then compares the totals to pick the shortest.","visual":"🧭"}],"questions":[{"kind":"numeric","prompt":"In Puzzle Valley there are three roads: Alpha–Beta is 4 km, Beta–Gamma is 3 km, and there is also a direct road Alpha–Gamma that is 9 km. What is the length of the shortest route from Alpha to Gamma?","answer":7,"explain":"Going Alpha→Beta→Gamma = 4+3 = 7 km, which is shorter than the direct 9 km road."},{"kind":"mcq","prompt":"Using the same roads (Alpha–Beta = 4 km, Beta–Gamma = 3 km, direct Alpha–Gamma = 9 km), which route should the mail carrier take to go from Alpha to Gamma in the LEAST distance?","options":["Alpha → Gamma directly","Either route, they are equal","Cannot be determined","Alpha → Beta → Gamma"],"answer":3,"explain":"The two-road path (4+3=7 km) beats the direct 9 km road."},{"kind":"numeric","prompt":"Now add one more road: Gamma–Delta is 2 km. What is the shortest distance from Alpha to Delta, travelling through Beta and Gamma?","answer":9,"explain":"Alpha→Beta (4) + Beta→Gamma (3) + Gamma→Delta (2) = 4+3+2 = 9 km."},{"kind":"mcq","prompt":"A delivery robot can travel Home→Park directly (6 km) or Home→Library→Park (2 km + 3 km). Which route is shorter, and by how much?","options":["Home→Library→Park, by 1 km","Home→Park directly, by 1 km","Both are equal","Home→Library→Park, by 2 km"],"answer":0,"explain":"Home→Library→Park = 2+3 = 5 km, which is 1 km less than the direct 6 km route."},{"kind":"numeric","prompt":"Four towns lie in a loop: Home to Mall is 5 km, Mall to School is 4 km, and School to Home directly is 6 km. What is the shortest distance to travel from Home to School?","answer":6,"explain":"Home→Mall→School = 5+4=9 km, but the direct Home→School road of 6 km is shorter, so 6 km is the answer."}]},{"id":"wt4","title":"Reading the Travel Timetable","icon":"🕓","kind":"lesson","story":"The Grand Station's timetable board is scrambled by a gust of wind! Use logic to work out when each train really leaves and arrives.","teach":[{"title":"Timetable Logic","body":"A timetable lists departure and arrival times in order. To find how long a journey takes, count forward from the departure time to the arrival time — and remember that 60 minutes make 1 hour.","visual":"📋"}],"questions":[{"kind":"numeric","prompt":"A train leaves the station at 9:00 and arrives at its destination at 11:30. How many minutes does the journey take?","answer":150,"explain":"From 9:00 to 11:30 is 2 hours 30 minutes = 120+30 = 150 minutes."},{"kind":"mcq","prompt":"A bus departs at 4:15 pm and the journey takes 50 minutes. What time does it arrive?","options":["5:15 pm","5:00 pm","4:50 pm","5:05 pm"],"answer":3,"explain":"4:15 pm + 50 minutes = 5:05 pm."},{"kind":"numeric","prompt":"Three trains leave a station one after another, each 20 minutes after the previous one. The first train leaves at 8:00. Give your answer as minutes past 8:00 (for example, answer 40 means 8:40) — at what time does the THIRD train leave?","answer":40,"explain":"Train 2 leaves at 8:20 and Train 3 leaves 20 minutes later, at 8:40, which is 40 minutes past 8:00."},{"kind":"mcq","prompt":"A ferry timetable shows departures every 45 minutes starting at 6:00 am. Which of these is NOT a departure time?","options":["8:15 am","7:30 am","6:45 am","7:00 am"],"answer":3,"explain":"Departures fall at 6:00, 6:45, 7:30, 8:15 and so on, so 7:00 am does not appear in the pattern."},{"kind":"numeric","prompt":"A student catches a train that departs at 10:10 and needs to reach school by 11:00. If the train ride itself takes 35 minutes, how many minutes does she have left to walk from the station to school before 11:00?","answer":15,"explain":"10:10 + 35 minutes = 10:45. From 10:45 to 11:00 is 15 minutes left."}]},{"id":"wt5","title":"Breaking a Big Trip into Steps","icon":"🧩","kind":"lesson","story":"Planning the class trip to the Hill Fort is a huge job! Break it down into small, ordered tasks so nothing gets forgotten — that's decomposition and algorithmic thinking at work.","teach":[{"title":"Decomposition","body":"Decomposition means breaking a big, complicated task — like planning a whole journey — into smaller steps that are easy to handle one at a time, in the right order.","visual":"🧩"},{"title":"Algorithms for Trips","body":"An algorithm is a clear list of steps done in order to reach a goal. A good travel algorithm — pack bag, walk to stop, buy ticket, board bus — must have every step in the correct sequence, or the plan fails.","visual":"📝"}],"questions":[{"kind":"mcq","prompt":"Which of these is the correct ORDER of steps for catching a bus to school? Step W: Wait at the bus stop. Step X: Walk from home to the bus stop. Step Y: Board the bus when it arrives. Step Z: Get off at the school stop.","options":["Z, Y, W, X","X, Y, W, Z","X, W, Y, Z","W, X, Y, Z"],"answer":2,"explain":"You must first walk to the stop (X), then wait (W), then board (Y), then get off (Z)."},{"kind":"mcq","prompt":"A travel algorithm lists these steps out of order: 1) Reach the platform 2) Buy a ticket 3) Show the ticket at the gate 4) Board the train. Which step should actually come FIRST?","options":["Buy a ticket","Show the ticket at the gate","Board the train","Reach the platform"],"answer":0,"explain":"You must buy the ticket before you can show it at the gate or reach the platform, so buying the ticket comes first."},{"kind":"numeric","prompt":"A trip-planning algorithm has 6 steps that must be done strictly in order: pack bag, lock door, walk to stop, buy ticket, board bus, take seat. If a traveller has just finished step 4 (buy ticket), how many steps does she still have left to do?","answer":2,"explain":"6 total steps minus the 4 already completed leaves 2 steps: board bus and take seat."},{"kind":"mcq","prompt":"Which task is a good example of 'decomposition' when planning a school picnic trip?","options":["Only thinking about the bus and nothing else","Doing every task at the exact same moment","Ignoring the smaller details and hoping it works out","Splitting the trip into smaller parts: transport, food, activities, and return time"],"answer":3,"explain":"Decomposition means breaking one big task into smaller, manageable parts, like transport, food, activities, and return time."},{"kind":"mcq","prompt":"In an algorithm for boarding a flight, which step logically must happen BEFORE 'find your seat'?","options":["Land at the destination","Show your boarding pass at the gate","Fasten your seatbelt","Collect your luggage"],"answer":1,"explain":"You must show your boarding pass and enter the plane before you can find your seat."}]},{"id":"wt6","title":"Spot the Travel Pattern","icon":"🔁","kind":"lesson","story":"The toy train at Fun Fair Park repeats its route again and again. Watch closely, find the pattern in stops, fares and distances, and predict what comes next!","teach":[{"title":"Pattern Recognition","body":"Pattern recognition means noticing what repeats or changes by a fixed rule — like a train's stops, or how ticket prices grow with distance — so you can predict what comes next without being told.","visual":"🔁"}],"questions":[{"kind":"numeric","prompt":"A toy train's ticket costs ₹10 for the 1st stop, and ₹5 more for each extra stop after that. How much does a ticket to the 4th stop cost?","answer":25,"explain":"Each extra stop adds ₹5: 10, 15, 20, 25 — so the 4th stop costs ₹25."},{"kind":"numeric","prompt":"A cyclist's daily distances follow a pattern: 2 km, 4 km, 6 km, 8 km... If the pattern continues, how far does she cycle on the 6th day?","answer":12,"explain":"The pattern adds 2 km each day: 2, 4, 6, 8, 10, 12 — so day 6 is 12 km."},{"kind":"mcq","prompt":"A shuttle bus repeats this loop of stops forever: Gate, Market, Temple, Gate, Market, Temple... If it just stopped at 'Market' for the 5th time, which stop will it reach next?","options":["The loop ends here","Gate","Market again","Temple"],"answer":3,"explain":"The pattern is Gate, Market, Temple repeating, so after Market always comes Temple."},{"kind":"numeric","prompt":"A train's stop pattern doubles the distance from the start each time: 3 km, 6 km, 12 km, 24 km... What distance will the 5th stop be at?","answer":48,"explain":"Each stop doubles the previous distance: 3, 6, 12, 24, 48 — so the 5th stop is 48 km from the start."},{"kind":"mcq","prompt":"Look at this sequence of bus fares by zone: ₹15, ₹20, ₹25, ₹30, ?. What rule explains the pattern, and what is the missing fare?","options":["Subtract ₹5 each time; ₹25","Multiply by 2 each time; ₹60","Add ₹10 each time; ₹40","Add ₹5 each time; ₹35"],"answer":3,"explain":"Each fare increases by ₹5: 15, 20, 25, 30, 35 — so the pattern is 'add ₹5' and the missing fare is ₹35."}]},{"id":"wt-boss","title":"The Master Route-Keeper's Challenge","icon":"👑","kind":"boss","story":"The Master Route-Keeper of Puzzle Valley blocks the final gate with a tangle of routes, clocks and patterns. Solve every challenge to earn your Traveller's Badge!","teach":[{"title":"Putting It All Together","body":"Real journeys mix every skill you've learned: following a sequence, calculating distance and time, comparing routes, reading timetables, breaking trips into steps, and spotting patterns. Use whichever tool fits each puzzle!","visual":"🏆"}],"boss":{"name":"The Master Route-Keeper","taunt":"You think you can out-plan a route that's older than the map itself?"},"questions":[{"kind":"numeric","prompt":"A forward-only train travels through 7 stations in a line, numbered 1 to 7. It has already stopped at every station except the last 2. At which station number is it currently standing?","answer":5,"explain":"7 total stations minus the last 2 not yet reached means the 5th station is the last one visited, so it is currently at station 5."},{"kind":"numeric","prompt":"A bus covers 90 km in 3 hours at a steady speed, then travels for 2 more hours at that same speed. What TOTAL distance does it cover in the full 5 hours?","answer":150,"explain":"Speed = 90 ÷ 3 = 30 km/h. In 5 hours total: 30 × 5 = 150 km."},{"kind":"numeric","prompt":"Between two villages, the direct road is 11 km. A route via a third village is 5 km plus 4 km. What is the shortest possible distance between the two villages?","answer":9,"explain":"The indirect route (5+4=9 km) is shorter than the direct 11 km road."},{"kind":"mcq","prompt":"A ferry leaves every 30 minutes starting at 7:00 am. A passenger reaches the dock at 8:10 am. How long must she wait for the next ferry?","options":["30 minutes","20 minutes","10 minutes","50 minutes"],"answer":1,"explain":"Ferries leave at 7:00, 7:30, 8:00, 8:30... so the next one after 8:10 am is 8:30 am, which is 20 minutes later."},{"kind":"mcq","prompt":"Which of these is the correctly ORDERED algorithm for a road trip: fill fuel tank, start engine, drive to destination, park the car?","options":["Drive to destination → Fill fuel tank → Start engine → Park the car","Fill fuel tank → Start engine → Drive to destination → Park the car","Park the car → Drive to destination → Start engine → Fill fuel tank","Start engine → Fill fuel tank → Park the car → Drive to destination"],"answer":1,"explain":"You must fuel up, start the engine, drive, and only then park — each step depends on the one before it."},{"kind":"numeric","prompt":"A cable car's height above ground follows the pattern 4 m, 8 m, 16 m, 32 m at four towers. If the pattern continues, what will its height be at the 5th tower?","answer":64,"explain":"Each tower doubles the height of the one before: 4, 8, 16, 32, 64 — so the 5th tower is 64 m."},{"kind":"mcq","prompt":"A bus travels forward only along a straight route of towns spaced 6 km apart: Town1, Town2, Town3, Town4. It has already covered 18 km from Town1. Which town has it just reached?","options":["Town2","Town4","Town1","Town3"],"answer":1,"explain":"18 km ÷ 6 km per gap = 3 gaps travelled, landing at Town4 (Town1→Town2→Town3→Town4)."}]}]},{"id":"fractions5","index":1,"name":"Fractions","subtitle":"Computational Thinking — Chapter 2","emoji":"🍰","palette":{"from":"#34d399","to":"#065f46"},"lessons":[{"id":"fr1","title":"The Bakery Gates","icon":"🍰","kind":"lesson","story":"The gates of the Bakery of Bhagpur are sealed by a frosting spell that only breaks for those who can compare fraction-slices correctly. Grab an apron, apprentice — it's time to prove you know your slices from your crumbs!","teach":[{"title":"What is a fraction?","body":"A fraction shows equal parts of one whole, written as parts-you-have over total-parts, like 3/8. The bottom number (denominator) says how many equal pieces the whole was cut into, and the top number (numerator) says how many of those pieces you're talking about.","visual":"🍰"},{"title":"Comparing fractions with the same denominator","body":"When two fractions are cut into the same number of pieces, just compare the top numbers — more pieces means a bigger fraction. So 5/8 is more cake than 3/8, because both are cut into eighths but 5 is more than 3.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"A cake is cut into 8 equal slices. Priya eats 3 slices and Raj eats 5 slices. Who ate the bigger fraction of the cake?","options":["Priya, because 3/8 is more than 5/8","They ate an equal fraction","Cannot be determined","Raj, because 5/8 is more than 3/8"],"answer":3,"explain":"Both fractions have the same denominator (8), so the one with the bigger numerator — Raj's 5/8 — is the larger fraction."},{"kind":"mcq","prompt":"Which is a bigger share: 1/4 kg of laddoos or 1/6 kg of laddoos?","options":["Cannot be determined","1/4 kg, because splitting into fewer parts makes each part bigger","1/6 kg, because 6 is a bigger number than 4","They are exactly equal"],"answer":1,"explain":"Both have a numerator of 1, but cutting into only 4 parts makes each part bigger than cutting the same amount into 6 parts."},{"kind":"numeric","prompt":"A garden is divided into 10 equal plots. Roses grow in 7 of the plots. How many plots do NOT have roses?","answer":3,"explain":"10 total plots minus the 7 with roses leaves 3 plots without roses — that's 3/10 of the garden."},{"kind":"mcq","prompt":"Two ribbons of the same length are cut into pieces. Ribbon A is cut into 5 equal pieces and Ribbon B into 9 equal pieces. One piece of which ribbon is longer?","options":["Ribbon A, because fewer, bigger pieces come from cutting into 5","Ribbon B, because 9 pieces means each is longer","Both pieces are the same length","Cannot be determined"],"answer":0,"explain":"The same length cut into fewer pieces (5) gives bigger pieces than cutting it into more pieces (9)."}]},{"id":"fr2","title":"The Ordering Trail","icon":"📏","kind":"lesson","story":"Beyond the bakery winds the Ordering Trail, a rope bridge where every plank is stamped with a fraction. Step on the planks from smallest to largest, or you'll tumble into the syrup swamp below!","teach":[{"title":"Lining fractions up in order","body":"To put fractions in order, compare them two at a time using what you know: same denominator means compare numerators, same numerator means the fraction with the smaller denominator is actually bigger (fewer, larger pieces).","visual":"📏"},{"title":"Fraction riddles","body":"Some puzzles describe a fraction without ever writing it down — like 'double me and you get a whole.' Turn the words into a small equation to hunt down the mystery fraction.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"Order these fractions from smallest to largest: 3/5, 1/5, 4/5.","options":["1/5, 4/5, 3/5","1/5, 3/5, 4/5","3/5, 1/5, 4/5","4/5, 3/5, 1/5"],"answer":1,"explain":"All three share the denominator 5, so just sort the numerators: 1, 3, 4 — giving 1/5, 3/5, 4/5."},{"kind":"mcq","prompt":"Riddle: If you double me, you get exactly one whole. Who am I?","options":["1/2 (Half)","1/4 (Quarter)","3/4 (Three-quarters)","1/3 (One-third)"],"answer":0,"explain":"Half doubled is 1/2 + 1/2 = 1 whole, so the mystery fraction is 1/2."},{"kind":"numeric","prompt":"Four friends each drink from a same-size glass of juice: Aisha drinks 2/6 of hers, Bilal drinks 1/6, Chetan drinks 4/6, and Divya drinks 3/6. How many of them drank MORE than half a glass (more than 3/6)?","answer":1,"explain":"Half a glass is 3/6. Only Chetan's 4/6 is greater than 3/6, so exactly 1 friend drank more than half."},{"kind":"mcq","prompt":"Which of these fractions is the smallest: 2/3, 2/5, 2/9?","options":["2/5","2/3","2/9","They are all equal"],"answer":2,"explain":"All three share the numerator 2, and splitting into the most pieces (9) makes each piece — and the fraction — the smallest."}]},{"id":"fr3","title":"Equivalence Portals","icon":"🌀","kind":"lesson","story":"A shimmering ring of portals blocks the road ahead. Each portal only opens for its twin fraction — the same amount written with different numbers. Find the matching value to step through safely.","teach":[{"title":"Equivalent fractions","body":"Equivalent fractions look different but stand for the same amount, like 1/2 and 2/4. You can find them by multiplying (or dividing) both the numerator AND the denominator by the same number.","visual":"🌀"},{"title":"Spotting the pattern","body":"If you know the scaling factor used on the denominator, use that exact same factor on the numerator to keep the fraction equal — and vice versa.","visual":"🔑"}],"questions":[{"kind":"mcq","prompt":"Which fraction is equivalent to 2/3?","options":["3/4","8/12","5/6","2/6"],"answer":1,"explain":"Multiplying both the top and bottom of 2/3 by 4 gives 8/12, which is the same amount as 2/3."},{"kind":"numeric","prompt":"3/4 is equivalent to ?/12. What number replaces the question mark?","answer":9,"explain":"To turn the denominator 4 into 12, multiply by 3. Doing the same to the numerator gives 3 x 3 = 9, so 3/4 = 9/12."},{"kind":"numeric","prompt":"If star = 16, diamond = half of star, and club = a quarter of star, find: star minus diamond plus club.","answer":12,"explain":"star = 16, diamond = 8, club = 4. So 16 - 8 + 4 = 12."},{"kind":"mcq","prompt":"Each row below follows the same equivalent-fraction pattern. What are A and B? Row 1: 1/2 = 2/4 = 3/A. Row 2: 1/3 = 2/6 = B/9.","options":["A = 6, B = 3","A = 6, B = 4","A = 8, B = 4","A = 5, B = 2"],"answer":0,"explain":"1/2 scaled by 3 gives 3/6, so A = 6. 1/3 scaled by 3 (since 3 x 3 = 9) gives 3/9, so B = 3."}]},{"id":"fr4","title":"The Village Census","icon":"👥","kind":"lesson","story":"You reach the Great Village Census, where every villager only speaks in fractions of the whole crowd. Figure out how many people are really standing before you to earn the census-keeper's trust.","teach":[{"title":"Finding a fraction of a group","body":"To find a fraction of a group, divide the group by the denominator to find the size of one part, then multiply by the numerator. For example, 3/4 of 12 means: 12 divided by 4 = 3 (one part), then 3 x 3 = 9.","visual":"👥"},{"title":"Working backwards to find the whole","body":"Sometimes you know how many are in a fraction of the group, and must find the total. If you know that one part equals a certain number, multiply that by the denominator to get the whole group.","visual":"🔙"}],"questions":[{"kind":"numeric","prompt":"In a class of 20 students, 3/5 wear a blue badge. How many students wear a blue badge?","answer":12,"explain":"One-fifth of 20 is 4, and 3/5 means 3 of those fifths, so 3 x 4 = 12 students."},{"kind":"numeric","prompt":"3/4 of the class are wearing blue caps. If 9 students wear blue caps, how many students are in the class in total?","answer":12,"explain":"If 3 parts (out of 4) equal 9 students, one part equals 3 students, so the whole class (4 parts) is 4 x 3 = 12."},{"kind":"mcq","prompt":"In a garden with 35 flowers, 2/7 of them are roses. How many flowers are NOT roses?","options":["25","10","20","15"],"answer":0,"explain":"One-seventh of 35 is 5, so roses = 2 x 5 = 10. That leaves 35 - 10 = 25 flowers that are not roses."},{"kind":"numeric","prompt":"A team has some players. 5/8 of them scored a goal this season, and that group is exactly 15 players. How many players are on the team in total?","answer":24,"explain":"If 5 parts equal 15 players, one part equals 3 players, so the whole team (8 parts) is 8 x 3 = 24."},{"kind":"mcq","prompt":"Neha has some marbles. She gives 2 more than half of them to her brother, and 2 less than half of them (of the original total) to her sister. What is the difference between the number of marbles given to her brother and her sister?","options":["Cannot be determined","4","2","0"],"answer":1,"explain":"Brother gets (half + 2) and sister gets (half - 2). The difference between them is always (half + 2) - (half - 2) = 4, no matter the total."}]},{"id":"fr5","title":"The Sharing Hall","icon":"🍕","kind":"lesson","story":"The Sharing Hall feeds every traveler who passes through — but each dish must be split fairly using fractions. Help the innkeeper divide correctly, or a very hungry crowd might start to grumble!","teach":[{"title":"Sharing equally as a fraction","body":"When you share things equally, the fraction each person gets is: (number of items) over (number of people). For example, 3 sandwiches shared equally among 4 friends means each friend gets 3/4 of a sandwich.","visual":"🍕"},{"title":"Decomposing a fraction","body":"A fraction can be split into smaller fractions that add up to it, like 5/6 = 1/2 + 1/3 (since 1/2 = 3/6 and 1/3 = 2/6, and 3/6 + 2/6 = 5/6). This helps when a whole is shared unevenly between groups.","visual":"➗"}],"questions":[{"kind":"mcq","prompt":"4 friends share 3 identical sandwiches equally. What fraction of a sandwich does each friend get?","options":["3/4","1/4","4/3","1/3"],"answer":0,"explain":"Sharing 3 sandwiches among 4 people gives each person (items)/(people) = 3/4 of a sandwich."},{"kind":"numeric","prompt":"A rope represents one whole. It is cut so that one piece is 3/5 of the rope. What is the numerator of the remaining piece, written as a fraction out of 5?","answer":2,"explain":"The whole rope is 5/5. Taking away the 3/5 piece leaves 5/5 - 3/5 = 2/5, so the numerator is 2."},{"kind":"numeric","prompt":"A farm (the whole) is split between two farmers. The first farmer gets 1/2 of the farm. The second farmer gets the rest, which is written as a fraction out of 6. What is the numerator of the second farmer's share?","answer":3,"explain":"1/2 written out of 6 is 3/6, and the whole farm is 6/6. So the second farmer gets 6/6 - 3/6 = 3/6, a numerator of 3."},{"kind":"mcq","prompt":"Sam makes 3 straight cuts across a round cake, and every cut passes exactly through the center. Into how many equal pieces is the cake now cut?","options":["3","6","9","8"],"answer":1,"explain":"Each cut through the center is a full line across the circle, and 3 such lines split it into 2 x 3 = 6 equal wedges."},{"kind":"numeric","prompt":"A pot with 24 servings of biryani is shared: 1/3 of it goes to Table A, 1/4 of it goes to Table B, and the rest goes to Table C. How many servings does Table C get?","answer":10,"explain":"Table A gets 1/3 of 24 = 8, Table B gets 1/4 of 24 = 6. Together that's 14, leaving Table C with 24 - 14 = 10 servings."}]},{"id":"fr6","title":"The Riddle Keeper","icon":"🕵️","kind":"lesson","story":"Deep in Fraction Forest lives the Riddle Keeper, who guards the last bridge before the boss's tower. Only those who can outsmart tricky fraction riddles — and spot the ones with no clear answer — may cross.","teach":[{"title":"Reading clues carefully","body":"Word puzzles often hide fractions inside a story. Read slowly, note what fraction is given, and figure out exactly what question is actually being asked before you calculate anything.","visual":"🕵️"},{"title":"Chains of halving","body":"In some puzzles, an amount gets cut in half again and again. To find the starting amount, work backwards from the end: undo each halving by doubling, one step at a time.","visual":"🔗"}],"questions":[{"kind":"mcq","prompt":"Statement: Three-fifths of the stickers in Aarav's book are stars. Which conclusion can we definitely draw?","options":["All of Aarav's stickers are stars","Aarav has more star stickers than any other sticker book","Exactly two-fifths of the stickers are NOT stars","Aarav has exactly 15 star stickers"],"answer":2,"explain":"If 3/5 of the stickers are stars, the remaining 5/5 - 3/5 = 2/5 must be stickers that are not stars — that's true no matter how many stickers he has."},{"kind":"mcq","prompt":"At a toy stall, four visitors buy marbles from a jar one after another. Each visitor buys exactly half of the marbles currently in the jar. The fourth visitor buys the last 4 marbles. How many marbles were in the jar at the start?","options":["16","32","64","128"],"answer":2,"explain":"Working backwards from 4: before the 4th buyer there were 8, before the 3rd there were 16, before the 2nd there were 32, and before the 1st there were 64."},{"kind":"mcq","prompt":"Riddle: If you take 4 times of me, you get exactly one whole. Who am I?","options":["3/4 (Three-quarters)","1/4 (Quarter)","1/2 (Half)","1/3 (One-third)"],"answer":1,"explain":"1/4 taken 4 times is 1/4 + 1/4 + 1/4 + 1/4 = 1 whole."},{"kind":"mcq","prompt":"Rohan has some pencils. He gives 3 more than half of them to his friend, and 3 less than half of them (of the original total) to his cousin. What is the difference between the number of pencils given to his friend and his cousin?","options":["3","Cannot be determined","0","6"],"answer":3,"explain":"Friend gets (half + 3) and cousin gets (half - 3). Their difference is always (half + 3) - (half - 3) = 6, whatever the total number of pencils is."},{"kind":"mcq","prompt":"Three teams — Red, Blue, and Green — each have the same number of players, and every player plays exactly one game. Half of Red plays Chess, and this equals the entire Blue team also playing Chess. Half of Green plays Ludo, and this equals the other half of Red, who also play Ludo. Everyone left over plays Carrom. Which game has the fewest players?","options":["Carrom","Chess and Ludo are tied for fewest","Ludo","Chess"],"answer":0,"explain":"If each team has n players: Chess has n/2 (Red) + n (all of Blue) = 1.5n, Ludo has n/2 (Red) + n/2 (Green) = n, and only Green's leftover half (n/2) plays Carrom — the smallest group."}]},{"id":"fr-boss","title":"The Sphinx of Splitshire","icon":"👑","kind":"boss","boss":{"name":"The Sphinx of Splitshire","taunt":"You think you can slice through MY riddles? Split THIS, little mathematician!"},"story":"At the top of Fraction Forest's tower waits the Sphinx of Splitshire, guardian of every trick you've learned so far. Comparing, ordering, equivalence, sharing — it's all fair game now. Prove you've mastered fractions to claim the Golden Slice!","teach":[{"title":"Bring it all together","body":"The Sphinx mixes every skill from this world: comparing and ordering fractions, spotting equivalent fractions, finding a fraction of a group (and working backwards), and sharing or splitting wholes fairly. Read each riddle carefully before you answer!","visual":"👑"}],"questions":[{"kind":"mcq","prompt":"Which is greater: 5/9 or 5/12?","options":["5/9","Cannot be determined","They are equal","5/12"],"answer":0,"explain":"Both share the numerator 5, and splitting into fewer parts (9 instead of 12) makes each part — and the fraction — bigger."},{"kind":"numeric","prompt":"2/3 of the fish in a pond are goldfish. If there are 18 goldfish, how many fish are in the pond altogether?","answer":27,"explain":"If 2 parts equal 18 goldfish, one part equals 9 fish, so the whole pond (3 parts) is 3 x 9 = 27 fish."},{"kind":"numeric","prompt":"5/8 is equivalent to ?/24. What number replaces the question mark?","answer":15,"explain":"To turn the denominator 8 into 24, multiply by 3. Doing the same to the numerator gives 5 x 3 = 15."},{"kind":"mcq","prompt":"3 friends share 2 identical pizzas equally. What fraction of a pizza does each friend get?","options":["1/2","2/3","3/2","1/3"],"answer":1,"explain":"Sharing 2 pizzas among 3 friends gives each friend (items)/(people) = 2/3 of a pizza."},{"kind":"mcq","prompt":"Order these fractions from smallest to largest: 3/8, 3/4, 3/16.","options":["3/16, 3/8, 3/4","3/8, 3/16, 3/4","3/4, 3/16, 3/8","3/4, 3/8, 3/16"],"answer":0,"explain":"All three share the numerator 3, so the fraction with the most pieces (16) is smallest and the one with the fewest pieces (4) is largest: 3/16, 3/8, 3/4."},{"kind":"numeric","prompt":"Two players share a bag of sweets. The first player gets 4 more than half the sweets, and the second gets 4 less than half (of the original total). What is the difference between what the two players got?","answer":8,"explain":"The first gets (half + 4) and the second gets (half - 4). Their difference is always (half + 4) - (half - 4) = 8, no matter the total."},{"kind":"mcq","prompt":"Riddle: If you take me away from a whole, exactly twice of me is left. Who am I?","options":["1/4 (Quarter)","2/3 (Two-thirds)","1/2 (Half)","1/3 (One-third)"],"answer":3,"explain":"If the whole minus me leaves twice me, then the whole equals three of me (me + 2 x me), so I must be 1/3."}]}]},{"id":"anglesasturns5","index":2,"name":"Angles as Turns","subtitle":"Computational Thinking — Chapter 3","emoji":"🔄","palette":{"from":"#f472b6","to":"#831843"},"lessons":[{"id":"at1","title":"Quarter, Half, Full","icon":"🔄","kind":"lesson","story":"You are Robo-Pilot, guiding a toy robot through Turn Town, where every path bends at exact angles. Learn to read turns before you help Robo-Pilot escape the twisty maze!","teach":[{"title":"What is a turn?","body":"A turn is how much you rotate away from the direction you started facing, like spinning on the spot. We measure turns in fractions of a full circle: quarter, half, three-quarter, and full.","visual":"🔄"},{"title":"Turns in degrees","body":"A full turn all the way around is 360°. A half turn is 180°, a quarter turn is 90° (also called a right angle), and a three-quarter turn is 270°.","visual":"📐"}],"questions":[{"kind":"mcq","prompt":"A quarter turn is how many degrees?","options":["180°","45°","90°","360°"],"answer":2,"explain":"A quarter of a full circle (360°) is 90°, also called a right angle."},{"kind":"numeric","prompt":"How many degrees are in a half turn?","answer":180,"explain":"A half turn is exactly half of 360°, which is 180°."},{"kind":"mcq","prompt":"Which turn brings you back to face the exact same direction you started?","options":["A quarter turn (90°)","A half turn (180°)","A full turn (360°)","There is no such turn"],"answer":2,"explain":"A full turn of 360° goes all the way around a circle, so you end up facing where you began."},{"kind":"numeric","prompt":"A three-quarter turn equals how many degrees?","answer":270,"explain":"Three quarters of 360° is 270° (3 x 90°)."}]},{"id":"at2","title":"Clockwise or Anticlockwise?","icon":"🧭","kind":"lesson","story":"Deep in Turn Town, signposts spin two different ways. Robo-Pilot must learn to tell clockwise from anticlockwise to read the town's spinning arrows correctly.","teach":[{"title":"Clockwise and anticlockwise","body":"Clockwise turning follows the way a clock's hands move: North to East to South to West and back to North. Anticlockwise goes the opposite way: North to West to South to East and back to North.","visual":"🕐"},{"title":"Right-angle turns on a compass","body":"If you face North and make one clockwise quarter (right-angle) turn, you now face East. Two clockwise quarter turns from North lands you facing South.","visual":"🧭"}],"questions":[{"kind":"mcq","prompt":"Priya is facing North. She makes one right-angle turn in the clockwise direction. Which direction does she now face?","options":["South","West","North","East"],"answer":3,"explain":"Turning clockwise from North by a right angle (90°) brings Priya to face East."},{"kind":"mcq","prompt":"Priya is facing North. She makes one right-angle turn in the ANTI-clockwise direction. Which direction does she now face?","options":["East","West","North","South"],"answer":1,"explain":"Turning anticlockwise from North by a right angle (90°) brings Priya to face West."},{"kind":"mcq","prompt":"Arjun is facing North. He takes a right-angle turn clockwise, then another right-angle turn clockwise. What direction is he facing now?","options":["North","South","East","West"],"answer":1,"explain":"Two clockwise quarter turns add up to a half turn (180°), so North becomes South."},{"kind":"numeric","prompt":"Starting at North and turning clockwise by quarter turns, how many quarter turns are needed to face South?","answer":2,"explain":"Each quarter turn is 90°, and 2 x 90° = 180°, which turns North into South."}]},{"id":"at3","title":"Two-Step Spins","icon":"➕","kind":"lesson","story":"The town's puzzle board challenges Robo-Pilot with two-step spins — first one turn, then another. Track carefully or you'll end up facing the wrong way!","teach":[{"title":"Adding turns","body":"When you make more than one turn, you can add up the degrees. But clockwise and anticlockwise turns work in opposite directions, like adding and subtracting.","visual":"➕"},{"title":"Working out the net turn","body":"Treat clockwise turns as positive degrees and anticlockwise turns as negative degrees, then add them together. The total tells you the final direction.","visual":"🔁"}],"questions":[{"kind":"mcq","prompt":"Meera faces North. She makes a quarter turn clockwise, then a half turn anticlockwise. Which direction does she now face?","options":["East","North","West","South"],"answer":2,"explain":"North + 90° clockwise = East, then 180° anticlockwise from East = West."},{"kind":"mcq","prompt":"Kabir faces North. He makes a half turn clockwise, then a quarter turn clockwise. Which direction does he now face?","options":["East","West","North","South"],"answer":1,"explain":"North + 180° clockwise = South, then + 90° clockwise more = West."},{"kind":"numeric","prompt":"Facing North, Naina turns 90° clockwise, then 90° clockwise again, then 90° clockwise once more. What is her total turn in degrees?","answer":270,"explain":"Three quarter turns of 90° each add up to 90 + 90 + 90 = 270°."},{"kind":"mcq","prompt":"Using Naina's total turn of 270° clockwise from North, which direction is she now facing?","options":["West","East","North","South"],"answer":0,"explain":"270° clockwise from North lands on West (North to East to South to West)."}]},{"id":"at4","title":"Turtle-Bot Tracer","icon":"🐢","kind":"lesson","story":"Robo-Pilot's turtle-bot draws paths on graph paper by moving forward and turning. Trace its moves in your head to predict where it will finally point.","teach":[{"title":"Turtle steps","body":"A turtle-bot understands two kinds of commands: 'move forward' (it walks straight, its facing direction does not change) and 'turn' (it spins on the spot). Only turn commands change which way it faces.","visual":"🐢"},{"title":"Tracing a path","body":"To find the final facing direction, ignore the 'forward' steps and just add up all the turns in order — clockwise turns as positive, anticlockwise turns as negative.","visual":"🗺️"}],"questions":[{"kind":"numeric","prompt":"A turtle-bot starts facing North. It does: forward 3 steps, turn 90° clockwise, forward 2 steps, turn 90° clockwise. How many degrees has it turned in total?","answer":180,"explain":"The two turns are the only steps that matter for direction: 90° + 90° = 180°."},{"kind":"mcq","prompt":"Using the turtle-bot's moves above (starting North, turning a total of 180° clockwise), which direction does it finally face?","options":["North","East","West","South"],"answer":3,"explain":"A 180° turn from North flips it exactly to South."},{"kind":"numeric","prompt":"A turtle-bot facing East does this four times in a row: forward 1 step, then turn 90° clockwise. What is its total turning in degrees?","answer":360,"explain":"Four quarter turns of 90° each add up to 4 x 90° = 360°."},{"kind":"mcq","prompt":"After turning a full 360° in total, which direction does the turtle-bot face compared to where it started?","options":["The same direction it started facing","The exact opposite direction","It cannot be determined","A quarter turn away"],"answer":0,"explain":"A full 360° turn is one complete circle, so the turtle-bot ends up facing exactly where it began."}]},{"id":"at5","title":"Zig, Zag and the Mirror Turns","icon":"🤖","kind":"lesson","story":"Two rival robots, Zig and Zag, stand in the town square doing mirrored turns. Can you deduce which direction they started from, using only clues about their turns?","teach":[{"title":"Same turn size, opposite direction","body":"If two robots make a turn of the same size but in opposite directions (one clockwise, one anticlockwise), their final directions will usually differ — unless the clues say they end up the same.","visual":"🤖"},{"title":"Working backwards","body":"If you know where someone ends up facing and how much they turned, you can work backwards (undo the turn) to find their starting direction.","visual":"⏪"}],"questions":[{"kind":"mcq","prompt":"Zig took a quarter turn clockwise and Zag took a quarter turn anticlockwise. Both now face the same direction. If Zig ends up facing North, which direction was Zag facing at the start?","options":["South","West","East","Cannot be determined"],"answer":2,"explain":"Since Zag also ends up facing North after turning 90° anticlockwise, Zag must have started facing East (East - 90° anticlockwise = North)."},{"kind":"mcq","prompt":"Rohit is facing South. He makes a half turn clockwise. Which direction does he face now?","options":["South","North","West","East"],"answer":1,"explain":"South + 180° clockwise brings Rohit all the way around to face North."},{"kind":"mcq","prompt":"Sana ends up facing East after making one right-angle turn clockwise. Which direction was she originally facing?","options":["South","North","West","East"],"answer":1,"explain":"Undoing a 90° clockwise turn from East means going back 90° anticlockwise, which is North."},{"kind":"mcq","prompt":"Vik and Riya both start facing East. Vik makes one quarter turn clockwise. Riya makes one quarter turn anticlockwise. Are they now facing the same direction or opposite directions?","options":["Opposite directions","The same direction","Directions 90° apart","Cannot be determined"],"answer":0,"explain":"Vik ends up facing South and Riya ends up facing North — these are opposite directions."}]},{"id":"at6","title":"The Secret Combination Gate","icon":"🧮","kind":"lesson","story":"The final gate of Turn Town needs a secret combination — the exact net turn a robot must dial in. Add and subtract degrees like a pro to crack it open.","teach":[{"title":"Net turn","body":"If a robot turns several times, some clockwise and some anticlockwise, the 'net turn' is what is left after the opposite turns cancel out — add up the clockwise degrees, then subtract the anticlockwise degrees.","visual":"🧮"},{"title":"Turns bigger than 360°","body":"A turn of 450° looks confusing, but since one full circle is 360°, 450° is the same as one full turn (360°) plus another 90° — so it ends up facing the same as just a 90° turn.","visual":"🌀"}],"questions":[{"kind":"numeric","prompt":"A robot turns 120° clockwise, then 40° clockwise. What is its total clockwise turn in degrees?","answer":160,"explain":"Both turns go the same way, so add them: 120° + 40° = 160°."},{"kind":"numeric","prompt":"A robot turns 200° clockwise, then 50° anticlockwise. What is its net clockwise turn in degrees?","answer":150,"explain":"The anticlockwise turn cancels part of the clockwise turn: 200° - 50° = 150°."},{"kind":"numeric","prompt":"A robot makes a turn of 450° clockwise. This has the same final facing as a single turn of how many degrees clockwise?","answer":90,"explain":"450° is one full circle (360°) plus 90° extra, so it ends facing the same way as a 90° turn."},{"kind":"mcq","prompt":"A robot facing North turns 450° clockwise (equivalent to a 90° turn). Which direction does it end up facing?","options":["South","West","East","North"],"answer":2,"explain":"450° clockwise from North is the same as 90° clockwise, which is East."},{"kind":"numeric","prompt":"What is the MINIMUM number of quarter turns (90° each) needed to turn a robot all the way around to face the exact opposite direction?","answer":2,"explain":"Two quarter turns make 180°, which is exactly the opposite direction."}]},{"id":"at-boss","title":"Showdown with DJ Dizzy","icon":"🌀","kind":"boss","story":"DJ Dizzy the Spin-Bot has taken over Turn Town's central plaza, scrambling every signpost with wild spins. Only a true turn master can out-spin the champion and restore order!","boss":{"name":"DJ Dizzy the Spin-Bot","taunt":"Spin, twirl, whirl — try to keep up with my dizzying turns, if you can!"},"teach":[{"title":"Turn master checklist","body":"Remember: a full circle is 360°, clockwise goes North-East-South-West, anticlockwise goes the reverse, and to find a net turn you add clockwise degrees and subtract anticlockwise degrees.","visual":"🏆"}],"questions":[{"kind":"mcq","prompt":"A robot faces North and makes two right-angle turns clockwise. Which direction is it facing?","options":["North","East","West","South"],"answer":3,"explain":"Two 90° clockwise turns make 180°, turning North into South."},{"kind":"numeric","prompt":"How many degrees are in three quarter turns?","answer":270,"explain":"3 x 90° = 270°."},{"kind":"mcq","prompt":"Facing East, a turtle-bot turns 180° clockwise. Which direction does it face now?","options":["East","West","North","South"],"answer":1,"explain":"A half turn (180°) from East lands exactly on West."},{"kind":"numeric","prompt":"A robot turns 300° clockwise then 80° anticlockwise. What is its net clockwise turn in degrees?","answer":220,"explain":"300° - 80° = 220° net clockwise turn."},{"kind":"mcq","prompt":"Tia and Zoya both start facing South. Tia turns one quarter clockwise; Zoya turns one quarter anticlockwise. Do they end up facing the same direction or opposite directions?","options":["The same direction","Opposite directions","Directions 90° apart","Cannot be determined"],"answer":1,"explain":"Tia ends facing West and Zoya ends facing East — these are opposite directions."},{"kind":"numeric","prompt":"A robot turns 630° clockwise from North and ends up facing West. Ignoring full circles, what single turn in degrees (less than 360°) gives the same result?","answer":270,"explain":"630° - 360° (one full circle) = 270°, and 270° clockwise from North is indeed West."},{"kind":"mcq","prompt":"What is the minimum number of quarter turns needed for a robot to return to its exact starting direction?","options":["4","1","3","2"],"answer":0,"explain":"Four quarter turns of 90° add up to 360°, a full circle back to the start."}]}]},{"id":"travellers2_5","index":3,"name":"We the Travellers - II","subtitle":"Computational Thinking — Chapter 4","emoji":"🚆","palette":{"from":"#fb923c","to":"#7c2d12"},"lessons":[{"id":"wu1","title":"Two-Leg Journeys","icon":"🚗","kind":"lesson","story":"Chapter 1 got you from town to town — now the journeys have TWO legs! Join Arnav as he pedals, then drives, then hops a bus, and discover how far he really travels and how fast the WHOLE trip was, on average.","teach":[{"title":"Adding up the legs","body":"A journey can have more than one leg — first by car, then by bus, then on foot. To find the TOTAL distance, add up the distance of every leg. To find the TOTAL time, add up the time taken on every leg too.","visual":"➕"},{"title":"Average speed isn't just averaging the speeds!","body":"Average speed for a whole trip = TOTAL distance ÷ TOTAL time — never just the average of the individual speeds. Riding 30 km in 1 hour (30 km/h) then 30 km in 2 hours (15 km/h) does NOT average to 22.5 km/h. The correct average is 60 km ÷ 3 hours = 20 km/h.","visual":"⚡"}],"questions":[{"kind":"numeric","prompt":"A car travels 60 km in 1 hour, then 40 km in the next 40 minutes. What is the TOTAL distance travelled, in km?","answer":100,"explain":"60 km + 40 km = 100 km."},{"kind":"numeric","prompt":"For that same trip, what is the TOTAL time taken, in minutes?","answer":100,"explain":"60 minutes + 40 minutes = 100 minutes (1 hour 40 minutes)."},{"kind":"mcq","prompt":"What is the average speed for the whole trip (100 km in 100 minutes)?","options":["65 km/h","50 km/h","70 km/h","60 km/h"],"answer":3,"explain":"100 minutes is 5/3 of an hour; 100 km ÷ 5/3 hour = 60 km/h — both legs happened to be exactly 60 km/h."},{"kind":"mcq","prompt":"A cyclist rides 30 km in 1 hour, then 30 km in 2 more hours. What is her average speed for the WHOLE ride?","options":["20 km/h","25 km/h","22.5 km/h","15 km/h"],"answer":0,"explain":"Total distance 60 km ÷ total time 3 hours = 20 km/h — NOT the average of 30 km/h and 15 km/h."},{"kind":"numeric","prompt":"A bus travels 45 km in 1 hour, then 45 km in 2 more hours. What is the TOTAL distance, in km?","answer":90,"explain":"45 km + 45 km = 90 km."}]},{"id":"wu2","title":"Reading the Timetable","icon":"🕘","kind":"lesson","story":"The stationmaster at Junction Central has locked the timetable board, and only YOU can read it fast enough to plan the way through. Every minute between departure and arrival is a clue.","teach":[{"title":"Duration = later time − earlier time","body":"To find how long a journey takes, subtract the departure time from the arrival time. A train leaving at 9:15 and arriving at 10:40 takes 1 hour to reach 10:15, then 25 more minutes — 1 hour 25 minutes in total.","visual":"🕘"},{"title":"Reading a timetable","body":"A timetable lists the time a vehicle reaches each stop. The gap between two stops' times tells you the travel time for that stretch — and comparing two vehicles' total journey times tells you which one is faster.","visual":"📋"}],"questions":[{"kind":"mcq","prompt":"A train departs Station A at 9:15 and arrives at Station B at 10:40. How long is the journey?","options":["1 hr 15 min","2 hr 5 min","1 hr 25 min","1 hr 35 min"],"answer":2,"explain":"From 9:15 to 10:15 is 1 hour, then 10:15 to 10:40 is 25 more minutes — 1 hr 25 min total."},{"kind":"numeric","prompt":"How many minutes in total is that same journey (9:15 to 10:40)?","answer":85,"explain":"1 hour 25 minutes = 60 + 25 = 85 minutes."},{"kind":"numeric","prompt":"A bus leaves at 14:20 and the journey takes 50 minutes. At what HOUR (24-hour format) does it arrive? Enter just the hour number.","answer":15,"explain":"14:20 + 50 minutes = 15:10, so the hour is 15."},{"kind":"mcq","prompt":"Train X departs at 8:00 and arrives at 9:30. Train Y departs at 8:10 and arrives at 9:50. Which train takes LESS time to complete its journey?","options":["Train X","Train Y","Both take the same time","Cannot tell"],"answer":0,"explain":"Train X takes 1 hr 30 min (90 min); Train Y takes 1 hr 40 min (100 min) — Train X is faster."},{"kind":"numeric","prompt":"A timetable shows: Station A 9:00, Station B 9:35, Station C 10:05. How many minutes does it take to travel from B to C?","answer":30,"explain":"10:05 − 9:35 = 30 minutes."}]},{"id":"wu3","title":"Speed Detective","icon":"🔍","kind":"lesson","story":"A mystery speed-inspector visits three vehicles overnight and leaves only distance and time clues behind. Can you work out how fast each one was really going — and spot the impostor?","teach":[{"title":"The speed triangle","body":"Speed = Distance ÷ Time. Distance = Speed × Time. Time = Distance ÷ Speed. Cover up the one you want to find, and the other two show you how to calculate it.","visual":"🔺"},{"title":"Working backwards to a target","body":"If you know the average speed you WANT for a whole trip, you can find the total time allowed, subtract the time already used, and work out exactly how fast the rest of the trip must go.","visual":"🧩"}],"questions":[{"kind":"numeric","prompt":"A cyclist travels 45 km in 3 hours at a steady speed. What is her speed, in km/h?","answer":15,"explain":"Speed = Distance ÷ Time = 45 ÷ 3 = 15 km/h."},{"kind":"numeric","prompt":"A car travels at a steady 50 km/h for 3 hours. How far does it travel, in km?","answer":150,"explain":"Distance = Speed × Time = 50 × 3 = 150 km."},{"kind":"mcq","prompt":"A scooter takes 2 hours to cover 70 km at a steady speed. What speed is that?","options":["30 km/h","35 km/h","40 km/h","25 km/h"],"answer":1,"explain":"Speed = 70 ÷ 2 = 35 km/h."},{"kind":"numeric","prompt":"Rani wants her 120 km trip to take exactly 2 hours in total (an average of 60 km/h). She already drove 40 km in the first hour. What speed, in km/h, must she average for the LAST hour to finish exactly on time?","answer":80,"explain":"She has 120 − 40 = 80 km left, with only 1 hour left, so she must average 80 km/h."},{"kind":"mcq","prompt":"Three of these describe the SAME speed, and one is different. Which one is the ODD ONE OUT?","options":["60 km in 1 hour","120 km in 3 hours","30 km in 30 minutes","15 km in 15 minutes"],"answer":1,"explain":"120 km in 3 hours is 40 km/h, but the other three are all 60 km/h."}]},{"id":"wu4","title":"Choosing the Best Route","icon":"🗺️","kind":"lesson","story":"Two rival delivery apps each promise the 'best route' between towns — but only one is telling the truth. Add up the segments of every path and prove which one really is shorter.","teach":[{"title":"Comparing whole routes","body":"When there's more than one path between two places, add up the distances of EVERY segment on each path, then compare the totals — the smaller total is the shorter route.","visual":"🛣️"},{"title":"Order matters","body":"When visiting several stops before returning home, different ORDERS of visiting them can give completely different total distances. Try a few different orders and add up each one to find the shortest.","visual":"🔀"}],"questions":[{"kind":"mcq","prompt":"There are two routes from Town A to Town D. Route 1: A→B is 5 km, then B→D is 9 km. Route 2: A→C is 6 km, then C→D is 6 km. Which route is shorter?","options":["Route 2 (12 km)","Route 1 (14 km)","Both routes are equal","Cannot tell"],"answer":0,"explain":"Route 1 totals 5 + 9 = 14 km; Route 2 totals 6 + 6 = 12 km — Route 2 is shorter."},{"kind":"numeric","prompt":"Using Route 1 above (A→B→D), what is the total distance in km?","answer":14,"explain":"5 km + 9 km = 14 km."},{"kind":"numeric","prompt":"A courier visits 3 shops from a depot in this order and returns: Depot→Shop1 = 4 km, Shop1→Shop2 = 3 km, Shop2→Shop3 = 5 km, Shop3→Depot = 6 km. What is the TOTAL distance for this route?","answer":18,"explain":"4 + 3 + 5 + 6 = 18 km."},{"kind":"mcq","prompt":"A van at a Depot must visit shops X, Y, and Z, then return to the Depot. Distances: Depot–X = 3 km, Depot–Y = 7 km, Depot–Z = 5 km, X–Y = 4 km, X–Z = 6 km, Y–Z = 2 km. Compare Route A (Depot→X→Y→Z→Depot) and Route B (Depot→X→Z→Y→Depot). Which is shorter?","options":["Route A (14 km)","Route B (18 km)","Both routes are equal","Cannot tell"],"answer":0,"explain":"Route A: 3+4+2+5 = 14 km. Route B: 3+6+2+7 = 18 km. Route A is shorter."},{"kind":"numeric","prompt":"What is the total distance of Route B (Depot→X→Z→Y→Depot) from the question above, in km?","answer":18,"explain":"3 + 6 + 2 + 7 = 18 km."}]},{"id":"wu5","title":"Catching the Connection","icon":"🔁","kind":"lesson","story":"One missed minute means a missed train! Help travellers work out if they have enough time to dash across the platform and catch their connection.","teach":[{"title":"Layover time","body":"When changing from one bus, train, or flight to another, the gap between your arrival time and the next departure time is called the layover. Subtract the arrival time from the next departure time to find it.","visual":"⏳"},{"title":"Enough time to connect?","body":"Every connection needs a minimum changeover time to reach the next platform or gate. If the layover is GREATER than or equal to that minimum, the connection is made — if it's less, the connection is missed.","visual":"🏃"}],"questions":[{"kind":"mcq","prompt":"A train arrives at Junction at 10:45. The connecting train leaves at 11:05, and a passenger needs at least 15 minutes to change platforms. Can she catch it?","options":["Cannot tell","No — she has exactly 15 minutes, which isn't enough","No — she only has 10 minutes","Yes — she has 20 minutes, more than the 15 needed"],"answer":3,"explain":"11:05 − 10:45 = 20 minutes, which is more than the 15 minutes she needs."},{"kind":"numeric","prompt":"In that same situation, how many SPARE minutes does she have beyond the 15 minutes she needs?","answer":5,"explain":"20 minutes available − 15 minutes needed = 5 spare minutes."},{"kind":"mcq","prompt":"A bus arrives at 16:50. The connecting bus leaves at 17:05, and changing queues needs at least 20 minutes. Can the passenger catch it?","options":["No — she only has 15 minutes but needs 20","Cannot tell","Yes — she has 20 minutes","Yes — she has exactly enough time"],"answer":0,"explain":"17:05 − 16:50 = 15 minutes, which is less than the 20 minutes needed."},{"kind":"numeric","prompt":"How many MORE minutes would the passenger above have needed to catch that bus?","answer":5,"explain":"She needed 20 minutes but only had 15 — she was short by 5 minutes."},{"kind":"numeric","prompt":"A flight lands at 13:30. The connecting flight leaves at 14:50, and the minimum connection time required is 45 minutes. How many minutes of SPARE time will the passenger have beyond the minimum requirement?","answer":35,"explain":"14:50 − 13:30 = 80 minutes available. 80 − 45 = 35 spare minutes."}]},{"id":"wu6","title":"The Delivery Round","icon":"📦","kind":"lesson","story":"The postman has three parcels and only one delivery round to plan. Test every order of stops and discover the shortest loop back to the post office.","teach":[{"title":"Try every order","body":"With just a few stops, you can list every possible order of visiting them, add up the distance for each, and pick the order with the smallest total — this is exactly how a computer plans an efficient delivery route.","visual":"📦"},{"title":"From distance to time","body":"Once you know the shortest route's total distance, you can find how long the trip takes at a steady speed using Time = Distance ÷ Speed.","visual":"⏱️"}],"questions":[{"kind":"numeric","prompt":"A postman starts at the Post Office (O) and must visit shops A, B, and C once each before returning to O. Distances: O–A = 2 km, O–B = 4 km, O–C = 9 km, A–B = 5 km, A–C = 6 km, B–C = 7 km. What is the total distance for the route O→A→B→C→O?","answer":23,"explain":"2 + 5 + 7 + 9 = 23 km."},{"kind":"numeric","prompt":"Using the same distances, what is the total distance for the route O→A→C→B→O?","answer":19,"explain":"2 + 6 + 7 + 4 = 19 km."},{"kind":"numeric","prompt":"Using the same distances, what is the total distance for the route O→B→A→C→O?","answer":24,"explain":"4 + 5 + 6 + 9 = 24 km."},{"kind":"mcq","prompt":"Comparing the three routes above (23 km, 19 km, and 24 km), which route is the SHORTEST?","options":["All three are equal","O→B→A→C→O (24 km)","O→A→B→C→O (23 km)","O→A→C→B→O (19 km)"],"answer":3,"explain":"19 km is the smallest of the three totals."},{"kind":"numeric","prompt":"If the postman cycles the shortest route (19 km) at a steady speed of 38 km/h, how many MINUTES does the whole round trip take?","answer":30,"explain":"19 km ÷ 38 km/h = 0.5 hour = 30 minutes."}]},{"id":"wu-boss","title":"The Grand Interchange","icon":"🏆","kind":"boss","boss":{"name":"The Grand Interchange","taunt":"Multi-leg, multi-stop, multi-minute — I've got a puzzle for every wheel on your journey!"},"story":"All of Chapter 4's skills collide in one final challenge — legs of a journey, timetables, connections, and the smartest route of all. Show the Study Atlas you've mastered every trick!","teach":[],"questions":[{"kind":"numeric","prompt":"A bus travels 80 km in 2 hours, then 40 km in 1 more hour. What is the TOTAL distance travelled, in km?","answer":120,"explain":"80 km + 40 km = 120 km."},{"kind":"mcq","prompt":"For that same trip (120 km in 3 hours total), what is the average speed?","options":["35 km/h","60 km/h","45 km/h","40 km/h"],"answer":3,"explain":"120 km ÷ 3 hours = 40 km/h."},{"kind":"numeric","prompt":"A train departs at 9:40 and arrives at 11:05. How many minutes long is the journey?","answer":85,"explain":"9:40 to 11:05 is 1 hour 25 minutes = 85 minutes."},{"kind":"mcq","prompt":"That train's passenger needs a connecting train that leaves at 11:30, and needs at least 20 minutes to change platforms. Can she catch it?","options":["Cannot tell","No — she only has 15 minutes","Yes — she has 25 minutes, more than the 20 needed","No — she has exactly 20 minutes"],"answer":2,"explain":"11:30 − 11:05 = 25 minutes, more than the 20 minutes she needs."},{"kind":"mcq","prompt":"Route 1 to a shop totals 22 km. Route 2 to the same shop totals 18 km. Which route is shorter?","options":["Route 2 (18 km)","Route 1 (22 km)","Both routes are equal","Cannot tell"],"answer":0,"explain":"18 km is less than 22 km."},{"kind":"numeric","prompt":"Distances: Depot–P = 3 km, Depot–Q = 5 km, P–Q = 4 km. What is the total distance of the round trip Depot→P→Q→Depot?","answer":12,"explain":"3 + 4 + 5 = 12 km."},{"kind":"numeric","prompt":"A cyclist wants his 90 km trip to average 30 km/h overall (so it must take exactly 3 hours). He already cycled 50 km in the first 2 hours. What speed, in km/h, must he average for the LAST hour to finish exactly on time?","answer":40,"explain":"He has 90 − 50 = 40 km left, with only 1 hour left, so he must average 40 km/h."}]}]},{"id":"farandnear5","index":4,"name":"Far and Near","subtitle":"Computational Thinking — Chapter 5","emoji":"📍","palette":{"from":"#facc15","to":"#713f12"},"lessons":[{"id":"fn1","title":"Closer or Farther?","icon":"📏","kind":"lesson","story":"Professor Locus has lost her map of Farlan Village and needs you to figure out who lives closer to the school gate using nothing but clues whispered by the villagers. Sharpen your reasoning — no ruler allowed!","teach":[{"title":"Comparing distances with clues","body":"When you know one distance and how much longer or shorter another one is, you can find it by adding or subtracting. If Amit stands 5 m from a tree and Priya stands 3 m farther from the tree than Amit, Priya is 5 + 3 = 8 m away.","visual":"📏"},{"title":"Chains of clues","body":"Sometimes clues only tell you an ORDER, not exact numbers — like 'Sam is closer than Tia, and Tia is closer than Uma.' Lining up these clues in a row tells you who is closest and who is farthest, even without measuring anything.","visual":"🔗"}],"questions":[{"kind":"numeric","prompt":"Kabir lives 900 m from the park. Zara lives 250 m closer to the park than Kabir. How far does Zara live from the park, in metres?","answer":650,"explain":"900 m minus 250 m closer gives 650 m."},{"kind":"mcq","prompt":"Aria lives 1,200 m from the library. Dev lives 300 m farther from the library than Aria. Who lives closer to the library?","options":["Aria","They live the same distance away","Dev","Cannot tell"],"answer":0,"explain":"Dev's distance is 1,200 + 300 = 1,500 m, which is farther than Aria's 1,200 m, so Aria lives closer."},{"kind":"numeric","prompt":"Neha stands 40 m from the gate. Omar stands 15 m farther from the gate than Neha. How far is Omar from the gate, in metres?","answer":55,"explain":"40 m + 15 m = 55 m."},{"kind":"mcq","prompt":"Sam lives closer to school than Tia. Tia lives closer to school than Uma. Who lives farthest from school?","options":["Cannot tell","Tia","Uma","Sam"],"answer":2,"explain":"The chain Sam < Tia < Uma (in distance) shows Uma is farthest away."}]},{"id":"fn2","title":"Ordering by Distance","icon":"📊","kind":"lesson","story":"The village well has run dry, and four houses are arguing about who should fetch water first — whoever lives closest should go! Help Farlan's water council put every house in the correct order.","teach":[{"title":"Reading a distance table","body":"When several distances are listed, ordering them is just like ordering numbers: the smallest number is the closest, and the largest number is the farthest. Compare them carefully, one pair at a time.","visual":"📋"},{"title":"Ordering without exact numbers","body":"Sometimes you only have 'closer than' clues linking people together, with no numbers at all. You can still build a full order by chaining the clues from closest to farthest, just like links in a chain.","visual":"🧩"}],"questions":[{"kind":"mcq","prompt":"Four houses are these distances from the well: House A — 320 m, House B — 280 m, House C — 410 m, House D — 295 m. Which house is closest to the well?","options":["House B","House C","House D","House A"],"answer":0,"explain":"280 m (House B) is the smallest of the four distances."},{"kind":"mcq","prompt":"Using the same four houses, which list correctly orders them from FARTHEST to CLOSEST?","options":["C, A, D, B","A, B, C, D","B, D, A, C","D, C, B, A"],"answer":0,"explain":"In order: C (410 m), A (320 m), D (295 m), B (280 m) — farthest to closest."},{"kind":"numeric","prompt":"Using the same table, how many metres closer is House B to the well than House C?","answer":130,"explain":"410 m − 280 m = 130 m."},{"kind":"mcq","prompt":"Priya is closer to the market than Rohan. Rohan is closer to the market than Sana. Sana is closer to the market than Tom. Who is farthest from the market?","options":["Tom","Sana","Rohan","Priya"],"answer":0,"explain":"The chain Priya < Rohan < Sana < Tom (in distance) puts Tom farthest away."}]},{"id":"fn3","title":"The Tied Goat","icon":"🐐","kind":"lesson","story":"Farlan's mischievous goat, Bella, is tied to a pole in the meadow. Villagers keep asking if she can reach this snack or that flower bed — and you're the only one who can work it out without walking all the way there.","teach":[{"title":"How far can a tied animal go?","body":"An animal tied with a rope of a certain length to a fixed pole can reach ANY point that is that distance or LESS from the pole. If the rope is 8 m long, the animal can reach anything within 8 m of the pole, but nothing farther.","visual":"🪢"}],"questions":[{"kind":"mcq","prompt":"Bella the goat is tied to a pole with an 8 m rope in an open field. A basket of hay is placed 6 m from the pole. Can Bella reach the hay?","options":["Only if Bella pulls harder","No, because 6 is less than 8","Yes, because 6 m is less than the 8 m rope","Cannot tell without knowing Bella's size"],"answer":2,"explain":"Since 6 m is within the 8 m rope's reach, Bella can reach the hay."},{"kind":"mcq","prompt":"The same goat (8 m rope) has a flower bed placed 11 m from the pole. Can Bella reach the flower bed?","options":["Only sometimes, depending on the flowers","Yes, ropes can always stretch","No, 11 m is farther than the 8 m rope","Yes, 11 m is closer than 8 m"],"answer":2,"explain":"11 m is beyond the 8 m the rope allows, so Bella cannot reach it."},{"kind":"numeric","prompt":"A dog is tied with a 12 m rope to a pole in a field. What is the farthest distance, in metres, the dog can ever be from the pole?","answer":12,"explain":"The rope allows the dog to reach anywhere up to, but not beyond, 12 m from the pole."},{"kind":"mcq","prompt":"A cat is tied to a pole with a 10-foot rope (assume the cat's body length is negligible). A bowl of milk is placed 15 feet away from wherever the cat happens to be STANDING at that moment. Can the cat always reach the milk?","options":["Yes, but only at noon","Sometimes yes, sometimes no — it depends on exactly where the milk is placed","Definitely no, never","Definitely yes, every time"],"answer":1,"explain":"The milk's position is described relative to the cat's current spot, not the pole — so whether it falls within the rope's reach depends entirely on which direction it was placed."}]},{"id":"fn4","title":"Grid Steps","icon":"🗺️","kind":"lesson","story":"An old treasure map of Farlan shows streets laid out in a perfect grid — no shortcuts through walls allowed! Count every block carefully to trace the explorer's true path.","teach":[{"title":"Counting steps on a grid","body":"On a city grid, you can only walk along the streets — never diagonally through buildings. If you walk 3 blocks east then 4 blocks north, you have walked 3 + 4 = 7 blocks in total, even though a straight line between start and finish would be shorter.","visual":"🧭"}],"questions":[{"kind":"numeric","prompt":"On a city grid, Aisha walks 3 blocks east then 4 blocks north to reach the library. How many blocks did she walk in total?","answer":7,"explain":"3 blocks + 4 blocks = 7 blocks walked along the grid."},{"kind":"numeric","prompt":"Rahul walks 6 blocks south then 6 blocks west to reach the market, moving only along the grid streets. How many blocks did he walk in total?","answer":12,"explain":"6 blocks + 6 blocks = 12 blocks."},{"kind":"mcq","prompt":"Which walking path covers FEWER blocks in total: Path 1 (5 blocks east + 5 blocks north), or Path 2 (3 blocks east + 3 blocks north + 3 blocks east)?","options":["Path 2 (9 blocks total)","Path 1 (9 blocks total)","Both are equal","Cannot tell without more information"],"answer":0,"explain":"Path 1 totals 5 + 5 = 10 blocks, while Path 2 totals 3 + 3 + 3 = 9 blocks — Path 2 is fewer."},{"kind":"numeric","prompt":"A treasure map says: start at the gate, walk 8 blocks north, then 5 blocks east, then 3 blocks south. How many blocks did the explorer walk in total (count every block moved, even the ones that double back)?","answer":16,"explain":"8 + 5 + 3 = 16 blocks walked in total."}]},{"id":"fn5","title":"Meeting in the Middle","icon":"🏃","kind":"lesson","story":"Two of Farlan's fastest runners are racing towards each other from opposite ends of the town field, and a curious snail is inching its way toward a lettuce leaf. Track every step — the answer might surprise you!","teach":[{"title":"Net movement","body":"When something moves forward and then backward again and again, its ACTUAL distance from the start is found by adding every forward move and subtracting every backward move — this is called the net movement.","visual":"🐌"},{"title":"Watch out for tricks!","body":"If two people start at opposite ends of a field and run towards each other, the moment they MEET, they are standing at the very same spot — so they are always exactly the same distance from anything else on the field, no matter their speeds!","visual":"🏁"}],"questions":[{"kind":"numeric","prompt":"A snail crawls forward 5 cm in the first minute, then slides backward 2 cm in the second minute, and repeats this pattern. How far from the start, in cm, is the snail after 6 minutes (three full forward-backward cycles)?","answer":9,"explain":"Each 2-minute cycle gains 5 − 2 = 3 cm net. Three cycles (6 minutes) give 3 × 3 = 9 cm."},{"kind":"mcq","prompt":"Using the same snail (forward 5 cm, then back 2 cm, repeating), how far has it net-moved after 4 minutes (two full cycles)?","options":["9 cm","14 cm","3 cm","6 cm"],"answer":3,"explain":"Two cycles at 3 cm net gain each give 2 × 3 = 6 cm."},{"kind":"mcq","prompt":"Vik and Om stand at opposite ends of a 90 m field, 90 m apart, and start running towards each other at the same time. Vik runs twice as fast as Om. A ball lies exactly at the centre of the field. When Vik and Om meet, who is farther from the ball?","options":["Om, because he is slower","Cannot tell without exact speeds","They are the same distance from the ball — they meet at the same spot!","Vik, because he ran farther to get there"],"answer":2,"explain":"The instant they meet, both runners are standing at the exact same point on the field, so their distance from the ball must be equal — speeds don't matter once they're together."},{"kind":"numeric","prompt":"Two joggers start together and jog in opposite directions along a straight path. One jogs 6 m every minute, the other jogs 4 m every minute. After 5 minutes, how far apart are they, in metres?","answer":50,"explain":"Together they separate by 6 + 4 = 10 m every minute, so after 5 minutes they are 10 × 5 = 50 m apart."}]},{"id":"fn6","title":"Smart Estimation","icon":"🤔","kind":"lesson","story":"Farlan's map is torn, and all that's left are rough guesses from different travellers. Can you combine their clues to pin down the exact distance — and estimate quickly when an exact number isn't needed?","teach":[{"title":"Overlapping clues","body":"When two people give a RANGE for the same distance, the true distance must fit inside BOTH ranges at once. Finding where the ranges overlap narrows things down — sometimes to a single whole number.","visual":"🔍"},{"title":"Rounding for a quick estimate","body":"To round a distance to the nearest kilometre, look at the metres left over. 500 m or more rounds UP to the next km; less than 500 m rounds DOWN. This gives a fast, close-enough answer without needing the exact number.","visual":"📏"}],"questions":[{"kind":"numeric","prompt":"Aditi thinks the distance between two villages is more than 4 km but less than 8 km. Bilal thinks it is more than 6 km but less than 10 km. If both are correct, and the distance is a whole number of km, what is the distance?","answer":7,"explain":"The two ranges overlap only between 6 km and 8 km, and the only whole number there is 7 km."},{"kind":"numeric","prompt":"Using the 7 km distance from before, if a taxi charges ₹9 per km, how much would the ride cost in ₹?","answer":63,"explain":"7 × 9 = 63."},{"kind":"mcq","prompt":"The exact distance from Meena's home to her cousin's home is 4,870 m. Rounded to the nearest kilometre, about how far is that?","options":["6 km","5 km","4.5 km","4 km"],"answer":1,"explain":"4,870 m has 870 m left over, which is 500 m or more, so it rounds up to 5,000 m = 5 km."},{"kind":"mcq","prompt":"Zoya guesses a rope's length is more than 10 m but less than 15 m. Kabir guesses it is more than 11 m but less than 18 m. If both guesses are correct, which of these lengths could NOT be the rope's length?","options":["12 m","14 m","13 m","11 m"],"answer":3,"explain":"11 m fails Kabir's clue, since the rope must be MORE than 11 m — so 11 m is impossible, while 12, 13, and 14 m all satisfy both clues."}]},{"id":"fn-boss","title":"The Far and Near Challenge","icon":"🏆","kind":"boss","boss":{"name":"The Far and Near Challenge","taunt":"Clues, ropes, grids, and tricky meetings — prove you can measure Farlan from every angle!"},"story":"Professor Locus has one final test before she can redraw Farlan's complete map: a mix of every distance puzzle you've solved so far. Stay sharp — some questions have a trick hiding inside!","teach":[],"questions":[{"kind":"numeric","prompt":"Yusuf lives 750 m from the market. Priya lives 180 m farther from the market than Yusuf. How far does Priya live from the market, in metres?","answer":930,"explain":"750 m + 180 m = 930 m."},{"kind":"mcq","prompt":"Four shops' distances from the bus stop are: Shop P — 640 m, Shop Q — 590 m, Shop R — 705 m, Shop S — 610 m. Which shop is farthest from the bus stop?","options":["Shop P","Shop S","Shop R","Shop Q"],"answer":2,"explain":"705 m (Shop R) is the largest of the four distances."},{"kind":"mcq","prompt":"A calf is tied to a post with a 9 m rope in an open field. A trough of water is placed 7 m from the post. Can the calf reach the water?","options":["No, because 7 is less than 9","Cannot tell without knowing the calf's size","Only if the calf stretches its neck","Yes, because 7 m is less than the 9 m rope"],"answer":3,"explain":"7 m is within the 9 m the rope allows, so the calf can reach the water."},{"kind":"numeric","prompt":"On a city grid, walking only along streets, Tara walks 6 blocks north then 9 blocks east to reach the museum. How many blocks did she walk in total?","answer":15,"explain":"6 + 9 = 15 blocks."},{"kind":"mcq","prompt":"Two cyclists start at opposite ends of a 100 m lane and cycle towards each other, one twice as fast as the other. A flag is planted exactly at the middle of the lane. When the two cyclists meet, who is closer to the flag?","options":["The slower cyclist","The faster cyclist","They are the same distance from the flag — they meet at the same spot!","Cannot tell without exact speeds"],"answer":2,"explain":"At the moment they meet, both cyclists are standing at the exact same point, so they are always the same distance from the flag."},{"kind":"numeric","prompt":"Sana thinks a hiking trail is more than 5 km but less than 9 km. Devika thinks it is more than 7 km but less than 12 km. If both are right, and the trail length is a whole number of km, how many km is the trail?","answer":8,"explain":"The ranges overlap only between 7 km and 9 km, and the only whole number there is 8 km."},{"kind":"mcq","prompt":"A road is exactly 3,240 m long. Rounded to the nearest kilometre, how long is it?","options":["3 km","4 km","2 km","3.5 km"],"answer":0,"explain":"3,240 m has only 240 m left over, less than 500 m, so it rounds down to 3,000 m = 3 km."}]}]},{"id":"dairyfarm5","index":5,"name":"The Dairy Farm","subtitle":"Computational Thinking — Chapter 6","emoji":"🐄","palette":{"from":"#4ade80","to":"#14532d"},"lessons":[{"id":"df1","title":"Milking Time Mix-up","icon":"🥛","kind":"lesson","story":"The sun rises over Sunflower Dairy Farm, and Moo-nager Bessie needs your help! The morning milk delivery is a jumble of cans and chores — can you break the big job into small, clear pieces before the milk truck arrives?","teach":[{"title":"Breaking Big Jobs into Small Steps","body":"Decomposition means splitting one big task into smaller, ordered steps that are easier to solve one at a time. On a dairy farm, 'make butter' becomes collect, churn, gather, and pack.","visual":"🧩"}],"questions":[{"kind":"numeric","prompt":"Farmer Amma has 4 milk cans, each holding 25 litres. She pours out 8 litres from every can to sell at the farm gate. How many litres are left in total across all 4 cans?","answer":68,"explain":"4 cans × 25 L = 100 L collected; 4 × 8 L = 32 L poured out; 100 − 32 = 68 L left."},{"kind":"mcq","prompt":"Ravi is decomposing the task 'Turn milk into butter' into ordered steps. Which order is correct?","options":["Pack the butter, collect the milk, churn the cream, gather it","Gather the butter, collect the milk, pack it, churn the cream","Churn the cream, pack the butter, collect the milk, gather it","Collect the milk, churn the cream, gather the butter, pack it"],"answer":3,"explain":"Steps must follow the order they naturally happen in — you can't churn cream before collecting the milk."},{"kind":"mcq","prompt":"Which of these is the best example of decomposition being used on the farm?","options":["Counting the total litres collected in a week","Guessing how many cows are on the farm","Splitting 'clean the barn' into sweep the floor, wash the troughs, and refill the hay","Painting all the milk cans the same colour"],"answer":2,"explain":"Decomposition breaks one big chore into smaller, manageable pieces."},{"kind":"numeric","prompt":"A dairy has 9 milk crates, each holding 12 pouches. If 5 pouches are removed from every crate to check quality, how many pouches remain in total?","answer":63,"explain":"9 × 12 = 108 pouches; 9 × 5 = 45 removed; 108 − 45 = 63 remain."}]},{"id":"df2","title":"The Rate of the Herd","icon":"🐄","kind":"lesson","story":"Deep in the milking shed, the old Rate Keeper robot hums the same rhythm every morning: 'every cow gives the same each day!' Learn to use that steady rhythm to solve any counting puzzle the herd throws at you.","teach":[{"title":"What is a Rate?","body":"A rate tells you how much of something happens for each single unit — like litres per cow, per day. Once you know the rate, you can find totals or missing numbers by multiplying or dividing.","visual":"⚖️"}],"questions":[{"kind":"numeric","prompt":"Each cow on the farm gives 8 litres of milk a day. How many cows are needed to collect 56 litres in one day?","answer":7,"explain":"56 ÷ 8 = 7 cows."},{"kind":"numeric","prompt":"A cow gives 6 litres in the morning and 5 litres in the evening. How many litres does it give over 4 days?","answer":44,"explain":"11 litres a day × 4 days = 44 litres."},{"kind":"numeric","prompt":"The farm has 12 cows, and each gives 7 litres a day. How many litres are collected from all the cows in one day?","answer":84,"explain":"12 × 7 = 84 litres."},{"kind":"mcq","prompt":"Which best describes a 'rate' on the dairy farm?","options":["The total litres given by the whole herd together","The colour of the milk can","The amount of milk one cow gives in one day","The total number of cows on the farm"],"answer":2,"explain":"A rate is a fixed amount per single unit, like litres per cow per day."}]},{"id":"df3","title":"Cartons and Crates","icon":"📦","kind":"lesson","story":"The delivery van is waiting, and crates are piling up by the gate! Help packer Rosy figure out the fewest crates and trips needed to get every drop of milk to town without wasting a single crate.","teach":[{"title":"Solving Step-by-Step Puzzles","body":"Some problems have many small parts, like different pouch sizes or trip limits. Solve them by working out each part separately, then combining the answers.","visual":"🚚"}],"questions":[{"kind":"numeric","prompt":"Each crate holds either 8 Toned Milk pouches or 10 Full-Cream Milk pouches, never mixed together. The dairy has 40 Toned Milk pouches and 30 Full-Cream Milk pouches, and every crate used must be completely full. What is the minimum number of crates needed in total?","answer":8,"explain":"40 ÷ 8 = 5 crates for Toned Milk, and 30 ÷ 10 = 3 crates for Full-Cream Milk, so 5 + 3 = 8 crates."},{"kind":"numeric","prompt":"A milk tanker can carry 500 litres per trip. The farm has 1850 litres to send to the city. What is the minimum number of trips needed?","answer":4,"explain":"1850 ÷ 500 = 3.7, so the tanker needs a 4th trip to carry the leftover milk."},{"kind":"numeric","prompt":"A milk van visits 3 villages. It picks up 45 litres at the first village, then 30 litres at the second. At the second village, 15 litres already collected turn out to be spoiled and are thrown away. Then it picks up 25 litres at the third village. How many litres of good milk does the van have after the third village?","answer":85,"explain":"45 + 30 = 75, minus 15 spoiled = 60, plus 25 collected = 85 litres."},{"kind":"mcq","prompt":"Why is it helpful to break a big delivery problem like 'get milk from the farm to 5 shops' into smaller steps?","options":["Because each small part becomes easier to plan, solve, and check","Because it makes the milk taste better","Because it uses fewer numbers","Because the van moves faster"],"answer":0,"explain":"Breaking a big problem into steps makes it easier to manage and check for mistakes."}]},{"id":"df4","title":"Patterns in the Milk Ledger","icon":"📈","kind":"lesson","story":"The farm's old ledger book is full of numbers, and its rows hide a secret pattern! Spot the rule connecting the numbers, and you'll be able to predict tomorrow's milk count before it's even collected.","teach":[{"title":"Finding the Hidden Rule","body":"Pattern recognition means noticing how numbers change together and figuring out the rule that connects them, like 'day number times ten'. Once you know the rule, you can predict what comes next.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"The farmer records milk daily: Day 1 = 10 L, Day 2 = 20 L, Day 3 = 30 L, Day 4 = 40 L. Which rule matches this pattern?","options":["Litres = Day number × 10","Litres = 40 − Day number","Litres = Day number + 10","Litres = Day number × 5"],"answer":0,"explain":"Each day's litres is exactly the day number multiplied by 10."},{"kind":"numeric","prompt":"Using the rule 'Litres = Day number × 10', how many litres will be recorded on Day 8?","answer":80,"explain":"8 × 10 = 80 litres."},{"kind":"mcq","prompt":"A chart shows: 2 cows → 16 L, 3 cows → 24 L, 4 cows → 32 L. Which rule matches this pattern?","options":["Litres = 32 − Number of cows","Litres = Number of cows × 6","Litres = Number of cows + 8","Litres = Number of cows × 8"],"answer":3,"explain":"Each cow contributes 8 litres, so litres = number of cows × 8."},{"kind":"numeric","prompt":"Using the rule 'Litres = Number of cows × 8', how many litres would 10 cows give?","answer":80,"explain":"10 × 8 = 80 litres."}]},{"id":"df5","title":"The Milk Yield Mystery","icon":"🕵️","kind":"lesson","story":"Three cows, Motu, Chotu and Dolly, share the same stalls but their milk totals are a mystery! Use the clues the farmhand left behind to deduce exactly how much each cow really gives.","teach":[{"title":"Using Clues to Deduce","body":"Deduction means using known facts and relationships to figure out an unknown number, like solving a mini mystery with math. Work through the clues one at a time.","visual":"🧠"}],"questions":[{"kind":"numeric","prompt":"Motu, Chotu and Dolly give 70 litres in total. Motu gives twice as much as Chotu. Dolly gives 10 litres more than Chotu. How many litres does Chotu give?","answer":15,"explain":"Let Chotu = x. Then Motu = 2x and Dolly = x + 10, so x + 2x + (x + 10) = 70, which gives 4x = 60 and x = 15."},{"kind":"numeric","prompt":"Using the same clues (total 70 L, Motu = twice Chotu, Dolly = Chotu + 10), how many litres does Dolly give?","answer":25,"explain":"Chotu gives 15 litres, so Dolly gives 15 + 10 = 25 litres."},{"kind":"numeric","prompt":"Two milk cans, A and B, feed a mixing tank. The tank's total litres equal can A's litres multiplied by can B's litres. If the tank shows 42 litres and can A has 6 litres, how many litres does can B have?","answer":7,"explain":"42 ÷ 6 = 7 litres."},{"kind":"mcq","prompt":"What CT skill did you use to work out each cow's exact share from clues about totals and relationships?","options":["Randomly guessing numbers","Logical reasoning (deduction) using the given clues","Copying yesterday's totals","Ignoring the clues and averaging"],"answer":1,"explain":"Deduction uses known facts step by step to work out an unknown value."}]},{"id":"df6","title":"Barn Stalls and Empty Pens","icon":"🏚️","kind":"lesson","story":"Storm winds scattered the cows last night, and now some stalls sit empty! Count carefully using rows and columns instead of stall by stall, and you'll finish before evening milking begins.","teach":[{"title":"Counting Smartly with Rows and Columns","body":"Instead of counting one by one, find how many rows and columns are filled and multiply them. This systematic counting saves time and avoids mistakes.","visual":"🔢"}],"questions":[{"kind":"numeric","prompt":"The barn has stalls arranged in 5 rows (1-5) and 6 columns (A-F) — 30 stalls in total. Row 3 is completely empty, and columns B and E are completely empty too. Every other stall has a cow. How many stalls have a cow?","answer":16,"explain":"The occupied rows (1, 2, 4, 5 — that's 4 rows) times the occupied columns (A, C, D, F — that's 4 columns) equal 16 stalls."},{"kind":"numeric","prompt":"If the cows return to Row 3 but columns B and E stay empty, how many stalls now have a cow?","answer":20,"explain":"The previous 16 stalls plus Row 3's 4 newly occupied stalls (excluding columns B and E) equal 20."},{"kind":"mcq","prompt":"Which counting strategy helps you find 'how many stalls have a cow' without counting one by one?","options":["Randomly guess a number","Multiply the number of occupied rows by the number of occupied columns","Add up all the row numbers","Only count column A"],"answer":1,"explain":"Multiplying occupied rows by occupied columns quickly gives the total filled cells in a grid."},{"kind":"numeric","prompt":"A feed store has trays arranged in 4 rows and 4 columns (16 trays total). The entire top row and the entire rightmost column are empty. How many trays have feed?","answer":9,"explain":"Empty trays = 4 (top row) + 4 (right column) − 1 (the corner tray counted twice) = 7, so filled trays = 16 − 7 = 9."}]},{"id":"df-boss","title":"The Great Dairy Challenge","icon":"🧌","kind":"boss","story":"The Curd Crumbler has scrambled every ledger, crate count, and barn chart on the farm! Prove you've mastered every dairy skill — rates, groups, patterns, deductions and counting — to restore order before sundown.","teach":[{"title":"Review: All Your Dairy Skills","body":"You've learned to decompose big jobs, use rates, solve multi-step puzzles, spot patterns, deduce hidden numbers, and count smartly with grids. Now put them all together!","visual":"🏆"}],"boss":{"name":"The Curd Crumbler","taunt":"Ha! Numbers are just curds and whey to me — think you can un-scramble my mess?"},"questions":[{"kind":"numeric","prompt":"The farm has 9 cows, each giving 7 litres a day. How many litres does the farm collect in one day?","answer":63,"explain":"9 × 7 = 63 litres."},{"kind":"numeric","prompt":"162 litres of milk must be poured into cans holding 18 litres each, with every can completely full. How many cans are needed?","answer":9,"explain":"162 ÷ 18 = 9 cans."},{"kind":"mcq","prompt":"Which set of steps correctly decomposes the task 'Deliver milk to the market'?","options":["Drive to market, collect the milk, unload the crates, load the van","Unload the crates, load the van, drive to market, collect the milk","Load the van, unload the crates, collect the milk, drive to market","Collect the milk, load the van, drive to market, unload the crates"],"answer":3,"explain":"Each step must follow the one before it logically: collect first, then load, then drive, then unload."},{"kind":"numeric","prompt":"A dairy packs pouches into crates. Each crate holds either 5 Cow Milk pouches or 8 Buffalo Milk pouches, never mixed. There are 35 Cow Milk pouches and 24 Buffalo Milk pouches, and every crate used must be full. What is the total minimum number of crates needed?","answer":10,"explain":"35 ÷ 5 = 7 crates for Cow Milk, and 24 ÷ 8 = 3 crates for Buffalo Milk, so 7 + 3 = 10 crates."},{"kind":"numeric","prompt":"The record chart shows Day 1 = 12 L, Day 2 = 24 L, Day 3 = 36 L. Following the same pattern, how many litres will Day 6 show?","answer":72,"explain":"The rule is litres = day number × 12, so Day 6 gives 6 × 12 = 72 litres."},{"kind":"numeric","prompt":"Two cows, X and Y, together give 45 litres. X gives twice as much as Y. How many litres does Y give?","answer":15,"explain":"Let Y = x, so X = 2x. Then x + 2x = 45, giving 3x = 45 and x = 15."},{"kind":"mcq","prompt":"Which best describes 'rate-based reasoning', as used all over the dairy farm?","options":["Using a fixed amount per unit, like litres per cow, to find totals or missing numbers","Ignoring the numbers and guessing","Only working with whole farms, never single cows","Counting every single litre one at a time forever"],"answer":0,"explain":"Rate-based reasoning uses a steady amount per unit to quickly find totals or unknowns."}]}]},{"id":"shapesandpatterns5","index":6,"name":"Shapes and Patterns","subtitle":"Computational Thinking — Chapter 7","emoji":"🔺","palette":{"from":"#22d3ee","to":"#164e63"},"lessons":[{"id":"sp1","title":"Guess My Shape","icon":"🔷","kind":"lesson","story":"A mysterious riddle-writer has locked the gate to Pattern Peak with word-clues about shapes instead of pictures. Read each clue carefully and name the shape to unlock the path!","teach":[{"title":"Naming shapes from clues","body":"Shapes can be described completely in words: how many sides they have, how many corners (vertices), whether the sides are equal, and whether the angles are right angles. A triangle has 3 sides, a quadrilateral has 4, a pentagon has 5, and a hexagon has 6.","visual":"🔷"},{"title":"Same number of sides, different shapes","body":"Many shapes share the same number of sides but are still different! A square, a rectangle, and a rhombus all have 4 sides, but only a square has both equal sides AND right angles. Look at every clue before you decide.","visual":"🧩"}],"questions":[{"kind":"mcq","prompt":"I have 4 sides. All my sides are equal in length, but none of my angles is a right angle. What shape am I?","options":["Rhombus","Rectangle","Trapezium","Square"],"answer":0,"explain":"A rhombus has 4 equal sides but its angles are not right angles, unlike a square."},{"kind":"mcq","prompt":"I have exactly 3 sides, and none of my sides are the same length as any other. What kind of triangle am I?","options":["Scalene triangle","Isosceles triangle","Right triangle","Equilateral triangle"],"answer":0,"explain":"A scalene triangle has all three sides of different lengths."},{"kind":"numeric","prompt":"A regular hexagon has 6 equal sides. How many corners (vertices) does it have?","answer":6,"explain":"A hexagon always has the same number of corners as sides: 6."},{"kind":"mcq","prompt":"I have 4 sides. My opposite sides are equal and parallel, and all my angles are right angles — but not all four of my sides are equal. What shape am I?","options":["Square","Rectangle","Parallelogram with no right angles","Rhombus"],"answer":1,"explain":"A rectangle has right angles and equal opposite sides, but its length and width are usually different, so all 4 sides are not equal."},{"kind":"numeric","prompt":"A shape has exactly one more side than a pentagon. How many sides does it have?","answer":6,"explain":"A pentagon has 5 sides, so one more side makes 6 — a hexagon."}]},{"id":"sp2","title":"Crack the Pattern Code","icon":"🔁","kind":"lesson","story":"The bridge across Rule River only appears if you can predict what comes next in its shifting shape-patterns. Find the hidden repeating rule to make the bridge solid!","teach":[{"title":"Finding the repeating rule","body":"A pattern is a sequence that follows a fixed rule, often a small group of items that repeats again and again, like circle-square-triangle, circle-square-triangle. Find the smallest repeating group — that's the 'rule' of the pattern.","visual":"🔁"},{"title":"Predicting far ahead","body":"To find a shape far down a pattern (like the 20th item), count how many items are in one repeating group, then think about where that position number would land inside one group. You don't have to draw all 20!","visual":"🔢"}],"questions":[{"kind":"mcq","prompt":"Look at this pattern: circle, square, triangle, circle, square, triangle, circle, square, ___. What comes next?","options":["Triangle","Circle","Square","Pentagon"],"answer":0,"explain":"The repeating group is circle-square-triangle, so after square comes triangle."},{"kind":"mcq","prompt":"The pattern circle, square, triangle repeats forever, starting at position 1 with circle. Which shape is in the 20th position?","options":["Triangle","Circle","Square","Cannot be determined"],"answer":2,"explain":"The group has 3 shapes. 20 divided by 3 leaves a remainder of 2, and the 2nd shape in the group is square."},{"kind":"mcq","prompt":"Look at this pattern: triangle, triangle, square, triangle, triangle, square, triangle, triangle, ___. What comes next?","options":["Triangle","Circle","Square","Pentagon"],"answer":2,"explain":"The repeating group is triangle-triangle-square, so after two triangles comes a square."},{"kind":"numeric","prompt":"A pattern of shapes gains one more side each time: a triangle (3 sides), then a square (4 sides), then a pentagon (5 sides), and so on. Following this rule, how many sides will the 7th shape in the pattern have?","answer":9,"explain":"The 1st shape has 3 sides, so the 7th shape has 3 + 6 = 9 sides."},{"kind":"mcq","prompt":"What do we call a clear, step-by-step rule that tells you exactly how to continue or build a pattern?","options":["A coincidence","A decoration","An algorithm","A guess"],"answer":2,"explain":"An algorithm is a set of clear steps or rules followed in order — exactly what you use to continue a pattern."}]},{"id":"sp3","title":"The Tessellation Trail","icon":"🧱","kind":"lesson","story":"The floor of the Tile Temple only stays solid where shapes fit together perfectly with no gaps or overlaps. Learn which shapes tile cleanly to cross safely!","teach":[{"title":"What is tessellation?","body":"Tessellation means covering a flat surface using shapes that fit together with no gaps and no overlaps, like floor tiles. Some shapes tessellate perfectly on their own, and some don't.","visual":"🧱"},{"title":"Why angles matter","body":"At every point where shape-corners meet, the angles around that point must add up to exactly 360 degrees for there to be no gap. Squares (90 degrees) and equilateral triangles (60 degrees) fit this perfectly, but regular pentagons (108 degrees) leave gaps.","visual":"📐"}],"questions":[{"kind":"mcq","prompt":"Which of these shapes can be used alone to cover a floor completely with no gaps or overlaps?","options":["Circle","Regular pentagon","Regular hexagon","Regular heptagon (7 sides)"],"answer":2,"explain":"A regular hexagon's corners (120 degrees each) fit exactly 3 around a point (3 x 120 = 360), so it tiles perfectly. Pentagons, circles, and heptagons leave gaps."},{"kind":"numeric","prompt":"Each corner of a square measures 90 degrees. How many square corners are needed to fit exactly around one point (360 degrees) with no gap?","answer":4,"explain":"90 x 4 = 360, so exactly 4 square corners meet perfectly at one point."},{"kind":"numeric","prompt":"Each corner of an equilateral triangle measures 60 degrees. How many triangle corners are needed to fit exactly around one point (360 degrees)?","answer":6,"explain":"60 x 6 = 360, so exactly 6 triangle corners meet perfectly at one point."},{"kind":"mcq","prompt":"A floor is tiled in rows of rectangular tiles, where each row is shifted sideways so the tile joints never line up straight across rows — just like bricks in a wall. What is this arrangement called?","options":["A symmetric pattern","A checkerboard pattern","A random pattern","A staggered (brick) pattern"],"answer":3,"explain":"Shifting each row so the joints don't line up is called a staggered or brick-laying pattern, and it makes the wall or floor stronger."},{"kind":"numeric","prompt":"You are tiling a rectangular floor that is 6 tiles long and 4 tiles wide, using square tiles of the same size with no gaps or cuts. How many square tiles are needed in total?","answer":24,"explain":"6 x 4 = 24 tiles are needed to cover the whole floor."}]},{"id":"sp4","title":"Growing Shape Sequences","icon":"➕","kind":"lesson","story":"The builders of Stick Canyon grow their shape-chains one step at a time, but they've lost count of how many matchsticks each step needs. Help them find the growing rule!","teach":[{"title":"Shapes that grow by a rule","body":"In a growing pattern, each new step is built by adding the same fixed amount to the one before it — like joining triangles in a row, where each new triangle shares one side and needs only 2 more sticks.","visual":"🔺"},{"title":"Spot the constant difference","body":"To predict a faraway step, first find how much is added each time (the constant difference), then multiply that by how many steps you're jumping ahead, and add it to your starting amount.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"One matchstick triangle needs 3 matchsticks. Each extra triangle added in a row (sharing one side with the last one) needs only 2 more matchsticks. How many matchsticks are needed for a row of 5 triangles?","answer":11,"explain":"3 sticks for the first triangle, plus 2 more for each of the next 4 triangles: 3 + (2 x 4) = 11."},{"kind":"mcq","prompt":"A row of squares is built so each new square shares one side with the last one. The first square needs 4 sticks, and every square after that needs 3 more sticks. How many sticks are needed for a row of 4 squares?","options":["13","16","15","12"],"answer":0,"explain":"4 sticks for the first square, plus 3 more for each of the next 3 squares: 4 + (3 x 3) = 13."},{"kind":"numeric","prompt":"A dot pattern grows like this: Step 1 has 1 dot, Step 2 has 3 dots, Step 3 has 6 dots, Step 4 has 10 dots. Each step adds one more dot than was added the time before (add 2, then add 3, then add 4...). How many dots will Step 5 have?","answer":15,"explain":"Step 4 has 10 dots, and Step 5 adds 5 more dots (one more than the 4 added before): 10 + 5 = 15."},{"kind":"mcq","prompt":"A growing pattern of hexagon-tile chains uses sticks like this: Step 1 uses 6 sticks, Step 2 uses 11 sticks, Step 3 uses 16 sticks. If the rule is 'add 5 sticks every step', how many sticks will Step 4 use?","options":["22","26","20","21"],"answer":3,"explain":"Step 3 uses 16 sticks, and adding 5 more for Step 4 gives 16 + 5 = 21."},{"kind":"numeric","prompt":"A staircase pattern is built from unit squares: Step 1 has 1 square, Step 2 has 3 squares, Step 3 has 6 squares, Step 4 has 10 squares. Following this rule, how many squares are added when you go from Step 4 to Step 5?","answer":5,"explain":"The amount added grows by one each time (add 2, then 3, then 4...), so going from Step 4 to Step 5 adds 5 squares."}]},{"id":"sp5","title":"Sort Into the Right Box","icon":"🗂️","kind":"lesson","story":"The Sorting Gate at Twin Grove Library only opens for shapes placed in their correct box — and some shapes belong in more than one box at once!","teach":[{"title":"Sorting by two clues at once","body":"Sometimes shapes are sorted using two properties at the same time, like 'has parallel sides' and 'all sides equal'. A shape can fit only one clue, both clues, or neither clue — you have to check each property separately.","visual":"🗂️"},{"title":"Using elimination","body":"When you have more than one clue, use each clue to rule out shapes that don't fit, one at a time. Whatever is left after checking every clue is your answer — this step-by-step ruling-out is a key computational thinking skill.","visual":"❌"}],"questions":[{"kind":"mcq","prompt":"Shapes are sorted into two groups: Group A = 'has at least one pair of parallel sides', Group B = 'all sides are equal length'. Where does a square belong?","options":["Both Group A and Group B","Only Group A","Only Group B","Neither group"],"answer":0,"explain":"A square has parallel sides (Group A) and all 4 sides equal (Group B), so it belongs to both groups."},{"kind":"mcq","prompt":"Using the same two groups (A = has parallel sides, B = all sides equal), where does a rectangle that is NOT a square belong?","options":["Only Group A","Only Group B","Both groups","Neither group"],"answer":0,"explain":"A non-square rectangle has parallel sides (Group A), but its length and width differ, so not all sides are equal (not Group B)."},{"kind":"mcq","prompt":"Using the same two groups, where does a scalene triangle (no parallel sides, no equal sides) belong?","options":["Neither group","Only Group A","Only Group B","Both groups"],"answer":0,"explain":"A scalene triangle has no parallel sides and no equal sides, so it fits neither group."},{"kind":"numeric","prompt":"In a shape box, 12 shapes have exactly 4 sides. Of those, 7 also have all sides equal (they are squares), and the rest are rectangles that are not squares. How many non-square rectangles are there?","answer":5,"explain":"12 shapes with 4 sides minus 7 squares leaves 12 - 7 = 5 non-square rectangles."},{"kind":"mcq","prompt":"A game asks you to pick a shape with MORE than 4 sides AND all sides equal. Which shape fits both clues?","options":["Regular pentagon","Square","Scalene triangle","Rectangle"],"answer":0,"explain":"A regular pentagon has 5 sides (more than 4) and all its sides are equal, so it fits both clues."}]},{"id":"sp6","title":"The Rule Detective — Shape Machines","icon":"⚙️","kind":"lesson","story":"A strange machine in the Clockwork Workshop turns numbers into other numbers, but nobody remembers its hidden rule. Study the clues it has already given and figure out how it works!","teach":[{"title":"What is a function machine?","body":"A function machine always applies the exact same hidden rule to whatever number or shape-property goes in, and gives you an output. Your job as a detective is to study a few input-output pairs and figure out the rule.","visual":"⚙️"},{"title":"Testing your rule","body":"Once you think you've found the rule, always test it against one more example before trusting it. If it works for every example you know, it's probably the real rule — this checking step is called verification.","visual":"✅"}],"questions":[{"kind":"mcq","prompt":"A shape machine takes a shape's number of sides and gives an output. Triangle (3 sides) gives 3. Square (4 sides) gives 4. Pentagon (5 sides) gives 5. What is the machine's rule?","options":["Output equals sides minus 1","Output equals the number of sides (it also equals the number of corners)","Output equals sides plus 1","Output equals sides times 2"],"answer":1,"explain":"In every example the output matches the number of sides exactly, which is also always equal to the number of corners."},{"kind":"numeric","prompt":"A shape machine follows the rule: output = number of sides x 2. If a hexagon (6 sides) goes in, what number comes out?","answer":12,"explain":"6 x 2 = 12."},{"kind":"mcq","prompt":"A machine takes a polygon's number of sides (n) and outputs the number of triangles it can be cut into from one single corner, using the rule: output = n - 2. A hexagon has 6 sides. What does the machine output?","options":["3","5","6","4"],"answer":3,"explain":"Using the rule output = n - 2, a hexagon gives 6 - 2 = 4."},{"kind":"numeric","prompt":"Look at this input-output table for a shape machine: Input 3 gives Output 9; Input 4 gives Output 16; Input 5 gives Output 25. What output would Input 6 give?","answer":36,"explain":"The rule is output = input x input (squaring), so 6 x 6 = 36."},{"kind":"mcq","prompt":"Why is it useful to TEST your guessed rule on one more example before trusting it completely?","options":["Because testing is required by the game","To make the pattern longer","To use up extra time","To make sure the rule really works for every case, not just the ones you've already checked"],"answer":3,"explain":"Testing a rule on a new example checks that it truly holds everywhere, not just by coincidence for the first few cases."}]},{"id":"sp-boss","title":"The Peak of Patterns","icon":"🏆","kind":"boss","story":"At the very top of Pattern Peak waits Glitch, the Pattern-Breaker, who has scrambled every shape rule in the kingdom. Solve the final round of shape, tiling, and pattern puzzles to restore order!","boss":{"name":"Glitch, the Pattern-Breaker","taunt":"Ha! I've twisted every tile and jumbled every sequence — bet you can't put my puzzles back in order!"},"teach":[{"title":"Bring it all together","body":"This final challenge mixes shape classification, pattern-rule deduction, tessellation logic, growing sequences, sorting by clues, and function-machine rules. Take each puzzle one careful step at a time, just as you practiced on Pattern Peak.","visual":"🏆"}],"questions":[{"kind":"mcq","prompt":"I have 5 sides, all equal in length, and all my angles are equal too. What shape am I?","options":["Rhombus","Regular hexagon","Square","Regular pentagon"],"answer":3,"explain":"A shape with 5 equal sides and 5 equal angles is a regular pentagon."},{"kind":"mcq","prompt":"Pattern: hexagon, hexagon, triangle, hexagon, hexagon, triangle, hexagon, hexagon, ___. What comes next?","options":["Hexagon","Square","Pentagon","Triangle"],"answer":3,"explain":"The repeating group is hexagon-hexagon-triangle, so after two hexagons comes a triangle."},{"kind":"numeric","prompt":"A regular hexagon's interior angle measures 120 degrees. How many hexagon corners fit exactly around one point (360 degrees) with no gaps?","answer":3,"explain":"120 x 3 = 360, so exactly 3 hexagon corners meet perfectly at one point."},{"kind":"numeric","prompt":"A growing row of pentagon tiles uses sticks like this: Step 1 uses 5 sticks, Step 2 uses 9 sticks, Step 3 uses 13 sticks (each new pentagon shares one side, adding 4 sticks). How many sticks will Step 5 use?","answer":21,"explain":"Starting at 5 sticks and adding 4 sticks for each of the next 4 steps: 5 + (4 x 4) = 21."},{"kind":"mcq","prompt":"Shapes are sorted by two clues: Group X = 'has a right angle', Group Y = 'has exactly 4 sides'. Where does a right-angled triangle belong?","options":["Only Group X","Only Group Y","Both groups","Neither group"],"answer":0,"explain":"A right-angled triangle has a right angle (Group X) but only 3 sides, so it does not belong to Group Y."},{"kind":"numeric","prompt":"A shape machine follows a hidden rule: Input 1 gives Output 3; Input 2 gives Output 5; Input 3 gives Output 7; Input 4 gives Output 9. Using the same rule, what output would Input 6 give?","answer":13,"explain":"The rule is output = (2 x input) + 1, so for Input 6: (2 x 6) + 1 = 13."},{"kind":"mcq","prompt":"A garden path is tiled in this repeating pattern: square, triangle, triangle, square, triangle, triangle, and so on, starting at position 1 with square. What tile is in the 10th position?","options":["Square","Triangle","Hexagon","Pentagon"],"answer":0,"explain":"The repeating group has 3 tiles (square, triangle, triangle). 10 divided by 3 leaves a remainder of 1, and the 1st tile in the group is square."}]}]},{"id":"weightcapacity5","index":7,"name":"Weight and Capacity","subtitle":"Computational Thinking — Chapter 8","emoji":"⚖️","palette":{"from":"#a78bfa","to":"#4c1d95"},"lessons":[{"id":"wc1","title":"The Coin of Lies","icon":"🪙","kind":"lesson","story":"You step into the Balance Bazaar, where merchant Runa's coin chest was raided overnight and a fake coin was slipped in among her gold! She hands you her balance scale and begs you to find the fake using the fewest weighings possible before the market opens.","teach":[{"title":"Splitting into Three (Ternary Search)","body":"When you have many look-alike objects and one is different, splitting them into three equal groups and comparing two groups on a balance scale eliminates two-thirds of the suspects in a single weighing. This is faster than comparing just one pair at a time, because each weighing gives you more information to work with.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"You have 9 identical-looking gold coins. One is a fake that is slightly LIGHTER than the rest. You split them into 3 groups of 3 (A, B, C), placing group A on the left pan and group B on the right pan of a balance scale. The pans balance exactly. What does this tell you?","options":["The fake coin is in group C","There is no way to know yet","The fake coin is in group A","The fake coin is in group B"],"answer":0,"explain":"If A and B balance, both groups are genuine, so the lighter fake must be in the group that wasn't weighed — group C."},{"kind":"numeric","prompt":"Continuing the same puzzle: group C has 3 coins and contains the fake. What is the minimum number of MORE weighings needed to find exactly which coin is fake, by comparing 2 of the 3 coins on the scale?","answer":1,"explain":"Weigh any 2 of the 3 coins: if they balance, the third one is fake; if not, the lighter one is fake — just 1 more weighing."},{"kind":"numeric","prompt":"So what is the TOTAL minimum number of weighings needed to find the 1 fake coin among the 9 coins using groups of 3?","answer":2,"explain":"1 weighing to narrow 9 coins down to 3, plus 1 more weighing to narrow 3 down to 1 — 2 weighings in total."},{"kind":"mcq","prompt":"You have 6 identical-looking rings, one of which is a lighter fake. You place 2 rings on the left pan and 2 different rings on the right pan (the remaining 2 rings are set aside). The left pan rises up, meaning it is lighter. Where must the fake ring be?","options":["Among the 2 rings on the right pan","It could be any of the 6 rings","Among the 2 rings on the left pan","Among the 2 rings set aside"],"answer":2,"explain":"The left pan is lighter, so the fake — which is lighter than a real ring — must be one of the two rings sitting on that pan."}]},{"id":"wc2","title":"Bhanu's Jumbled Jars","icon":"🔄","kind":"lesson","story":"Runa's cousin, the potion-seller Bhanu, is in a panic — his gram and kilogram labels got swapped on every jar overnight! Help him relabel the shelves correctly by converting weights and volumes before curious customers start asking prices.","teach":[{"title":"Same Units, Fair Comparisons","body":"You can only compare or add weights and volumes when they're written in the same unit — so 1 kilogram equals 1000 grams, and 1 litre equals 1000 millilitres. Converting everything to the same unit first is a key computational thinking step before doing any calculation.","visual":"🔄"}],"questions":[{"kind":"numeric","prompt":"A bag of rice weighs 2 kg 350 g. What is this weight in grams?","answer":2350,"explain":"2 kg = 2000 g, plus the extra 350 g gives 2350 g."},{"kind":"numeric","prompt":"Two identical bottles each hold 750 ml of juice. How many millilitres of juice do both bottles hold together?","answer":1500,"explain":"750 ml + 750 ml = 1500 ml."},{"kind":"mcq","prompt":"Which is heavier: a sack weighing 3 kg 200 g, or a sack weighing 3200 g?","options":["3200 g is heavier","3 kg 200 g is heavier","Cannot be compared","They are exactly equal"],"answer":3,"explain":"3 kg 200 g = 3000 g + 200 g = 3200 g, which is exactly the same as 3200 g."},{"kind":"numeric","prompt":"A water tank holds 5 L of water. If 750 ml is poured out, how many millilitres of water remain in the tank?","answer":4250,"explain":"5 L = 5000 ml, and 5000 ml − 750 ml = 4250 ml."},{"kind":"numeric","prompt":"Four identical packets of flour weigh 250 g each. What is their total weight in kilograms?","answer":1,"explain":"4 × 250 g = 1000 g, and 1000 g = 1 kg."}]},{"id":"wc3","title":"Tarun's Odd Jugs","icon":"🪣","kind":"lesson","story":"At the well behind the bazaar, water-carrier Tarun has lost his measuring cups and is left with only two oddly-sized jugs! Use clever pouring steps to help him measure out exactly the right amounts of water for the thirsty camel caravan.","teach":[{"title":"Tracking State Step by Step","body":"In a pouring puzzle, keep track of exactly how much liquid is in each container after every single pour — this is called tracking the 'state'. Computers solve tricky puzzles the same way: one small step at a time, always knowing exactly where things stand.","visual":"🪣"}],"questions":[{"kind":"mcq","prompt":"You have an empty 5 L jug and an empty 3 L jug (no markings) plus unlimited water. First you completely fill the 5 L jug, then pour from it into the 3 L jug until the 3 L jug is completely full. How much water is now left in the 5 L jug?","options":["5 L","1 L","2 L","3 L"],"answer":2,"explain":"5 L minus the 3 L that went into the smaller jug leaves 2 L behind in the big jug."},{"kind":"numeric","prompt":"Next, you empty the 3 L jug completely and pour the 2 L remaining in the 5 L jug into the now-empty 3 L jug. How many more litres of space are left in the 3 L jug before it becomes full?","answer":1,"explain":"The 3 L jug now holds 2 L, so it has 3 − 2 = 1 L of empty space left."},{"kind":"numeric","prompt":"Now you fill the 5 L jug completely again, then pour from it into the 3 L jug (which already holds 2 L) until the 3 L jug is full — that takes exactly 1 more litre. How many litres of water are now left in the 5 L jug?","answer":4,"explain":"You poured 1 L out of the full 5 L jug, so 5 − 1 = 4 L remains — exactly the amount Tarun wanted to measure!"},{"kind":"numeric","prompt":"A total of 20 L of paint is poured completely into 4 tins, filling all of them. Two of the tins are completely full, holding 5 L and 8 L. The other two tins are filled so that exactly 1 L of empty space remains in each one. If one of those two tins has a capacity of 4 L, what is the capacity (in litres) of the last tin?","answer":5,"explain":"5 + 8 = 13 L used, leaving 7 L for the last two tins. The 4 L tin holds 4 − 1 = 3 L, so the last tin holds 7 − 3 = 4 L, meaning its capacity is 4 + 1 = 5 L."}]},{"id":"wc4","title":"The Riddle-Guards' Bridge","icon":"🔗","kind":"lesson","story":"Three riddle-loving guards block the only bridge out of the bazaar, each hinting at their weight compared to the others instead of simply telling you the number! Untangle their clues with careful step-by-step reasoning to earn safe passage.","teach":[{"title":"Chaining Clues Together","body":"When you're told how one weight compares to another, and then how a third compares to the second, you can chain the clues together to work out the full picture — just like solving a mystery one hint at a time. Always start from something you're told directly, then build outward step by step.","visual":"🔗"}],"questions":[{"kind":"mcq","prompt":"Priya weighs 3 kg more than Rohan. Meera weighs 2 kg less than Priya. What is the difference between Meera's weight and Rohan's weight?","options":["2 kg","3 kg","1 kg","5 kg"],"answer":2,"explain":"Priya = Rohan + 3, and Meera = Priya − 2 = Rohan + 1, so Meera is just 1 kg more than Rohan."},{"kind":"numeric","prompt":"A faulty weighing machine always shows a weight that is 4 kg MORE than the actual weight. It shows Kabir's weight as 42 kg, so his actual weight is 38 kg. Diya's actual weight is 3 kg less than Kabir's actual weight. What weight will the faulty machine show for Diya?","answer":39,"explain":"Diya's actual weight is 38 − 3 = 35 kg. The faulty machine adds 4 kg, showing 35 + 4 = 39 kg."},{"kind":"mcq","prompt":"The sum of the weights of X and Y is 45 kg, and the sum of the weights of Y and Z is 60 kg. If the weight of X is AT LEAST 15 kg, which of these CANNOT be the weight of Z?","options":["25 kg","50 kg","40 kg","30 kg"],"answer":0,"explain":"Since Z = 15 + X and X must be at least 15 kg, Z can never be less than 30 kg — so 25 kg is impossible."},{"kind":"mcq","prompt":"QUESTION: What is the total weight of 8 identical bricks? STATEMENT 1: Each brick weighs 2 kg. STATEMENT 2: The 8 bricks together weigh less than 20 kg. Which statement(s) alone are sufficient to answer the question?","options":["Statement 1 alone is sufficient, but Statement 2 alone is not","Statement 2 alone is sufficient, but Statement 1 alone is not","Both statements alone are sufficient","Even both statements together are not sufficient"],"answer":0,"explain":"Statement 1 directly gives 8 × 2 = 16 kg, an exact answer. Statement 2 only gives an upper limit, not an exact weight."}]},{"id":"wc5","title":"The Rope Lift's Limit","icon":"🛗","kind":"lesson","story":"The bazaar's rickety rope lift can only carry so much weight before the ropes snap! Help the loaders work out exactly which combinations of people and crates are safe to send up without going over the limit.","teach":[{"title":"Checking the Limit","body":"Before combining objects onto a scale, lift, or vehicle, add up their weights and compare the total to the maximum allowed — this is called checking a constraint. If the total goes even slightly over the limit, the whole plan needs to change.","visual":"🛗"}],"questions":[{"kind":"mcq","prompt":"A lift can carry a MAXIMUM of 300 kg at a time. Four friends weigh 68 kg, 72 kg, 75 kg, and 90 kg. Can all four friends ride the lift together?","options":["No — together they weigh 305 kg, which is over the limit","Yes — together they weigh 295 kg, well under the limit","No — together they weigh 320 kg","Yes — together they weigh exactly 300 kg"],"answer":0,"explain":"68 + 72 + 75 + 90 = 305 kg, which is 5 kg more than the 300 kg limit."},{"kind":"numeric","prompt":"If the lightest of the four friends (68 kg) waits outside, what is the total weight (in kg) of the remaining three friends?","answer":237,"explain":"305 kg total − 68 kg = 237 kg for the remaining three friends."},{"kind":"numeric","prompt":"A delivery van can carry up to 200 kg. It already has 3 boxes loaded, weighing 45 kg, 60 kg, and 50 kg. How many more kilograms can the van carry before reaching its limit?","answer":45,"explain":"45 + 60 + 50 = 155 kg already loaded, and 200 − 155 = 45 kg of room remains."},{"kind":"mcq","prompt":"Three crates weigh 40 kg, 55 kg, and 65 kg. A trolley can carry at most 2 crates at a time and must not exceed 100 kg total. Which pair of crates lets you carry the MOST weight without going over the limit?","options":["The 40 kg and 55 kg crates (95 kg total)","Just the 65 kg crate alone (65 kg total)","The 55 kg and 65 kg crates (120 kg total)","The 40 kg and 65 kg crates (105 kg total)"],"answer":0,"explain":"40 + 55 = 95 kg fits under the 100 kg limit and is heavier than any other safe combination."}]},{"id":"wc6","title":"Devi's Tripling Trick","icon":"🔺","kind":"lesson","story":"Old Scalekeeper Devi shows you her giant ternary balance and a mountain of coins. She challenges you: as the pile keeps tripling in size, can you predict how many weighings she'll need — without testing every single pile by hand?","teach":[{"title":"Spotting the Pattern","body":"Once you solve a puzzle for a small number of items, look for a pattern in how the answer changes as the number of items grows — like tripling the coins each time. Spotting and using patterns lets you predict answers for huge numbers without solving everything from scratch.","visual":"🔺"}],"questions":[{"kind":"numeric","prompt":"Using the ternary (split-into-3) method, finding 1 fake coin among 9 coins takes 2 weighings. Following the same pattern, how many weighings does it take to find 1 fake coin among 27 coins?","answer":3,"explain":"27 coins split into 3 groups of 9 (1 weighing), then 9 split into 3 groups of 3 (1 more), then 3 down to 1 (1 more) — 3 weighings total."},{"kind":"numeric","prompt":"Continuing the pattern, how many weighings are needed to find 1 fake coin among 81 coins?","answer":4,"explain":"Each tripling of the coins adds exactly 1 more weighing, so 81 coins (3×27) needs 3 + 1 = 4 weighings."},{"kind":"mcq","prompt":"Look at how the number of coins changes each time: 9, 27, 81, 243 — each number is 3 times the one before it. What happens to the number of weighings needed each time the coins triple?","options":["It stays exactly the same","It increases by exactly 1 weighing","It doubles","It increases by 3 weighings"],"answer":1,"explain":"Multiplying the coins by 3 always adds just 1 more weighing — that's the power of splitting into three groups each time."},{"kind":"numeric","prompt":"Using this pattern, how many weighings would be needed to find 1 fake coin among 243 coins?","answer":5,"explain":"243 coins = 3 × 81, so it needs 1 more weighing than 81 coins: 4 + 1 = 5 weighings."}]},{"id":"wc-boss","title":"Lord Ledger, the Imbalance Wizard","icon":"🧙","kind":"boss","story":"At the top of the bazaar tower waits Lord Ledger, the Imbalance Wizard, who scrambled every scale, jug, and label in Measure-Land purely for his own amusement! Prove you've mastered weight and capacity thinking to restore balance to the whole bazaar and defeat him for good.","teach":[{"title":"Bring It All Together","body":"Lord Ledger's challenges mix every skill you've learned: splitting into groups, converting units, tracking pours, chaining clues, checking limits, and spotting patterns. Read each riddle carefully and decide which computational thinking tool fits best before you answer.","visual":"🧙"}],"boss":{"name":"Lord Ledger, the Imbalance Wizard","taunt":"Ha! Your numbers wobble more than my rustiest old scale — let's see if you can out-balance ME!"},"questions":[{"kind":"numeric","prompt":"A parcel weighs 1 kg 750 g. What is this weight in grams?","answer":1750,"explain":"1 kg = 1000 g, plus the extra 750 g gives 1750 g."},{"kind":"mcq","prompt":"You have 3 identical-looking pouches, one of which is a heavier fake. Using a balance scale, what is the MINIMUM number of weighings needed to guarantee finding the heavier pouch?","options":["2 weighings","0 weighings","1 weighing","3 weighings"],"answer":2,"explain":"Weigh any 2 of the 3 pouches: if they balance, the third is the heavier fake; if not, the heavier pan holds the fake — just 1 weighing."},{"kind":"numeric","prompt":"An elevator's maximum load is 250 kg. Three people weigh 80 kg, 85 kg, and 90 kg. By how many kilograms would they go OVER the limit if all three rode together?","answer":5,"explain":"80 + 85 + 90 = 255 kg, which is 5 kg more than the 250 kg limit."},{"kind":"numeric","prompt":"You have a 4 L jug and a 1 L jug, unlimited water, and want exactly 3 L in the 4 L jug. If you fill the 4 L jug completely and then pour water out into the 1 L jug until the 1 L jug is full, how many litres remain in the 4 L jug?","answer":3,"explain":"4 L − 1 L poured out = 3 L remaining, exactly the amount needed."},{"kind":"mcq","prompt":"Aman weighs 5 kg more than Zoya. Kabir weighs 2 kg less than Aman. Who is heavier, Kabir or Zoya, and by how much?","options":["Zoya, by 3 kg","They weigh the same","Kabir, by 3 kg","Kabir, by 5 kg"],"answer":2,"explain":"Kabir = Aman − 2 = (Zoya + 5) − 2 = Zoya + 3, so Kabir is heavier than Zoya by 3 kg."},{"kind":"numeric","prompt":"Using the split-into-3 balance method, finding 1 fake coin among 9 coins takes 2 weighings, and among 27 coins takes 3 weighings. Following this pattern, how many weighings would be needed for 729 coins? (Hint: 729 = 3 x 3 x 3 x 3 x 3 x 3)","answer":6,"explain":"729 = 3 to the 6th power, and since each tripling adds 1 weighing starting from 3 coins needing 1 weighing, 3 to the 6th needs 6 weighings."}]}]},{"id":"coconutfarm5","index":8,"name":"Coconut Farm","subtitle":"Computational Thinking — Chapter 9","emoji":"🥥","palette":{"from":"#84cc16","to":"#365314"},"lessons":[{"id":"cf1","title":"The Grove Count","icon":"🌴","kind":"lesson","story":"Bhola Uncle needs to know exactly how many coconuts his grove will give BEFORE he hires baskets and workers for harvest day. Every tree in a row gives the same number of coconuts — help him multiply smartly instead of counting one by one.","teach":[{"title":"Multiply Instead of Counting One by One","body":"When every tree in a group gives the SAME number of coconuts, you don't have to count each nut by hand — just multiply the number of trees by the coconuts per tree. Using a repeated pattern to skip repeated work is a key computational thinking trick.","visual":"🌴×🥥"},{"title":"Break a Big Job into Groups","body":"A giant grove is easier to handle when you split it into smaller equal rows first, solve each row on its own, and then add the row totals together. Splitting one big problem into smaller identical pieces is called decomposition.","visual":"🌴🌴🌴➡️➕"}],"questions":[{"kind":"numeric","prompt":"Row A has 7 trees. Each tree gives 9 coconuts this season. How many coconuts will row A give in total?","answer":63,"explain":"7 trees × 9 coconuts each = 63 coconuts."},{"kind":"numeric","prompt":"Row B has 12 trees, and each tree gives 8 coconuts. How many coconuts will row B give?","answer":96,"explain":"12 trees × 8 coconuts each = 96 coconuts."},{"kind":"numeric","prompt":"Using rows A and B above (63 and 96 coconuts), how many coconuts will the two rows give together?","answer":159,"explain":"63 + 96 = 159 coconuts from both rows combined."},{"kind":"mcq","prompt":"Bhola Uncle wants the total harvest from 5 identical rows, each with 6 trees giving 7 coconuts per tree. What is the SMARTEST way to compute this?","options":["Count every coconut one by one on all 30 trees","Multiply 5 × 7 only and ignore the number of trees per row","Add 6 and 7 first, then multiply by 5","Multiply 6 × 7 to get coconuts per row, then multiply that by 5"],"answer":3,"explain":"Finding coconuts per row first (6 × 7 = 42), then multiplying by the number of identical rows (× 5), avoids counting one by one."},{"kind":"numeric","prompt":"Using the smart method above, how many coconuts do the 5 rows give in total?","answer":210,"explain":"Each row gives 6 × 7 = 42 coconuts, and 5 rows give 42 × 5 = 210 coconuts."}]},{"id":"cf2","title":"Basket Sharing","icon":"🧺","kind":"lesson","story":"Harvest day! The pickers dropped 84 coconuts in one big pile, and Meena must share them fairly among the baskets before the truck arrives. Help her use division — and work out what happens when the sharing doesn't come out even.","teach":[{"title":"Division Shares Things Equally","body":"Division splits a total into equal-sized groups. If you have a certain number of coconuts and want to fill a certain number of baskets equally, dividing the coconuts by the baskets tells you how many go in each one.","visual":"🥥➗🧺"},{"title":"Sometimes There's a Remainder","body":"When a total doesn't divide evenly, some coconuts are left over after filling all the equal baskets — that leftover amount is called the remainder, and it always has to go somewhere, like one extra small basket.","visual":"🥥🥥➕❓"}],"questions":[{"kind":"numeric","prompt":"Meena has 84 coconuts and 7 identical baskets. If she shares them equally, how many coconuts go in each basket?","answer":12,"explain":"84 ÷ 7 = 12 coconuts in each basket, with nothing left over."},{"kind":"numeric","prompt":"Now Meena has 90 coconuts to share equally among 8 baskets, filling each one as much as possible. How many coconuts go in each basket?","answer":11,"explain":"8 × 11 = 88, which is the most she can put in 8 equal baskets, so each basket gets 11."},{"kind":"numeric","prompt":"In the previous puzzle, how many coconuts are LEFT OVER after filling the 8 baskets with 11 each?","answer":2,"explain":"90 − 88 = 2 coconuts are left over as the remainder."},{"kind":"mcq","prompt":"A farmer has 53 coconuts and wants to pack them into baskets of 6 each. How many FULL baskets of 6 can she make, and how many are left over?","options":["7 full baskets, with 11 coconuts left over","8 full baskets, with 5 coconuts left over","9 full baskets, with 1 coconut left over","8 full baskets, with 6 coconuts left over"],"answer":1,"explain":"6 × 8 = 48, and 53 − 48 = 5, so she makes 8 full baskets with 5 coconuts left over."},{"kind":"numeric","prompt":"Using the same 53 coconuts, how many MORE coconuts does she need to collect so that all baskets of 6 are completely full with zero left over?","answer":1,"explain":"53 has a remainder of 5 when divided by 6; adding just 1 more coconut makes 54, which is exactly 9 full baskets of 6."}]},{"id":"cf3","title":"The Leftover Nuts","icon":"🔍","kind":"lesson","story":"The farm inspector wants to know, WITHOUT counting every single coconut, whether today's harvest can be split into neat rows of a certain size with nothing left over. Sharpen your remainder-detective skills!","teach":[{"title":"Check Divisibility With a Quick Test","body":"To find out if a total will divide evenly into groups of a certain size, divide and look at the remainder. If the remainder is 0, it splits perfectly; if not, there will be leftovers.","visual":"🥥➗0️⃣❓"},{"title":"Decide What Information You Actually Need","body":"Before solving a counting puzzle, ask which facts are truly necessary to answer it. Some clues let you answer directly, while others are just distractions — picking out only the USEFUL information is a key computational thinking skill.","visual":"🔎📋"}],"questions":[{"kind":"mcq","prompt":"The farm has 96 coconuts. The inspector wants to arrange them into rows of exactly 8 with none left over. How can you check this WITHOUT laying out all the rows?","options":["Multiply 96 by 8 and check the result","Add 96 and 8 and check if the sum is even","Divide 8 by 96 and see if the remainder is 0","Divide 96 by 8 and see if the remainder is 0"],"answer":3,"explain":"96 ÷ 8 = 12 with remainder 0, so the coconuts arrange perfectly into rows of 8."},{"kind":"numeric","prompt":"Will 96 coconuts divide evenly into rows of 7? Answer with the remainder when 96 is divided by 7.","answer":5,"explain":"7 × 13 = 91, and 96 − 91 = 5, so the remainder is 5 — it does NOT divide evenly."},{"kind":"mcq","prompt":"QUESTION: Can today's 70 coconuts be split evenly into baskets of 5 with nothing left over? STATEMENT 1: 70 is an even number. STATEMENT 2: 70 divided by 5 leaves a remainder of 0. Which statement(s) alone are sufficient to answer the question?","options":["Statement 2 alone is sufficient, but Statement 1 alone is not","Statement 1 alone is sufficient, but Statement 2 alone is not","Both statements alone are sufficient","Neither statement is sufficient alone"],"answer":0,"explain":"Statement 2 directly tells us the remainder is 0, which answers the question. Statement 1 only tells us 70 is even, which says nothing about dividing by 5."},{"kind":"numeric","prompt":"A farmer collects some coconuts and finds that dividing them into groups of 9 leaves a remainder of 4. If she has between 50 and 60 coconuts, how many coconuts does she have?","answer":58,"explain":"58 ÷ 9 = 6 remainder 4, and it is the only number between 50 and 60 that leaves remainder 4 when divided by 9."},{"kind":"numeric","prompt":"The inspector checks 45 coconuts for rows of 6. What is the remainder when 45 is divided by 6?","answer":3,"explain":"6 × 7 = 42, and 45 − 42 = 3, so the remainder is 3."}]},{"id":"cf4","title":"Loading the Truck","icon":"🚚","kind":"lesson","story":"The delivery truck has finally arrived, but it can only carry a maximum number of coconuts per trip! Help the farm team work out how many trips they need, and which sacks fit together without going over the limit.","teach":[{"title":"Check the Limit Before Loading","body":"Before packing items into a truck, basket, or box, add up what's already inside and compare it to the maximum allowed. Checking this limit — called a constraint — stops you from overloading or wasting space.","visual":"🚚⚖️"},{"title":"Break a Big Delivery into Trips","body":"When one truckload isn't enough, decompose the total job into repeated trips of the same size, then work out how many trips are needed — including a smaller final trip if there's a remainder.","visual":"🚚➡️🚚➡️🚚"}],"questions":[{"kind":"numeric","prompt":"A truck can carry at most 150 coconuts per trip. The farm has 620 coconuts to deliver. How many FULL trips of 150 coconuts can the truck make?","answer":4,"explain":"150 × 4 = 600, which fits, but 150 × 5 = 750 is too many. So there are 4 full trips."},{"kind":"numeric","prompt":"After those full trips, how many coconuts are left over for one final, smaller trip?","answer":20,"explain":"620 − 600 = 20 coconuts remain for the last, smaller trip."},{"kind":"mcq","prompt":"So what is the TOTAL number of trips the truck must make to deliver all 620 coconuts, including the smaller final trip?","options":["3 trips","4 trips","6 trips","5 trips"],"answer":3,"explain":"4 full trips of 150 plus 1 smaller trip of 20 makes 5 trips in total."},{"kind":"numeric","prompt":"A second truck can carry at most 90 crates of coconuts. It already has 54 crates loaded. How many more crates can it carry before reaching its 90-crate limit?","answer":36,"explain":"90 − 54 = 36 more crates can still be loaded."},{"kind":"mcq","prompt":"Truck 1 is empty and can carry at most 200 coconuts. Three sacks are ready to load, holding 130, 90, and 160 coconuts. Which single sack fits safely inside Truck 1's limit while leaving the LEAST unused space?","options":["The 160-coconut sack (only 40 spaces unused)","The 90-coconut sack (110 spaces unused)","The 130-coconut sack (70 spaces unused)","None of the sacks fit"],"answer":0,"explain":"All three sacks fit under the 200 limit, but 160 leaves only 200 − 160 = 40 spaces unused — the least waste of any sack."}]},{"id":"cf5","title":"Missing Pieces","icon":"🧩","kind":"lesson","story":"Grandma Farmer left cryptic notes about this year's harvest instead of writing down the exact totals! You must deduce the missing numbers using only the clues she left behind — just like a detective.","teach":[{"title":"Work Backward From Clues","body":"When you don't know a number directly but you know how it relates to a number you DO know, you can work backward step by step to find it — like following one clue at a time in a treasure hunt.","visual":"🧩🔙"},{"title":"Decide If a Clue Is Enough","body":"A single clue might already answer the question completely, or you might need to combine two clues together. Checking whether you have ENOUGH information before calculating saves time and avoids guessing.","visual":"✅❓"}],"questions":[{"kind":"numeric","prompt":"The North field gave 45 more coconuts than the South field. The South field gave 130 coconuts. How many coconuts did the North field give?","answer":175,"explain":"130 + 45 = 175 coconuts from the North field."},{"kind":"numeric","prompt":"The East field gave 20 FEWER coconuts than the North field (175 coconuts, from before). How many coconuts did the East field give?","answer":155,"explain":"175 − 20 = 155 coconuts from the East field."},{"kind":"mcq","prompt":"QUESTION: How many coconuts did Grandma's secret grove give this year? STATEMENT 1: The secret grove gave 25 fewer coconuts than the North field, which gave 175 coconuts. STATEMENT 2: The secret grove's coconuts, shared into baskets of 10, filled exactly 15 baskets with none left over. Which statement(s) alone are sufficient to answer the question?","options":["Both statements alone are sufficient","Statement 1 alone is sufficient, but Statement 2 alone is not","Statement 2 alone is sufficient, but Statement 1 alone is not","Neither statement alone is sufficient"],"answer":0,"explain":"Statement 1 gives 175 − 25 = 150 directly. Statement 2 gives 15 × 10 = 150 directly too — either clue alone is enough, and they agree."},{"kind":"numeric","prompt":"The secret grove gave 150 coconuts (confirmed above). If Grandma already sold 65 of them at the market, how many coconuts does she have left from the secret grove?","answer":85,"explain":"150 − 65 = 85 coconuts remaining."},{"kind":"mcq","prompt":"QUESTION: Did the Hill field give MORE or FEWER coconuts than the South field (130 coconuts)? STATEMENT: The Hill field's harvest, divided by 4, gives exactly 40 with no remainder. Is this statement ALONE enough to answer the question?","options":["Yes — the Hill field gave 100 coconuts, which is less than 130","Yes — the Hill field gave 160 coconuts, which is more than 130","No — we need to know the South field's harvest too","No — the statement doesn't tell us the total"],"answer":1,"explain":"40 × 4 = 160 coconuts in the Hill field, and 160 is more than the South field's 130 — the single statement is enough."}]},{"id":"cf6","title":"Picking Order","icon":"📋","kind":"lesson","story":"Before the big harvest morning, you must write out the exact ORDER of steps the workers should follow — get it wrong, and coconuts get bruised or wasted! You'll also need to crack the farm's number patterns to predict future batches.","teach":[{"title":"Put Steps in the Right Order","body":"A harvest isn't just one action — it's climbing, cutting, catching, and loading, and each step only makes sense AFTER the one before it. Arranging actions into a correct, logical sequence is called decomposition into an algorithm.","visual":"🧗➡️✂️➡️🧺➡️🚚"},{"title":"Spot the Pattern to Predict Ahead","body":"Many harvest counts follow a repeating rule, like doubling, or multiplying and dividing in turn. Once you spot the RULE behind a sequence of numbers, you can predict what comes next without being told directly.","visual":"🔁➡️❓"}],"questions":[{"kind":"mcq","prompt":"Put these harvest steps in the correct order: (1) Load the baskets onto the truck (2) Climb the coconut tree (3) Cut the coconuts down (4) Catch and collect the fallen coconuts in baskets.","options":["3, 2, 4, 1","1, 2, 3, 4","2, 3, 4, 1","4, 3, 2, 1"],"answer":2,"explain":"You must first climb (2), then cut the coconuts down (3), then catch and collect them (4), and only then load the full baskets onto the truck (1)."},{"kind":"numeric","prompt":"A farm's coconut count doubles every row: Row 1 gives 3 coconuts, Row 2 gives 6, Row 3 gives 12, Row 4 gives 24. Following this doubling pattern, how many coconuts will Row 5 give?","answer":48,"explain":"Each row doubles the one before it, so Row 5 gives 24 × 2 = 48 coconuts."},{"kind":"numeric","prompt":"Another orchard's basket-count pattern follows a rule: 16, 48, 24, 72, 36, 108, ? — What comes next?","answer":54,"explain":"The pattern alternates: multiply by 3, then divide by 2, repeating. So 108 ÷ 2 = 54."},{"kind":"mcq","prompt":"A picker's daily routine repeats every 3 days in this order: Pick, Rest, Sell, Pick, Rest, Sell, and so on. If Day 1 is \"Pick\", what activity happens on Day 8?","options":["Rest","Pick","Sell","None of these"],"answer":0,"explain":"Day 8 is the 8th day of a 3-day repeating cycle: days 1,4,7 are Pick, days 2,5,8 are Rest, days 3,6 are Sell — so Day 8 is Rest."},{"kind":"numeric","prompt":"Using the same 3-day routine (Pick, Rest, Sell) starting on Day 1, how many of the first 30 days are \"Pick\" days?","answer":10,"explain":"Exactly 1 out of every 3 days is a Pick day, so in 30 days there are 30 ÷ 3 = 10 Pick days."}]},{"id":"cf-boss","title":"The Great Harvest Showdown","icon":"🐦","kind":"boss","story":"Kaalu the Crafty Crow King has raided the farm overnight and hidden coconuts all over his nest tree! To win them back, you must use everything you've learned — multiplying, sharing, checking remainders, loading trucks, and cracking clues — before he flies off with the whole harvest.","boss":{"name":"Kaalu, the Crafty Crow King","taunt":"Caw caw! Numbers are just noise to me — beat my count if you can, little counter!"},"teach":[{"title":"Put It All Together","body":"A big real-world problem often needs several computational thinking skills used one after another: multiply to predict, divide to share, check remainders, respect limits, and follow clues in the right order. Combining skills like this is how real problems get solved.","visual":"🌴➕🧺➕🚚➕🧩"}],"questions":[{"kind":"numeric","prompt":"Kaalu hid coconuts in 9 trees around his nest, 11 coconuts in each tree. How many coconuts has he hidden in total?","answer":99,"explain":"9 trees × 11 coconuts each = 99 coconuts."},{"kind":"numeric","prompt":"You recover all 99 coconuts and share them equally among 8 rescue baskets, filling each as much as possible. How many coconuts go into each basket?","answer":12,"explain":"8 × 12 = 96, the most that fits evenly, so each basket gets 12 coconuts."},{"kind":"numeric","prompt":"How many coconuts are left over after filling the 8 rescue baskets with 12 each?","answer":3,"explain":"99 − 96 = 3 coconuts left over as the remainder."},{"kind":"mcq","prompt":"QUESTION: Did Kaalu steal MORE or FEWER coconuts than the North Field's 175 coconuts? STATEMENT: Kaalu's stash, divided by 9, gives exactly 11 with no remainder. Is this statement ALONE enough to answer the question?","options":["Yes — Kaalu's stash is 99 coconuts, more than 175","No — we need more information","No — the remainder isn't given","Yes — Kaalu's stash is 99 coconuts, fewer than 175"],"answer":3,"explain":"9 × 11 = 99 coconuts, and 99 is fewer than 175 — the single statement is enough to answer."},{"kind":"numeric","prompt":"A rescue truck can carry at most 60 coconuts per trip. How many FULL trips of 60 are needed to carry away the recovered coconuts, before any smaller final trip?","answer":1,"explain":"60 × 1 = 60 fits, but 60 × 2 = 120 is more than 99, so only 1 full trip is possible."},{"kind":"numeric","prompt":"How many coconuts remain for the final, smaller trip after that 1 full trip?","answer":39,"explain":"99 − 60 = 39 coconuts remain for the last, smaller trip."},{"kind":"mcq","prompt":"The rescue must happen in the correct order: (1) Chase Kaalu away from the grove (2) Count how many coconuts he dropped (3) Pack them into baskets (4) Load the baskets onto the rescue truck. What is the correct order?","options":["4, 3, 2, 1","1, 3, 2, 4","1, 2, 3, 4","2, 1, 3, 4"],"answer":2,"explain":"You must first chase Kaalu away (1), then count the dropped coconuts (2), then pack them (3), and finally load the truck (4)."}]}]},{"id":"symmetricaldesigns5","index":9,"name":"Symmetrical Designs","subtitle":"Computational Thinking — Chapter 10","emoji":"❄️","palette":{"from":"#38bdf8","to":"#0c4a6e"},"lessons":[{"id":"sd1","title":"Spin and Match","icon":"🌀","kind":"lesson","story":"You enter the Whirling Courtyard, where giant stone medallions spin slowly on the floor. The Keeper says each medallion will only lock into place once you can tell exactly how many times it matches itself in one full spin.","teach":[{"title":"What Is Rotational Symmetry?","body":"A design has rotational symmetry if, when you spin it around its centre point, it looks exactly the same as the start — before finishing one full 360° turn. The order of rotational symmetry is how many times it matches during that one full turn (including back at the start).","visual":"🌀"},{"title":"Finding the Order","body":"To find the order, imagine spinning the shape slowly and counting every moment it looks unchanged. An equilateral triangle matches 3 times (every 120°), so its order is 3. A shape that only matches once, after a full 360°, has order 1 — that means it has no real rotational symmetry.","visual":"🔺"}],"questions":[{"kind":"mcq","prompt":"A regular pentagon (5 equal sides, 5 equal angles) is spun around its centre point. How many times will it look exactly the same during one full turn?","options":["3 times","4 times","5 times","1 time"],"answer":2,"explain":"A regular pentagon matches itself every 72° (360° ÷ 5), so it looks the same 5 times in one full turn."},{"kind":"numeric","prompt":"A plus-sign (+) shape, where all four arms are exactly the same length and width, is rotated around its centre. What is its order of rotational symmetry?","answer":4,"explain":"The plus-sign matches itself every 90°, which happens 4 times in a full 360° turn."},{"kind":"mcq","prompt":"Which of these shapes has NO rotational symmetry other than the trivial full 360° turn (its order is 1)?","options":["A scalene triangle (three different side lengths)","An equilateral triangle","A regular hexagon","A square"],"answer":0,"explain":"A scalene triangle has no matching sides or angles, so spinning it only ever matches at a full 360° turn — order 1."},{"kind":"numeric","prompt":"The capital letter S looks exactly the same after being rotated 180° around its centre, but at no other angle less than 360°. What is the order of rotational symmetry of the letter S?","answer":2,"explain":"S matches itself only once more before completing the full turn (at 180°), so its order of rotational symmetry is 2."}]},{"id":"sd2","title":"Mirror Lines in Tricky Shapes","icon":"🪞","kind":"lesson","story":"Beyond the courtyard lies the Hall of a Thousand Mirrors. Every wall shows a shape, and each shape hides several fold lines. Count every line of symmetry correctly, or the mirrors will scramble your reflection forever!","teach":[{"title":"Symmetry Beyond Simple Shapes","body":"In Class 4 you met shapes with one or a few lines of symmetry. Many-sided regular shapes hide even more — a regular hexagon (6 equal sides) actually has 6 different lines of symmetry running through it.","visual":"⬡"},{"title":"The Regular Polygon Rule","body":"Here's a handy rule: a regular polygon with n equal sides always has exactly n lines of symmetry. So a regular octagon (8 sides) has 8 lines, and a regular decagon (10 sides) has 10 lines.","visual":"📐"}],"questions":[{"kind":"numeric","prompt":"How many lines of symmetry does a regular hexagon (all 6 sides and angles equal) have?","answer":6,"explain":"A regular polygon with n sides has n lines of symmetry, so a hexagon (6 sides) has 6 lines."},{"kind":"mcq","prompt":"A regular 8-sided shape (regular octagon), like most STOP signs, has how many lines of symmetry?","options":["8","1","6","4"],"answer":0,"explain":"Using the rule for regular polygons, an octagon has 8 sides, so it has 8 lines of symmetry."},{"kind":"mcq","prompt":"Which of these capital letters has exactly ONE line of symmetry, running straight down the middle (top to bottom)?","options":["T","O","H","S"],"answer":0,"explain":"T folds neatly top-to-bottom along one vertical line only. H has two lines (vertical and horizontal), O has many, and S has none at all."},{"kind":"numeric","prompt":"A perfectly regular five-pointed star, like the ones on many flags, has how many lines of symmetry?","answer":5,"explain":"Each point of the star lines up with a line of symmetry running through it and the middle of the opposite side, giving 5 lines in total."}]},{"id":"sd3","title":"Complete the Pattern","icon":"🧩","kind":"lesson","story":"The Pattern Weaver is halfway through a magical tapestry and has lost her thread! She describes each unfinished design to you — use symmetry to work out exactly what belongs in the missing spot.","teach":[{"title":"Reading a Mirrored Pattern","body":"In a pattern that is symmetric about a middle line, every spot on one side has a matching partner spot on the other side, at the same distance from the middle. Find the partner, and you know what belongs in the gap.","visual":"🧩"},{"title":"Filling in Rotational Patterns","body":"If a circular design has rotational symmetry of order N, then all N sections around the centre must be exact copies of each other. If even one section looks different, the true order of symmetry is broken.","visual":"⚙️"}],"questions":[{"kind":"mcq","prompt":"A row of 5 wall tiles is painted so the pattern is symmetric about the middle tile (tile 3). Tile 1 = Red, Tile 2 = Blue, Tile 3 = Yellow, Tile 4 = ?, Tile 5 = Red. What colour must Tile 4 be?","options":["Red","Green","Blue","Yellow"],"answer":2,"explain":"Tile 4 is the same distance from the middle (tile 3) as Tile 2, so it must match Tile 2's colour: Blue."},{"kind":"mcq","prompt":"A flag pattern has 2 rows and 4 columns, symmetric left-to-right (column 1 matches column 4, and column 2 matches column 3). Row 1 reads: Blue, Green, ?, Blue. What colour goes in the blank?","options":["Green","Yellow","Blue","Red"],"answer":0,"explain":"The blank is in column 3, which must mirror column 2 (Green)."},{"kind":"mcq","prompt":"A circular badge has 4 identical symbols spaced evenly around its centre, giving it rotational symmetry of order 4. Three of the spots show a star, but the fourth spot is blank. What must go in the blank spot to keep the order-4 symmetry true?","options":["A moon","Nothing — it can stay blank","A star","A different symbol from the other three"],"answer":2,"explain":"True order-4 rotational symmetry means all 4 spots around the centre must be identical, so the missing spot must also be a star."},{"kind":"numeric","prompt":"A square rug is symmetric across both its horizontal AND vertical middle lines, so all 4 corner sections match each other exactly. If the top-left corner uses exactly 6 red threads, how many red threads are used across all 4 corners in total?","answer":24,"explain":"Since all 4 corners must be identical copies, the total is 6 × 4 = 24 red threads."}]},{"id":"sd4","title":"Fold, Cut, Unfold — Level Up","icon":"✂️","kind":"lesson","story":"The Origami Sentry blocks the bridge with a stack of folded paper and a tiny hole-punch. This time the folds are trickier than anything you tried in Class 4 — predict correctly, or start folding all over again!","teach":[{"title":"Two Folds Make Four Layers","body":"Fold a paper in half left-to-right, then fold it in half again top-to-bottom, and you get 4 layers stacked together. Punch ONE hole through all the layers, and when you fully unfold the paper, that single hole becomes 4 holes — mirrored across both fold lines.","visual":"📄"},{"title":"More Folds, More Copies","body":"Each extra fold doubles the number of layers, which doubles the number of holes a single punch creates. Fold three times (8 layers) and one punch becomes 8 holes when unfolded — just like the repeating arms of a paper snowflake.","visual":"❄️"}],"questions":[{"kind":"numeric","prompt":"A square paper is folded in half left-to-right, then folded in half again top-to-bottom, making 4 layers. If you punch ONE hole through all the layers, how many holes appear when the paper is fully unfolded?","answer":4,"explain":"Each of the 4 stacked layers gets punched, so unfolding reveals 4 holes, mirrored across both fold lines."},{"kind":"mcq","prompt":"A paper is folded in half three times in a row (each fold halving it again), making 8 layers, then one hole is punched through all of them. How many holes will you see after fully unfolding?","options":["3","6","8","4"],"answer":2,"explain":"One punch goes through all 8 stacked layers, so unfolding reveals 8 holes in total."},{"kind":"mcq","prompt":"A square sheet is folded twice to make a smaller square (fold left-right, then top-bottom). A small triangle is snipped off the corner of the folded square that sits exactly at the centre of the original sheet. When unfolded, what appears in the middle of the sheet?","options":["A hole only in one quarter","No hole at all","A diamond-shaped hole in the very centre","A single triangle near one edge"],"answer":2,"explain":"A snip at the folded corner that was the sheet's true centre gets copied into all 4 quarters, joining up into one diamond-shaped hole in the middle."},{"kind":"numeric","prompt":"A circular paper is folded in half, then folded in half again (a quarter-circle wedge), then folded in half once more (an eighth-circle wedge). A hole is punched near the folded tip. How many holes appear when the paper is fully unfolded?","answer":8,"explain":"Three folds create 8 stacked layers, so one punch near the tip becomes 8 holes arranged evenly around the circle."}]},{"id":"sd5","title":"Two Symmetries, One Shape","icon":"☯️","kind":"lesson","story":"In the Twin Towers of Balance, one tower only understands mirrors and the other only understands spins. To cross the bridge between them, you must show that some shapes speak both languages at once.","teach":[{"title":"Some Shapes Have Both","body":"A shape can have line symmetry AND rotational symmetry at the same time. A square has 4 lines of symmetry AND rotational order 4. But the letter S has rotational symmetry (order 2) with zero lines of symmetry, while the letter A has 1 line of symmetry but no extra rotational symmetry at all.","visual":"🔁"},{"title":"Double Reflection = Rotation","body":"Here is a neat trick: if you reflect a picture across one line, then reflect that result across a second line crossing the first, the final picture looks exactly like the original rotated around the crossing point — by double the angle between the two lines.","visual":"🔄"}],"questions":[{"kind":"mcq","prompt":"Which shape has BOTH at least one line of symmetry AND rotational symmetry of order greater than 1?","options":["Letter F","Equilateral triangle","Letter S","Scalene triangle"],"answer":1,"explain":"An equilateral triangle has 3 lines of symmetry and rotational order 3, so it has both kinds. The others have only one kind or none."},{"kind":"mcq","prompt":"Which of these capital letters has rotational symmetry but NO line of symmetry at all?","options":["F","T","Z","A"],"answer":2,"explain":"Z looks the same after a 180° rotation (order 2) but cannot be folded along any line to match itself. A and T each have one vertical line but no extra rotation, and F has neither."},{"kind":"numeric","prompt":"Picture P is reflected across line AB to make picture R. Then picture R is reflected across line CD, which crosses AB at a right angle (90°). Compared to the original picture P, the final image is the same as P rotated by how many degrees around the crossing point?","answer":180,"explain":"Reflecting twice across two lines that cross at an angle equals a rotation of double that angle: 2 × 90° = 180°."},{"kind":"mcq","prompt":"Which of these does NOT have its number of lines of symmetry equal to its order of rotational symmetry?","options":["Letter S (0 lines, order 2)","A regular hexagon (6 lines, order 6)","An equilateral triangle (3 lines, order 3)","A square (4 lines, order 4)"],"answer":0,"explain":"The letter S has 0 lines of symmetry but rotational order 2, so the two numbers don't match. Regular polygons always have them equal."}]},{"id":"sd6","title":"Designs All Around","icon":"🏵️","kind":"lesson","story":"The final gallery of the Study Atlas museum is filled with real-world art: kolams, wheel emblems, flags and snowflakes. The curator asks you to spot the hidden computational patterns behind their beauty.","teach":[{"title":"Symmetry in Real Life","body":"Rangoli and kolam patterns, national emblems, vehicle wheels, and snowflakes are often designed with both reflective and rotational symmetry, because balanced, repeating designs look pleasing and are easier to plan and draw.","visual":"🎴"},{"title":"Using Abstraction to Spot Symmetry","body":"Computational thinkers use Abstraction — they ignore small details like colour and focus only on the outline and the repeating parts. This makes it much faster to count lines of symmetry or work out the order of rotation in a busy real-world design.","visual":"🧠"}],"questions":[{"kind":"numeric","prompt":"A wheel emblem has 24 identical, evenly spaced spokes arranged around its centre. What is the order of its rotational symmetry?","answer":24,"explain":"With 24 identical spokes spaced evenly (every 15°), the design matches itself 24 times in one full turn."},{"kind":"mcq","prompt":"A hexagonal snowflake has 6 identical arms spreading out from the centre, and each arm is itself symmetric down its own middle line. How many lines of symmetry does the whole snowflake have in total?","options":["3","1","12","6"],"answer":3,"explain":"Each of the 6 arms sits on its own line of symmetry running through the centre, giving 6 lines in total."},{"kind":"mcq","prompt":"A circular logo is divided into 5 equal, identically coloured pie-slice wedges around the centre, so it has rotational symmetry of order 5. Does it necessarily ALSO have line (reflective) symmetry?","options":["Yes, every rotationally symmetric shape automatically has line symmetry","No, wedge shapes can never have line symmetry","Yes, but only if each wedge is itself mirror-symmetric about its own centre line","No, rotational symmetry never comes with line symmetry"],"answer":2,"explain":"Rotational symmetry doesn't guarantee line symmetry — it depends on whether each individual wedge design is itself mirror-symmetric."},{"kind":"numeric","prompt":"A traditional kolam pattern is made of 8 identical loops arranged evenly in a circle around a central dot. What is the order of rotational symmetry of this kolam?","answer":8,"explain":"With 8 identical, evenly spaced loops, the pattern matches itself 8 times in one full turn."}]},{"id":"sd-boss","title":"The Symmetry Sentinel","icon":"🛡️","kind":"boss","story":"At the top of the Hall of Reflections stands the Symmetry Sentinel, built from spinning shields and mirrored armour. To pass, you must answer every challenge about rotation, reflection, folding, and pattern completion — all at once.","boss":{"name":"The Symmetry Sentinel","taunt":"Fold me, spin me, mirror me twice — one wrong move and you're marching straight back to Chapter 1!"},"questions":[{"kind":"numeric","prompt":"A regular heptagon has 7 equal sides and 7 equal angles. What is its order of rotational symmetry?","answer":7,"explain":"A regular polygon with n sides has rotational symmetry of order n, so a heptagon's order is 7."},{"kind":"mcq","prompt":"Which shield has rotational symmetry of order 3 but NO line of symmetry at all?","options":["A regular hexagon","A square","A triskelion (three curved arms, all twisted the same way)","An equilateral triangle"],"answer":2,"explain":"A triskelion's curved, twisted arms match every 120° (order 3) but no straight fold line can ever make its halves match. The other shapes have both kinds of symmetry."},{"kind":"mcq","prompt":"A row of 7 lockers is painted symmetric about the middle locker (locker 4). Locker 1 = Green, Locker 2 = Blue, Locker 3 = Red, Locker 4 = Yellow, Locker 5 = Red, Locker 6 = Blue, Locker 7 = ?. What colour is Locker 7?","options":["Green","Yellow","Blue","Red"],"answer":0,"explain":"Locker 7 is the same distance from the middle (locker 4) as Locker 1, so it must match Locker 1's colour: Green."},{"kind":"numeric","prompt":"Image P is reflected across line AB, and the result is reflected again across line CD, which crosses AB at 45°. The final image is the same as P rotated by how many degrees about the crossing point?","answer":90,"explain":"Two reflections across lines crossing at an angle equal a rotation of double that angle: 2 × 45° = 90°."},{"kind":"numeric","prompt":"A 4-quadrant shield design is symmetric across both its horizontal AND vertical middle lines. The top-left quadrant has exactly 3 silver stars. How many silver stars appear on the whole shield in total?","answer":12,"explain":"Since all 4 quadrants must be identical copies, the total is 3 × 4 = 12 silver stars."},{"kind":"mcq","prompt":"The Symmetry Sentinel holds up four floating shields. Which shield has the MOST total symmetry, counting both its lines of symmetry AND its order of rotational symmetry added together?","options":["An equilateral triangle (3 lines + order 3 = 6 total)","A square (4 lines + order 4 = 8 total)","A rectangle that is not a square (2 lines + order 2 = 4 total)","A regular hexagon (6 lines + order 6 = 12 total)"],"answer":3,"explain":"The regular hexagon has the highest total: 6 lines of symmetry plus rotational order 6 equals 12, more than any of the other shields."}]}]},{"id":"grandmothersquilt5","index":10,"name":"Grandmother's Quilt","subtitle":"Computational Thinking — Chapter 11","emoji":"🧵","palette":{"from":"#f97316","to":"#7c2d12"},"lessons":[{"id":"gq1","title":"The Torn Pattern Strip","icon":"🧩","kind":"lesson","story":"Grandmother's oldest quilt strip got singed by a candle and a whole patch is missing! She says the patches always follow a hidden rhythm — figure out the pattern's rule and stitch in the missing patch before the Quilting Fair begins tomorrow.","teach":[{"title":"Spotting a Repeating Pattern","body":"In a repeating pattern, a small group of patches repeats again and again in the same order. To find a missing patch, first find the group that repeats, then figure out where in the repeating group the gap falls.","visual":"🔁"}],"questions":[{"kind":"mcq","prompt":"A quilt strip has patches in this order, left to right: red, blue, yellow, red, blue, yellow, red, blue, ___. What colour comes next?","options":["Blue","Green","Red","Yellow"],"answer":3,"explain":"The pattern \"red, blue, yellow\" repeats every 3 patches, and after red, blue comes yellow."},{"kind":"mcq","prompt":"A strip repeats the group \"green, green, purple\" over and over: green, green, purple, green, green, purple, green, green, purple, ... What is the 11th patch in the strip?","options":["Cannot be determined","Purple","Green","Blue"],"answer":2,"explain":"The group \"green, green, purple\" has 3 patches; the 11th patch is the 2nd patch of the 4th group (11 = 3×3 + 2), which is green."},{"kind":"numeric","prompt":"A pattern repeats every 4 patches: yellow, yellow, blue, red. How many yellow patches are there in the first 20 patches of the strip?","answer":10,"explain":"20 patches = 5 full groups of 4, and each group has 2 yellow patches, so 5 × 2 = 10 yellow patches."},{"kind":"mcq","prompt":"Looking at this torn strip: orange, pink, pink, orange, pink, pink, orange, ___, ___ — what are the two missing patches, in order?","options":["orange, orange","orange, pink","pink, orange","pink, pink"],"answer":3,"explain":"The repeating group is \"orange, pink, pink\"; after the 7th patch (orange, which starts a new group), the next two must be pink, pink."}]},{"id":"gq2","title":"Counting the Quilt Squares","icon":"🔢","kind":"lesson","story":"Grandmother wants to know exactly how much cloth to buy for her next big quilt, and she trusts you with the counting! Every quilt is stitched from small identical unit squares arranged in neat rows and columns — count carefully so no cloth is wasted.","teach":[{"title":"Area by Counting Unit Squares","body":"The area of a quilt made of identical unit squares is simply the number of rows multiplied by the number of columns — this tells you exactly how many squares of cloth are needed. Counting rows times columns is much faster than counting every single square one by one.","visual":"🟧"}],"questions":[{"kind":"numeric","prompt":"A quilt patch is arranged in 6 rows and 5 columns of unit squares. What is its total area in square units?","answer":30,"explain":"Area = rows × columns = 6 × 5 = 30 square units."},{"kind":"numeric","prompt":"A quilt is a perfect square with 9 unit squares along each side. What is its total area in square units?","answer":81,"explain":"A square grid of side 9 has area 9 × 9 = 81 square units."},{"kind":"mcq","prompt":"Grandmother has two quilt pieces: Piece A has 4 rows and 8 columns of unit squares. Piece B has 8 rows and 4 columns of unit squares. Which piece uses more cloth?","options":["They use exactly the same amount of cloth","Piece A uses more cloth","Cannot be determined","Piece B uses more cloth"],"answer":0,"explain":"Piece A's area is 4 × 8 = 32 and Piece B's area is 8 × 4 = 32 — swapping rows and columns doesn't change the total area."},{"kind":"numeric","prompt":"A rectangular quilt has an area of 48 square units and is arranged in 6 rows. How many columns of unit squares does it have?","answer":8,"explain":"Since area = rows × columns, columns = 48 ÷ 6 = 8."},{"kind":"numeric","prompt":"Grandmother joins two small quilt pieces edge to edge to make one bigger rectangle: one piece is 3 rows by 5 columns, and the other is 3 rows by 4 columns, joined along their matching 3-row sides. What is the total area of the combined quilt in square units?","answer":27,"explain":"Joining them side-by-side just adds their areas together: (3×5) + (3×4) = 15 + 12 = 27 square units."}]},{"id":"gq3","title":"The Quilt's Edge","icon":"📏","kind":"lesson","story":"Grandmother needs a ribbon trim sewn all around the outer edge of each quilt before the fair judges arrive. Help her measure exactly how much ribbon to cut by counting the unit-length edges around each quilt's border.","teach":[{"title":"Perimeter as the Distance Around","body":"The perimeter of a quilt is the total distance around its outer edge, measured in unit lengths. For a rectangle made of unit squares, you can find it by adding up all four sides: two lengths and two widths.","visual":"🎀"}],"questions":[{"kind":"numeric","prompt":"A rectangular quilt is 7 unit squares long and 4 unit squares wide. What is its perimeter in unit lengths?","answer":22,"explain":"Perimeter = 2 × (length + width) = 2 × (7 + 4) = 22 unit lengths."},{"kind":"numeric","prompt":"A square quilt has sides of 6 unit squares each. What is its perimeter?","answer":24,"explain":"A square's perimeter is 4 × side = 4 × 6 = 24 unit lengths."},{"kind":"mcq","prompt":"Grandmother cuts a rectangular quilt (8 units long, 3 units wide) exactly in half along its width, making two smaller rectangles each 4 units long and 3 units wide. How does the COMBINED perimeter of the two new pieces compare to the perimeter of the original quilt?","options":["The combined perimeter is exactly equal to the original quilt's perimeter","The combined perimeter is less than the original quilt's perimeter","The combined perimeter is greater than the original quilt's perimeter","Cannot be determined"],"answer":2,"explain":"The original perimeter is 2×(8+3) = 22, but the two new pieces together have perimeter 2×(4+3)×2 = 28 — cutting always adds two brand-new edges along the cut."},{"kind":"numeric","prompt":"A rectangular quilt has a perimeter of 30 unit lengths and is 9 units long. How many units wide is it?","answer":6,"explain":"Half the perimeter is 30 ÷ 2 = 15, and 15 − 9 (the length) = 6 units wide."}]},{"id":"gq4","title":"Block by Block","icon":"🧱","kind":"lesson","story":"The Grand Quilt for the village hall is far too big to stitch all at once, so Grandmother teaches you her secret: break the giant quilt into small identical blocks, sew each block separately, then join them all together like tiles.","teach":[{"title":"Decomposing into Repeating Blocks","body":"A big, complicated quilt can be broken down (decomposed) into many small, identical blocks that repeat across rows and columns — this is called tiling. Solving and building just ONE small block, then repeating it, is much easier than planning the whole giant quilt at once.","visual":"🧱"}],"questions":[{"kind":"numeric","prompt":"A big quilt is tiled using small 2x2 unit-square blocks, arranged 4 blocks across and 3 blocks down. How many small blocks are used in total?","answer":12,"explain":"Total blocks = blocks across × blocks down = 4 × 3 = 12 blocks."},{"kind":"numeric","prompt":"Each small block from the last puzzle covers 2 rows and 2 columns of unit squares (an area of 4 square units). What is the total area of the whole big quilt in square units?","answer":48,"explain":"12 blocks × 4 square units each = 48 square units total (this matches 8 columns × 6 rows = 48)."},{"kind":"mcq","prompt":"A quilt maker wants to tile a big rectangle that is 12 units wide and 8 units tall using identical square blocks that are 4 units on each side, with no gaps or overlaps. How many blocks fit across the width, and how many fit down the height?","options":["3 blocks across and 3 blocks down","3 blocks across and 2 blocks down","4 blocks across and 3 blocks down","2 blocks across and 3 blocks down"],"answer":1,"explain":"12 ÷ 4 = 3 blocks fit across the width, and 8 ÷ 4 = 2 blocks fit down the height."},{"kind":"numeric","prompt":"Using the same 12-by-8 quilt tiled with 4-unit square blocks, how many blocks are needed in total to tile the whole quilt?","answer":6,"explain":"3 blocks across × 2 blocks down = 6 blocks in total."},{"kind":"mcq","prompt":"A quilt block pattern named \"Pinwheel\" is repeated 6 times to make a table runner. If Grandmother wants to make a runner exactly twice as long by repeating the SAME Pinwheel block, what should she do?","options":["Design a completely new, different block","Use only 3 Pinwheel blocks","Repeat the same Pinwheel block 12 times instead of 6","Make each Pinwheel block twice as big"],"answer":2,"explain":"Because the design is decomposed into one repeating block, doubling the length just means repeating the same block more times — 6 × 2 = 12."}]},{"id":"gq5","title":"Symmetry in the Stitches","icon":"🪞","kind":"lesson","story":"For the fair's centrepiece quilt, Grandmother insists every row must mirror itself perfectly from left to right, like a reflection in a pond. Check her rows of patches for perfect symmetry before she starts stitching for real.","teach":[{"title":"Checking for Symmetry","body":"A row of patches is symmetric (mirror-matched) if reading it from left to right gives the exact same sequence as reading it from right to left. Checking symmetry is a handy way computers and quilters both verify a pattern is correct before finishing the work.","visual":"🪞"}],"questions":[{"kind":"mcq","prompt":"A row of patches reads, left to right: yellow, green, blue, green, yellow. Is this row symmetric (a mirror match) from left to right?","options":["Cannot be determined","Yes, it reads the same forwards and backwards","No, the middle patch is wrong","No, the 2nd and 4th patches don't match"],"answer":1,"explain":"Reversing the row gives yellow, green, blue, green, yellow — exactly the same as the original, so it is symmetric."},{"kind":"mcq","prompt":"A row of patches reads: red, white, blue, white, red, blue. Is this row symmetric from left to right?","options":["No — the middle two patches don't match","Cannot be determined","Yes, it is perfectly symmetric","No — the first and last patches (red and blue) don't match"],"answer":3,"explain":"For a row to be symmetric, the 1st and last patches must match — here the first is red and the last is blue, so it fails."},{"kind":"mcq","prompt":"A row of 6 patches is being designed to be symmetric. The first three patches are already stitched: red, blue, green. What must the last three patches (positions 4, 5, 6) be for the whole row to be symmetric?","options":["red, blue, green","green, blue, red","green, red, blue","blue, green, red"],"answer":1,"explain":"For symmetry, position 4 must match position 3 (green), position 5 must match position 2 (blue), and position 6 must match position 1 (red)."},{"kind":"numeric","prompt":"A symmetric row has 9 patches. Only the first 5 are visible so far: blue, blue, yellow, red, green (the 5th patch is the exact middle of the row). How many patches in the FULL row of 9 will be yellow?","answer":2,"explain":"Position 3 (yellow) mirrors position 7 on the other side of the middle, giving exactly 2 yellow patches in the full symmetric row of 9."}]},{"id":"gq6","title":"The Colour-Count Puzzle","icon":"🎨","kind":"lesson","story":"The fair judges want every quilt square to use exactly equal amounts of each thread colour, no cheating! Count the colours patch by patch across Grandmother's grids to prove her quilts are perfectly fair.","teach":[{"title":"Counting by Colour in a Grid","body":"In a grid puzzle, you can count how many unit squares of each colour appear by checking each row carefully and adding up the totals. Comparing colour counts this way tells you whether a design is balanced or unequal, without needing to measure anything.","visual":"🔍"}],"questions":[{"kind":"numeric","prompt":"A quilt square is 4 rows by 4 columns (16 unit squares total). Exactly half the squares are red and the rest are yellow. How many squares are yellow?","answer":8,"explain":"Half of 16 squares is 8, so 8 squares are yellow and 8 are red."},{"kind":"mcq","prompt":"A 6x6 grid quilt (36 squares) is described row by row: Row 1 is all black, Row 2 is all white, Row 3 is all black, Row 4 is all white, Row 5 is all black, Row 6 is all white (6 squares per row). Does this grid have an EQUAL number of black and white squares?","options":["No — there are more black squares than white","Cannot be determined without seeing the grid","Yes — 18 black squares and 18 white squares, exactly equal","No — there are more white squares than black"],"answer":2,"explain":"3 rows are fully black (3×6=18) and 3 rows are fully white (3×6=18), so the counts are exactly equal."},{"kind":"mcq","prompt":"A different 6x6 grid quilt has this pattern: Rows 1, 2, and 3 are each fully black (6 black squares per row). Rows 4, 5, and 6 each alternate one white then one black square across the row, giving 3 white and 3 black squares per row. Which colour has MORE total squares in this 36-square quilt?","options":["They are exactly equal","Cannot be determined","Black has more squares (27 black vs 9 white)","White has more squares"],"answer":2,"explain":"Rows 1–3 give 18 black squares, and rows 4–6 add 9 more black and 9 white, for totals of 27 black and 9 white — black has far more."},{"kind":"numeric","prompt":"In a quilt square with 5 rows and 5 columns (25 unit squares), the centre row and the centre column are both stitched in gold thread, and every other square is stitched in blue. How many squares are gold? (The one square where the centre row and centre column cross should be counted only once.)","answer":9,"explain":"The centre row has 5 gold squares and the centre column has 5 gold squares, but they share 1 square where they cross, so 5 + 5 − 1 = 9 gold squares total."},{"kind":"numeric","prompt":"A rectangular quilt is 8 rows by 10 columns (80 squares total). Every square in the outer border (the outermost ring of squares) is stitched maroon, and every square inside the border is stitched cream. How many squares are maroon?","answer":32,"explain":"Border squares = 2×(rows+columns)−4 = 2×(8+10)−4 = 32 maroon squares (the inner 6×8=48 squares are cream, and 32+48=80 checks out)."}]},{"id":"gq-boss","title":"Mothgrim, the Pattern Unraveler","icon":"👻","kind":"boss","story":"At the very top of Grandmother's attic, moth-eaten shadows swirl together into Mothgrim, the Pattern Unraveler, who has been secretly nibbling holes in every quilt in the village! Solve his tangle of pattern, area, perimeter, block, symmetry, and colour-counting puzzles all at once to stitch every quilt back to perfection and send him fluttering away for good.","teach":[{"title":"Every Quilting Trick at Once","body":"Mothgrim's puzzles mix everything you've learned: spotting repeating patterns, counting area, measuring perimeter, decomposing into blocks, checking symmetry, and counting colours. Read each puzzle slowly, picture the grid in your mind, and pick the right trick before you answer.","visual":"🧵"}],"boss":{"name":"Mothgrim, the Pattern Unraveler","taunt":"Snip snip! I've chewed every stitch to bits — patch me back together if you dare!"},"questions":[{"kind":"mcq","prompt":"A quilt strip repeats the group \"brown, brown, cream\" over and over: brown, brown, cream, brown, brown, cream, ... What is the 14th patch?","options":["Brown","White","Cream","Cannot be determined"],"answer":0,"explain":"14 = 3×4 + 2, so the 14th patch is the 2nd patch in its group of \"brown, brown, cream\" — brown."},{"kind":"numeric","prompt":"A quilt is 7 rows by 9 columns of unit squares. What is its total area in square units?","answer":63,"explain":"Area = rows × columns = 7 × 9 = 63 square units."},{"kind":"numeric","prompt":"A rectangular quilt is 10 units long and 6 units wide. What is its perimeter in unit lengths?","answer":32,"explain":"Perimeter = 2 × (length + width) = 2 × (10 + 6) = 32 unit lengths."},{"kind":"mcq","prompt":"A big quilt, 20 units wide and 15 units tall, is tiled using identical square blocks that are 5 units on each side. How many blocks are needed in total?","options":["20 blocks","4 blocks","15 blocks","12 blocks"],"answer":3,"explain":"4 blocks fit across (20÷5) and 3 blocks fit down (15÷5), so 4 × 3 = 12 blocks in total."},{"kind":"mcq","prompt":"A row of 8 patches must be symmetric. The first four patches are: teal, teal, gold, teal. What must the last four patches (positions 5-8) be?","options":["teal, gold, teal, teal","gold, teal, teal, teal","teal, teal, teal, gold","teal, teal, gold, teal"],"answer":0,"explain":"For symmetry, position 5 mirrors position 4 (teal), position 6 mirrors position 3 (gold), and positions 7 and 8 mirror positions 2 and 1 (teal, teal)."},{"kind":"numeric","prompt":"A rectangular quilt is 6 rows by 9 columns (54 squares). Every square in the outer border is stitched silver, and the rest are stitched navy. How many squares are silver?","answer":26,"explain":"Border squares = 2×(rows+columns)−4 = 2×(6+9)−4 = 26 silver squares."},{"kind":"numeric","prompt":"A 4x4 quilt block (16 squares) is repeated to tile a giant quilt that has 5 blocks across and 5 blocks down. What is the total area of the giant quilt in square units?","answer":400,"explain":"5 × 5 = 25 total blocks, each with an area of 16, so 25 × 16 = 400 square units altogether."}]}]},{"id":"racingseconds5","index":11,"name":"Racing Seconds","subtitle":"Computational Thinking — Chapter 12","emoji":"🏃","palette":{"from":"#fb7185","to":"#881337"},"lessons":[{"id":"rs1","title":"The Starter's Whistle","icon":"⏱️","kind":"lesson","story":"You arrive at the Riverside Sports Day just as the starter raises her whistle. The timekeeper's stopwatch is covered in scribbles, and she needs a sharp-eyed helper who can convert seconds and minutes correctly before the very first race begins!","teach":[{"title":"Seconds Inside a Minute","body":"Every minute is made of exactly 60 seconds, no more and no less. To turn minutes into seconds, multiply by 60; to turn seconds back into minutes, divide by 60.","visual":"⏱️"},{"title":"Adding Race Times","body":"When you add two lengths of time together, if the seconds add up to 60 or more, carry 1 minute over — just like carrying a ten when adding numbers.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"A sprint race lasts exactly 2 minutes. How many seconds is that?","answer":120,"explain":"Each minute has 60 seconds, so 2 minutes = 2 x 60 = 120 seconds."},{"kind":"numeric","prompt":"A runner's stopwatch reads 150 seconds when she crosses the finish line. How many whole minutes is that?","answer":2,"explain":"150 seconds divided by 60 gives 2 full minutes (with 30 seconds left over)."},{"kind":"mcq","prompt":"Runner Priya finishes a lap in 1 minute 40 seconds. Runner Sam finishes the same lap in 95 seconds. Who finished faster?","options":["Priya, because her time uses minutes","Cannot be determined","They finished at exactly the same time","Sam, because 95 seconds is less than 100 seconds"],"answer":3,"explain":"Priya's time is 1 minute 40 seconds = 100 seconds, and 95 seconds is less than 100 seconds, so Sam was faster."},{"kind":"numeric","prompt":"A relay team's first runner takes 45 seconds and the second runner takes 50 seconds. What is their combined time in seconds?","answer":95,"explain":"45 + 50 = 95 seconds added together."},{"kind":"numeric","prompt":"The combined relay time from the last question was 95 seconds. Written as minutes and seconds, how many seconds are left over after taking out 1 full minute?","answer":35,"explain":"95 seconds = 60 seconds (1 minute) + 35 seconds, so 35 seconds remain."}]},{"id":"rs2","title":"Photo Finish Puzzle","icon":"🏁","kind":"lesson","story":"The 100-metre dash just ended in a blur, and the finish-line camera jammed! The judges only have scattered clues about who crossed when. Line up the clues in your head to work out the real finishing order.","teach":[{"title":"Ordering From Clues","body":"When you know how far apart runners finished, you can place them on an imaginary timeline, like marks on a ruler. Smaller time means finishing earlier, so the smallest number always wins the race.","visual":"📏"},{"title":"One Step at a Time","body":"Solve clue puzzles by fixing one runner's time first, then using each remaining clue to work out the next runner's time, one at a time, just like a computer follows instructions in order.","visual":"🔗"}],"questions":[{"kind":"mcq","prompt":"Reha finishes the race at 40 seconds. Kiran finishes 3 seconds after Reha. Who won the race?","options":["Reha","They tied","Kiran","Cannot be determined"],"answer":0,"explain":"Kiran finished later (43 seconds), which means slower, so Reha, with the smaller time, won."},{"kind":"numeric","prompt":"Using the clue above, at what time (in seconds) did Kiran finish?","answer":43,"explain":"Kiran finished 3 seconds after Reha's 40 seconds, so 40 + 3 = 43 seconds."},{"kind":"mcq","prompt":"Three friends race. Aarav finishes before Bela. Bela finishes before Chetan. Who finished the race LAST?","options":["Cannot be determined","Chetan","Bela","Aarav"],"answer":1,"explain":"Aarav is before Bela, and Bela is before Chetan, so the order is Aarav, Bela, Chetan — Chetan is last."},{"kind":"numeric","prompt":"In a 4-runner race, Meena finishes at 30 seconds. Dev finishes 5 seconds after Meena. Isha finishes 2 seconds before Dev. At what time (in seconds) does Isha finish?","answer":33,"explain":"Dev finishes at 30 + 5 = 35 seconds. Isha finishes 2 seconds before that: 35 - 2 = 33 seconds."},{"kind":"mcq","prompt":"Using the times from the last question (Meena at 30 s, Dev at 35 s, Isha at 33 s), who finished the race first among these three?","options":["Dev","Isha","It was a three-way tie","Meena"],"answer":3,"explain":"Meena's time of 30 seconds is the smallest among 30, 35, and 33, so Meena finished first."}]},{"id":"rs3","title":"The Lap-Counter's Tally","icon":"🔁","kind":"lesson","story":"The stadium's automatic lap counter has broken down mid-race! You must track each runner's steady pace by hand, counting laps and beeps so nobody gets cheated out of their true finishing time.","teach":[{"title":"Repeating Actions in a Loop","body":"When something happens again and again at a fixed gap of time, like a lap every so many seconds, you can predict future events just by repeating the pattern — this is called a loop in computational thinking.","visual":"🔁"},{"title":"Skip Counting to Predict","body":"To find when the 5th event of a loop happens, multiply the gap by one less than the event number, since the loop already started at time zero for the 1st event.","visual":"🧮"}],"questions":[{"kind":"numeric","prompt":"A runner completes one lap every 20 seconds and starts the race at 0 seconds. At what time (in seconds) does she finish her 3rd lap?","answer":60,"explain":"3 laps of 20 seconds each: 3 x 20 = 60 seconds."},{"kind":"numeric","prompt":"A relay baton beeps every 15 seconds, starting with its first beep at the 15-second mark. At what time (in seconds) is the 4th beep?","answer":60,"explain":"The 4th beep happens after 4 gaps of 15 seconds: 4 x 15 = 60 seconds."},{"kind":"mcq","prompt":"A training whistle blows once every 10 seconds, starting at 0 seconds (the 1st blow). At what time is the whistle's 6th blow?","options":["60 seconds","6 seconds","40 seconds","50 seconds"],"answer":3,"explain":"The 1st blow is at 0 seconds, so the 6th blow comes after 5 more gaps of 10 seconds: 5 x 10 = 50 seconds."},{"kind":"numeric","prompt":"A drone camera flies past the stands every 25 seconds, first passing at 0 seconds. How many times will it pass the stands from 0 seconds up to and including the 100-second mark?","answer":5,"explain":"It passes at 0, 25, 50, 75, and 100 seconds — that is 5 passes in total."}]},{"id":"rs4","title":"Grid-Track Sprint","icon":"🐢","kind":"lesson","story":"Down at the school fair, two toy robots are racing along a straight numbered track made of equal boxes. Each robot moves at its own steady speed, and the crowd wants to know exactly who reaches the finish box first, and by how much!","teach":[{"title":"Speed as Time Per Step","body":"If you know how many seconds it takes to move one box, you can find the total time for any number of boxes by multiplying the seconds-per-box by the number of boxes.","visual":"🐢"},{"title":"Comparing Two Racers","body":"To see who wins, work out each racer's total time separately, then subtract the smaller time from the larger time to find out by how many seconds one beat the other.","visual":"⚡"}],"questions":[{"kind":"numeric","prompt":"Robot A moves 1 box every 6 seconds. The finish line is 5 boxes away. How many seconds does Robot A take to reach the finish line?","answer":30,"explain":"5 boxes x 6 seconds per box = 30 seconds."},{"kind":"numeric","prompt":"Robot B moves 1 box every 4 seconds and also has 5 boxes to travel. How many seconds does Robot B take to reach the finish line?","answer":20,"explain":"5 boxes x 4 seconds per box = 20 seconds."},{"kind":"mcq","prompt":"Using Robot A (30 seconds) and Robot B (20 seconds) from the last two questions, how many seconds after Robot B does Robot A reach the finish line?","options":["20 seconds","50 seconds","10 seconds","30 seconds"],"answer":2,"explain":"Robot A takes 30 seconds and Robot B takes 20 seconds, so Robot A arrives 30 - 20 = 10 seconds later."},{"kind":"numeric","prompt":"Robot C moves 1 box every 3 seconds. If the finish line is 8 boxes away, how many seconds does Robot C take to finish?","answer":24,"explain":"8 boxes x 3 seconds per box = 24 seconds."},{"kind":"mcq","prompt":"Robot D takes 4 seconds per box and finishes a race in 28 seconds. How many boxes long was the track?","options":["4 boxes","24 boxes","7 boxes","32 boxes"],"answer":2,"explain":"Total time divided by seconds-per-box gives the number of boxes: 28 / 4 = 7 boxes."}]},{"id":"rs5","title":"The Arrival Board Mix-Up","icon":"🚌","kind":"lesson","story":"At the town bus depot, the digital arrival board has gone haywire, showing riddles instead of times! The dispatcher needs your help working backward and forward through clues to fix every scheduled arrival before the buses roll out.","teach":[{"title":"Working Backward From an Arrival","body":"If you know when someone arrived and how long their journey took, you can find their start time by subtracting the journey length from the arrival time.","visual":"⏪"},{"title":"Chaining Time Clues","body":"When one person's time is described using another person's time, solve for the first person directly, then use that answer to work out the next one, step by step.","visual":"🔗"}],"questions":[{"kind":"numeric","prompt":"A bus leaves the depot at 3:00 PM and the journey takes 45 minutes. At what minute past 3 PM does it arrive (for example, answer 45 means 3:45 PM)?","answer":45,"explain":"3:00 PM plus 45 minutes of travel lands at 3:45 PM, which is 45 minutes past 3."},{"kind":"mcq","prompt":"A train arrives at the platform at 5:20 PM. The journey took 50 minutes. What time did the train leave its starting station?","options":["4:40 PM","5:10 PM","6:10 PM","4:30 PM"],"answer":3,"explain":"Working backward, 5:20 PM minus 50 minutes of travel gives a departure time of 4:30 PM."},{"kind":"numeric","prompt":"Runner X reaches the water station 12 minutes after starting. Runner Y reaches it 5 minutes after Runner X. If Runner X started at 9:00 AM (0 minutes), how many minutes after 9:00 AM does Runner Y reach the water station?","answer":17,"explain":"Runner X arrives at 12 minutes, and Runner Y arrives 5 minutes later: 12 + 5 = 17 minutes after 9:00 AM."},{"kind":"mcq","prompt":"Two friends board different buses. Bus 1 is scheduled to leave at 6:15 PM. Amit boards Bus 1 exactly 10 minutes before it leaves. Bus 2 leaves 20 minutes after Bus 1. If Riya boards Bus 2 exactly 10 minutes before IT leaves, what time does Riya board?","options":["6:35 PM","6:15 PM","6:05 PM","6:25 PM"],"answer":3,"explain":"Bus 2 leaves at 6:15 PM + 20 minutes = 6:35 PM, and Riya boards 10 minutes before that: 6:35 PM - 10 minutes = 6:25 PM."},{"kind":"numeric","prompt":"A cyclist's ride is scheduled to start at 4:50 PM but she arrives 8 minutes early. If the ride takes exactly 25 minutes from its scheduled start time, at what minute past 5 PM does the ride finish (for example, answer 15 means 5:15 PM)?","answer":15,"explain":"The ride is timed from its scheduled start (4:50 PM), not her early arrival: 4:50 PM + 25 minutes = 5:15 PM, which is 15 minutes past 5."}]},{"id":"rs6","title":"Handicap Race Day","icon":"🎽","kind":"lesson","story":"The final tune-up race before the big tournament uses a 'handicap' system, giving slower runners a head start so the race stays exciting. As official scorer, you must work out true finishing order once every head start is added in.","teach":[{"title":"Head Starts Change the Race","body":"In a handicap race, a runner's actual running time is added to any head-start time they were given, so their real finishing time is head start plus running time.","visual":"🎽"},{"title":"Comparing Totals Fairly","body":"To find the true winner, always compare each runner's FINAL total time, not just their running speed alone — sometimes a head start changes who crosses the line first.","visual":"⚖️"}],"questions":[{"kind":"numeric","prompt":"Runner P is given a 10-second head start and then runs the race in 50 seconds. What is Runner P's total finishing time in seconds?","answer":60,"explain":"Head start plus running time: 10 + 50 = 60 seconds."},{"kind":"numeric","prompt":"Runner Q gets no head start and runs the race in 65 seconds. Using Runner P's total time of 60 seconds from the last question, by how many seconds does Runner P beat Runner Q?","answer":5,"explain":"65 - 60 = 5 seconds, so Runner P finishes 5 seconds ahead of Runner Q."},{"kind":"mcq","prompt":"Runner S has a 15-second head start and runs the race in 55 seconds (total 70 seconds). Runner T has no head start and runs the race in 68 seconds. Who wins?","options":["Runner T, because 68 seconds is less than 70 seconds","Cannot be determined","They tie exactly","Runner S, because of the head start"],"answer":0,"explain":"Comparing total times, Runner T's 68 seconds beats Runner S's total of 70 seconds, even without a head start."},{"kind":"numeric","prompt":"Runner U is given a head start so that her total time becomes exactly 45 seconds. If Runner U's actual running time is 38 seconds, how many seconds was her head start?","answer":7,"explain":"Total time minus running time gives the head start: 45 - 38 = 7 seconds."}]},{"id":"rs-boss","title":"Chronos, the Time-Twisting Hare","icon":"🐇","kind":"boss","story":"At the grand finish line stands Chronos, a mischievous giant hare who has been scrambling every stopwatch, schedule, and starting gun in the valley just to watch racers get confused! Show him you can out-think every clock trick he throws and win the Racing Seconds trophy for good.","teach":[{"title":"Bring It All Together","body":"Chronos mixes every skill from this world: converting seconds and minutes, ordering finishers from clues, predicting repeating events, comparing racer speeds, working backward from arrival times, and adding head starts. Read each riddle slowly and pick the right tool before you answer.","visual":"🐇"}],"boss":{"name":"Chronos, the Time-Twisting Hare","taunt":"Tick-tock, tick-tock! By the time you finish counting, I'll have hopped three laps ahead of you!"},"questions":[{"kind":"numeric","prompt":"A race lasts 3 minutes. How many seconds is that?","answer":180,"explain":"3 minutes x 60 seconds = 180 seconds."},{"kind":"mcq","prompt":"Neel finishes a lap in 1 minute 5 seconds. Farah finishes the same lap in 70 seconds. Who was faster?","options":["Cannot be determined","They tied exactly","Neel, because 65 seconds is less than 70 seconds","Farah, because her time is in seconds"],"answer":2,"explain":"Neel's time is 1 minute 5 seconds = 65 seconds, and 65 seconds is less than Farah's 70 seconds, so Neel was faster."},{"kind":"numeric","prompt":"In a 3-runner race, Wren finishes at 28 seconds. Zara finishes 4 seconds after Wren. Omar finishes 1 second before Zara. At what time (in seconds) does Omar finish?","answer":31,"explain":"Zara finishes at 28 + 4 = 32 seconds. Omar finishes 1 second before that: 32 - 1 = 31 seconds."},{"kind":"numeric","prompt":"A checkpoint bell rings every 12 seconds, first ringing at 0 seconds. At what time (in seconds) is the 5th ring?","answer":48,"explain":"The 5th ring comes after 4 gaps of 12 seconds: 4 x 12 = 48 seconds."},{"kind":"mcq","prompt":"Robot E moves 1 box every 5 seconds along a 6-box track. Robot F moves 1 box every 3 seconds along the same 6-box track. How many seconds after Robot F does Robot E finish?","options":["12 seconds","30 seconds","18 seconds","6 seconds"],"answer":0,"explain":"Robot E takes 6 x 5 = 30 seconds and Robot F takes 6 x 3 = 18 seconds, so Robot E finishes 30 - 18 = 12 seconds later."},{"kind":"numeric","prompt":"A ferry arrives at the dock at 4:10 PM after a 35-minute crossing. At what minute past 3 PM did it leave (for example, answer 35 means 3:35 PM)?","answer":35,"explain":"Working backward: 4:10 PM minus 35 minutes of travel gives a departure time of 3:35 PM."},{"kind":"numeric","prompt":"Runner G is given an 8-second head start and runs the actual race in 47 seconds. What is Runner G's total finishing time in seconds?","answer":55,"explain":"Head start plus running time: 8 + 47 = 55 seconds."}]}]},{"id":"animaljumps5","index":12,"name":"Animal Jumps","subtitle":"Computational Thinking — Chapter 13","emoji":"🐸","palette":{"from":"#4ade80","to":"#14532d"},"lessons":[{"id":"aj1","title":"Hopper's First Leap","icon":"🐸","kind":"lesson","story":"Hopper the frog has washed up on Number-Line Island and must learn to hop home along the giant number line painted across the sand. Every jump she makes follows one simple rule — help her follow it exactly, again and again.","teach":[{"title":"What Is a Jump Rule?","body":"A jump rule tells a frog exactly how far to hop every single time — like 'always jump 3 steps forward.' Following the same rule over and over is called REPETITION, one of the most powerful ideas in computational thinking.","visual":"🐸"},{"title":"Simulating Step by Step","body":"To find where a frog lands, we don't guess — we simulate: add the jump size to the current position, one jump at a time, keeping track of the new position after each hop.","visual":"🔢"}],"questions":[{"kind":"mcq","prompt":"Hopper starts at 2 and jumps 3 steps forward, 4 times in a row. Where does she land?","options":["9","12","14","17"],"answer":2,"explain":"Each jump adds 3, so after 4 jumps: 2 + (3 × 4) = 14."},{"kind":"numeric","prompt":"A grasshopper starts at 0 and jumps 5 steps forward each time. Where is it after 6 jumps?","answer":30,"explain":"0 + (5 × 6) = 30."},{"kind":"numeric","prompt":"Hopper starts at 10 and jumps 4 steps forward each time. Where does she land after 3 jumps?","answer":22,"explain":"10 + (4 × 3) = 22."},{"kind":"mcq","prompt":"Which word best describes doing the exact same jump size over and over again?","options":["Sorting","Searching","Comparison","Repetition"],"answer":3,"explain":"Repeating the same instruction again and again is called repetition (or iteration) in computational thinking."}]},{"id":"aj2","title":"Hopping Backwards","icon":"🔙","kind":"lesson","story":"To cross back over Pebble River, Hopper must sometimes jump BACKWARD toward the shore she came from. She needs to master how backward jumps change her position on the number line.","teach":[{"title":"Backward Jumps","body":"A backward jump means we SUBTRACT the jump size from the current position instead of adding it. The algorithm is exactly the same — only the direction (and the operation) flips.","visual":"⬅️"},{"title":"Same Rule, Every Time","body":"Whether jumping forward or backward, a good algorithm always follows the exact same rule for every single jump — that consistency is what makes it predictable and easy to trace.","visual":"📏"}],"questions":[{"kind":"numeric","prompt":"Hopper starts at 20 and jumps 3 steps backward each time. Where does she land after 4 jumps?","answer":8,"explain":"20 − (3 × 4) = 8."},{"kind":"mcq","prompt":"A cricket starts at 15 and hops 2 steps backward each time. Where is it after 5 hops?","options":["7","3","10","5"],"answer":3,"explain":"15 − (2 × 5) = 5."},{"kind":"numeric","prompt":"A squirrel starts at 50 and jumps 6 steps backward each time. Where is it after 7 jumps?","answer":8,"explain":"50 − (6 × 7) = 8."},{"kind":"mcq","prompt":"If a frog jumps backward every time, what happens to its position after each jump?","options":["It increases by the jump size","It stays the same","It decreases by the jump size","It doubles"],"answer":2,"explain":"A backward jump subtracts the jump size, so the position always gets smaller."}]},{"id":"aj3","title":"Detective Hopper: Find the Rule","icon":"🕵️","kind":"lesson","story":"Hopper found mysterious frog tracks on the number line, but the rulebook that explains the jump size got soaked in the river! She must work backward from the start and landing spots to uncover the missing rule.","teach":[{"title":"Working Backward","body":"Sometimes we know the START and the END, but not the RULE. To find the jump size, find the total distance traveled and divide it by the number of jumps — this is called working backward, an important computational thinking skill.","visual":"🔍"},{"title":"Checking Your Answer","body":"Once you think you've found the jump size, always check it: start plus (jump size times number of jumps) should equal the landing spot exactly.","visual":"✅"}],"questions":[{"kind":"numeric","prompt":"A frog starts at 3 and after 5 equal forward jumps lands on 28. What is the size of each jump?","answer":5,"explain":"Total distance = 28 − 3 = 25. Divide by 5 jumps: 25 ÷ 5 = 5 per jump."},{"kind":"mcq","prompt":"A grasshopper starts at 40 and after 4 equal backward jumps lands on 24. What is the size of each jump?","options":["3","5","4","6"],"answer":2,"explain":"Total distance = 40 − 24 = 16. Divide by 4 jumps: 16 ÷ 4 = 4 per jump."},{"kind":"numeric","prompt":"Hopper starts at 6 and after 6 equal forward jumps lands on 42. What is the size of each jump?","answer":6,"explain":"Total distance = 42 − 6 = 36. Divide by 6 jumps: 36 ÷ 6 = 6 per jump."},{"kind":"mcq","prompt":"You know a jumper's start position, its end position, and the number of jumps it made. How do you find the jump size?","options":["Subtract start from end, then divide by the number of jumps","Divide start by end","Add start and end, then multiply by the number of jumps","Multiply start by end"],"answer":0,"explain":"The jump size is the total distance traveled (end minus start) shared equally across all the jumps."}]},{"id":"aj4","title":"Pattern Patrol","icon":"🔮","kind":"lesson","story":"The animals of Number-Line Island are hopping in mysterious sequences. Hopper must predict the next few landing spots by spotting the hidden pattern — just like a computer predicts the next step in a loop.","teach":[{"title":"Spotting the Pattern","body":"A sequence like 2, 5, 8, 11 hides a jump rule: each number is 3 more than the one before it. Once you spot the pattern, you can predict future terms without listing every single hop.","visual":"🧩"},{"title":"Predicting Ahead","body":"To jump straight to a later term without simulating every hop, find the jump size, multiply it by how many jumps from the start, then add (or subtract) it from the starting value.","visual":"🚀"}],"questions":[{"kind":"numeric","prompt":"What is the next number in this sequence: 4, 9, 14, 19, ___?","answer":24,"explain":"The jump rule is +5 each time, so 19 + 5 = 24."},{"kind":"mcq","prompt":"A frog's landing spots are 50, 44, 38, 32... What is its next landing spot?","options":["30","24","28","26"],"answer":3,"explain":"The jump rule is −6 each time, so 32 − 6 = 26."},{"kind":"numeric","prompt":"A sequence starts at 5 and jumps forward by 7 each time: 5, 12, 19, 26... What is the 6th number (counting 5 as the 1st)?","answer":40,"explain":"The 6th term is 5 plus 5 jumps of 7: 5 + (7 × 5) = 40."},{"kind":"mcq","prompt":"In the sequence 100, 90, 80, 70..., what is the jump rule?","options":["Subtract 10 each time","Multiply by 10 each time","Add 10 each time","Divide by 10 each time"],"answer":0,"explain":"Each number is 10 less than the one before it, so the rule is subtract 10."},{"kind":"numeric","prompt":"A sequence is 3, 8, 13, 18... What is the 10th term (counting 3 as the 1st)?","answer":48,"explain":"The 10th term is 3 plus 9 jumps of 5: 3 + (5 × 9) = 48."}]},{"id":"aj5","title":"Two Frogs, One Race","icon":"🐸","kind":"lesson","story":"Hopper challenges her cousin Blip to a hopping race along the same number line. Now Hopper must track two jumpers at once and figure out how their positions compare after every round.","teach":[{"title":"Tracking Multiple Jumpers","body":"When two animals jump at the same time with different rules, a computational thinker tracks each one's position separately, step by step, then compares them.","visual":"🐢"},{"title":"Comparing Positions","body":"Two jumpers 'meet' when they land on the exact same number after the exact same number of jumps. Comparing their positions round by round helps us find that meeting spot — or spot who is ahead.","visual":"🤝"}],"questions":[{"kind":"numeric","prompt":"Hopper starts at 0 and jumps 4 forward each turn. Blip starts at 0 and jumps 6 forward each turn. After 3 turns, how far apart are they?","answer":6,"explain":"Hopper is at 12 and Blip is at 18 after 3 turns. 18 − 12 = 6 apart."},{"kind":"mcq","prompt":"Frog A starts at 2 and jumps 5 forward each time. Frog B starts at 20 and jumps 3 backward each time. After 2 jumps each, who is at the bigger position?","options":["Frog A","Cannot be determined","Frog B","They are equal"],"answer":2,"explain":"Frog A reaches 2 + 10 = 12, and Frog B reaches 20 − 6 = 14, so Frog B's position is bigger."},{"kind":"numeric","prompt":"A ladybird starts at 1 and jumps 2 steps forward every turn. Where is the ladybird after its 5th jump?","answer":11,"explain":"1 + (2 × 5) = 11."},{"kind":"mcq","prompt":"Two frogs both start at 0. Frog X jumps 4 steps each time, and Frog Y jumps 8 steps each time. After the same number of jumps, what is always true about Frog Y's position compared to Frog X's?","options":["It is always exactly double Frog X's position","They are always equal","It is always 4 more than Frog X's position","It is always exactly half Frog X's position"],"answer":0,"explain":"Since Frog Y's jump size (8) is exactly double Frog X's jump size (4), and both start at 0, Frog Y's position is always double Frog X's."}]},{"id":"aj6","title":"Bug in the Hop Code","icon":"🐛","kind":"lesson","story":"Someone mis-programmed the practice course, and a few jumps skipped their proper step! Hopper must trace through the jump log to find exactly where things went wrong, and learn to handle a wall that bounces jumps back.","teach":[{"title":"Tracing an Algorithm","body":"To debug a set of steps, trace through them one at a time, writing down the result after each step. The step where your trace disagrees with the reported answer is exactly where the bug is hiding.","visual":"🐞"},{"title":"Boundaries and Walls","body":"Some number lines have edges! If a jump would go past a wall, the rule can say to 'bounce back' the extra distance instead — a special case a careful algorithm must handle.","visual":"🧱"}],"questions":[{"kind":"numeric","prompt":"A frog starts at 5 and jumps 4 steps forward each time for 3 jumps. A logbook claims it lands on 21, but that's wrong! What is the CORRECT landing spot?","answer":17,"explain":"5 + (4 × 3) = 17, not 21 — the logbook made a mistake."},{"kind":"mcq","prompt":"Trace this jump log: start 8, jump +3 gives 11, jump +3 gives 14, jump +3 gives 16. Which jump has an error?","options":["The first jump","The second jump","There is no error","The third jump (should be 17, not 16)"],"answer":3,"explain":"14 + 3 = 17, not 16, so the third step's addition was recorded wrong."},{"kind":"numeric","prompt":"There is a wall at position 20. A frog starts at 15 and jumps 8 forward, which would land past the wall at 23. The extra distance past the wall bounces the frog back the same amount. Where does it actually land?","answer":17,"explain":"The frog overshoots by 23 − 20 = 3, so it bounces back from the wall: 20 − 3 = 17."},{"kind":"mcq","prompt":"A frog should jump 5 forward each time, but a bug makes it jump 5 backward on the 2nd jump only. Starting at 10, where does it actually end up after 3 jumps?","options":["25","15","20","10"],"answer":1,"explain":"10 + 5 (jump 1) − 5 (buggy jump 2) + 5 (jump 3) = 15."}]},{"id":"aj-boss","title":"The Grand Hop-Off","icon":"👑","kind":"boss","story":"All of Number-Line Island gathers to watch Hopper face the legendary Jumpmaster Ribbit in the Grand Hop-Off — a final contest testing every jump-tracing, pattern-spotting, and rule-finding skill she has learned.","boss":{"name":"Jumpmaster Ribbit","taunt":"Think you can out-hop the Jumpmaster? Show me your smartest jump-tracing skills, little frog!"},"teach":[{"title":"Putting It All Together","body":"Forward jumps, backward jumps, finding a missing rule, spotting patterns, comparing jumpers, and debugging a jump log — every skill from Number-Line Island is about to be tested at once!","visual":"🏆"}],"questions":[{"kind":"numeric","prompt":"A frog starts at 12 and jumps 7 steps forward each time. Where does it land after 5 jumps?","answer":47,"explain":"12 + (7 × 5) = 47."},{"kind":"mcq","prompt":"A frog starts at 60 and jumps 9 steps backward each time. Where does it land after 4 jumps?","options":["24","30","20","26"],"answer":0,"explain":"60 − (9 × 4) = 24."},{"kind":"numeric","prompt":"A frog starts at 5 and after 6 equal forward jumps lands on 41. What is the size of each jump?","answer":6,"explain":"Total distance = 41 − 5 = 36. Divide by 6 jumps: 36 ÷ 6 = 6 per jump."},{"kind":"mcq","prompt":"What is the next number in this sequence: 90, 81, 72, 63, ___?","options":["45","54","55","60"],"answer":1,"explain":"The jump rule is −9 each time, so 63 − 9 = 54."},{"kind":"numeric","prompt":"Frog A starts at 0 and jumps 10 steps forward each time. Frog B starts at 100 and jumps 15 steps backward each time. After 4 jumps each, how far apart are they?","answer":0,"explain":"Frog A reaches 0 + 40 = 40, and Frog B reaches 100 − 60 = 40 — they land on the exact same spot, 0 apart!"},{"kind":"mcq","prompt":"Trace this jump log: start 4, jump +6 gives 10, jump +6 gives 17, jump +6 gives 22. Where is the mistake?","options":["There is no mistake","The third jump is wrong","The first jump is wrong","The second jump should be 16, not 17"],"answer":3,"explain":"10 + 6 = 16, not 17, so the second step's addition was recorded wrong."},{"kind":"numeric","prompt":"There is a wall at position 30. A frog starts at 22 and jumps 12 forward, which would land past the wall at 34. The extra distance past the wall bounces the frog back the same amount. Where does it actually land?","answer":26,"explain":"The frog overshoots by 34 − 30 = 4, so it bounces back from the wall: 30 − 4 = 26."}]}]},{"id":"mapsandlocations5","index":13,"name":"Maps and Locations","subtitle":"Computational Thinking — Chapter 14","emoji":"🗺️","palette":{"from":"#22d3ee","to":"#164e63"},"lessons":[{"id":"ma1","title":"The Grid Kingdom Awakens","icon":"📍","kind":"lesson","story":"You step through a shimmering gate into the Grid Kingdom, where every street is a straight line and every building sits at an exact spot. The Royal Mapmaker hands you a chalk and says, 'Before you can rule these streets, you must learn to describe WHERE things are.'","teach":[{"title":"Coordinates: Your Location Code","body":"A location can be described using two numbers: how many blocks EAST (or west) and how many blocks NORTH (or south) it is from a starting point. Together these two numbers are called coordinates, and they pinpoint one exact spot.","visual":"📍"}],"questions":[{"kind":"mcq","prompt":"The library is 3 blocks east and 2 blocks north of the school. Which of these correctly describes the library's location?","options":["2 blocks east and 3 blocks north","3 blocks east and 2 blocks north","3 blocks east and 2 blocks south","3 blocks west and 2 blocks north"],"answer":1,"explain":"The library's coordinates are given exactly as 3 east and 2 north of the school — the order and direction both matter."},{"kind":"numeric","prompt":"Point A is 4 blocks east of the school (0 blocks north). Point B is 4 blocks east and 3 blocks north of the school. How many blocks north is B compared to A?","answer":3,"explain":"Both points share the same east distance (4), so the difference is just B's north value: 3."},{"kind":"numeric","prompt":"The park sits 5 blocks east and 0 blocks north of home, on the very same street as home. If you can only walk east, how many blocks do you walk to reach the park?","answer":5,"explain":"Since the north distance is 0, walking straight east for 5 blocks gets you exactly there."},{"kind":"mcq","prompt":"On a coordinate grid, which pair of numbers tells you exactly where a point is located?","options":["Its size","Its coordinates (east and north distances)","Its name","Its color"],"answer":1,"explain":"Coordinates are the two numbers (east/west and north/south distances) that pin down an exact location."}]},{"id":"ma2","title":"Follow the Compass","icon":"🧭","kind":"lesson","story":"A gust of wind spins the Kingdom's giant compass statue, and now every street sign is scrambled! The Royal Guide teaches you the secret of turning: a right turn spins you clockwise, a left turn spins you the other way.","teach":[{"title":"Turning Left and Right","body":"Facing North and turning right (a 90-degree turn) makes you face East. Keep turning right and you go East, then South, then West, then back to North — like a clock. A left turn spins the opposite way.","visual":"🧭"}],"questions":[{"kind":"mcq","prompt":"You are facing North. You turn right (90 degrees). Which direction are you facing now?","options":["South","East","West","North"],"answer":1,"explain":"A right turn from North moves you one step clockwise, which lands on East."},{"kind":"mcq","prompt":"You are facing East. You turn left (90 degrees). Which direction are you facing now?","options":["South","North","West","East"],"answer":1,"explain":"A left turn from East moves you one step counter-clockwise, back to North."},{"kind":"mcq","prompt":"Riya is facing North. She takes 1 right turn, then 1 more right turn. Which direction is she facing now?","options":["North","East","West","South"],"answer":3,"explain":"Two right turns is 180 degrees, which flips North all the way around to South."},{"kind":"mcq","prompt":"Kabir faces North. He turns left, then left, then left again (three left turns in total). Which direction does he face now?","options":["East","South","West","North"],"answer":0,"explain":"Left turns go North to West to South to East — three lefts lands on East."}]},{"id":"ma3","title":"Village Directions","icon":"🏘️","kind":"lesson","story":"Deep in Huts Hollow, four tiny huts sit scattered near a lake. The village elder won't draw you a picture — she only gives you clues in words, and challenges you to work out who lives where.","teach":[{"title":"Combining Clues to Find Directions","body":"When you know how two places relate (like 'Oak is west of Pine'), you can combine several such clues to figure out the direction between ANY two places, even ones never compared directly. Opposite directions flip too: if Oak is west of Pine, then Pine is east of Oak.","visual":"🏘️"}],"questions":[{"kind":"mcq","prompt":"Four huts sit near a lake: Oak is west of Pine. Maple is south of Oak. Birch is north of Pine. In which direction is Maple with respect to Birch?","options":["South-West","South-East","North-East","North-West"],"answer":0,"explain":"Maple is south of Oak, and Oak is west of Pine (with Birch north of Pine), so Maple ends up south-west of Birch."},{"kind":"mcq","prompt":"Using the same huts (Oak west of Pine, Maple south of Oak, Birch north of Pine), in which direction is Birch with respect to Maple?","options":["South-West","North-West","South-East","North-East"],"answer":3,"explain":"Direction flips going the other way — since Maple is south-west of Birch, Birch must be north-east of Maple."},{"kind":"mcq","prompt":"Which hut is directly east of Oak?","options":["Birch","Maple","None of them","Pine"],"answer":3,"explain":"The clues state Oak is west of Pine, which means Pine is directly east of Oak."},{"kind":"mcq","prompt":"In which direction is Pine with respect to Maple?","options":["South-West","North-West","North-East","South-East"],"answer":2,"explain":"Maple is south of Oak, and Pine is east of Oak, so Pine sits to the north-east of Maple."}]},{"id":"ma4","title":"The Right-Turn Trail","icon":"➡️","kind":"lesson","story":"A twisty forest trail lies ahead, and the trail markers only give turn-by-turn instructions — no pictures allowed! To reach the old watchtower, you must trace the path in your head, one exact step at a time.","teach":[{"title":"Routes as a Sequence of Steps","body":"A route can be written as an exact, ordered list of moves — like 'go straight, turn right, go straight.' This ordered list is a tiny algorithm: follow the steps in order, and you always end up in the same place.","visual":"➡️"}],"questions":[{"kind":"numeric","prompt":"A trail is described as: Start facing East. Go straight. Turn right. Go straight. Turn right. Go straight. Turn left. Go straight. How many RIGHT turns are in this trail?","answer":2,"explain":"Counting the instructions in order, 'turn right' appears exactly twice."},{"kind":"mcq","prompt":"Using the same trail (start facing East, then right, right, left turns in that order), which direction are you facing at the very end?","options":["North","South","East","West"],"answer":1,"explain":"East, right turn, to South; right turn, to West; left turn, back to South — the final facing is South."},{"kind":"numeric","prompt":"A robot starts at the school facing North and follows: move 2 blocks forward, turn right, move 3 blocks forward, turn right, move 2 blocks forward, turn right, move 3 blocks forward. Each block takes 1 minute to walk. How many minutes does the whole route take (ignore turning time)?","answer":10,"explain":"Adding up all the forward moves: 2 + 3 + 2 + 3 = 10 minutes."},{"kind":"mcq","prompt":"Which of these is a proper ALGORITHM for walking from home to the park?","options":["Walk toward the park somewhere near the trees","Go north 2 blocks, then turn right and go east 3 blocks","You'll probably find it eventually","It's not too far, just head that way"],"answer":1,"explain":"An algorithm needs exact, ordered, unambiguous steps — only the first option gives precise distances and directions."}]},{"id":"ma5","title":"Treasure Map Clues","icon":"🏴‍☠️","kind":"lesson","story":"Captain Chartwell's old treasure map has no big red X — just a scrap of paper covered in riddle-like clues. The grid boxes are labelled by a column letter (A to E) and a row number (1 to 5). Only careful deduction will reveal the treasure's box.","teach":[{"title":"Deducing a Location from Clues","body":"When a map gives several clues instead of a picture, you narrow down the possibilities step by step — crossing out anything that doesn't fit each clue — until only ONE box is left standing. This is called deduction.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"Clues for the first treasure: (1) It is in an odd-numbered row. (2) It is not in row 1 or row 5. (3) It is in column B. Which box holds the treasure?","options":["B3","D3","B5","B1"],"answer":0,"explain":"Odd rows are 1, 3, 5; removing row 1 and row 5 leaves row 3, and the column is given as B, so the box is B3."},{"kind":"mcq","prompt":"Clues for a second treasure: (1) The row number is greater than 3. (2) The row number is even. (3) The column is not A, B, or C. (4) The column comes right before E in the alphabet. Which box holds the treasure?","options":["D4","D5","C4","E4"],"answer":0,"explain":"Rows greater than 3 and even leaves only row 4; a column that isn't A, B, or C and comes right before E must be D — so the box is D4."},{"kind":"numeric","prompt":"On the treasure grid, columns are numbered A=1, B=2, C=3, D=4, E=5, and rows are numbered 1 to 5. What is the sum of the column number and row number for box B2?","answer":4,"explain":"Column B is number 2 and the row is also 2, so 2 + 2 = 4."},{"kind":"mcq","prompt":"Why is it useful to use clues like 'not in row 1 or row 5' when reading a mystery map?","options":["It is not useful at all","It helps eliminate wrong locations until only one is left","It changes where the treasure actually is","It makes the map more colorful"],"answer":1,"explain":"Each clue removes possibilities, narrowing the search until a single correct location remains — that's deduction."}]},{"id":"ma6","title":"The Algorithm of Steps","icon":"🤖","kind":"lesson","story":"The Kingdom's delivery robot, Rolo, needs exact written directions or it will roll off in the wrong direction entirely. You must write and trace its path as a precise ordered list of moves.","teach":[{"title":"Order Matters (Sometimes!)","body":"When moves are given as fixed compass directions (like 'East 4, North 3'), adding them up in any order gives the same final spot. But when moves are given as turns plus 'forward' (like the trail markers), the order changes everything, because each turn changes what 'forward' means next.","visual":"🤖"}],"questions":[{"kind":"numeric","prompt":"Rolo starts at the school (0,0) and follows: North 3, East 2, North 1, East 4. How many blocks EAST of the school is Rolo's final position?","answer":6,"explain":"Adding the east moves: 2 + 4 = 6 blocks east."},{"kind":"numeric","prompt":"Using the same route (North 3, East 2, North 1, East 4), how many blocks NORTH of the school is Rolo's final position?","answer":4,"explain":"Adding the north moves: 3 + 1 = 4 blocks north."},{"kind":"mcq","prompt":"If Rolo instead followed the moves in a different order — East 4, North 3, East 2, North 1 — would it end up at the same final spot?","options":["No, because order always changes the destination","No, it would end up somewhere completely different","Yes, but only if it turns around first","Yes, because it still ends up 6 east and 4 north"],"answer":3,"explain":"Compass-direction moves (east/north) just add up — reordering them doesn't change the total distance in each direction."},{"kind":"mcq","prompt":"A different route uses TURN instructions like 'turn right, go forward' instead of compass directions. Why does the ORDER of these instructions matter so much?","options":["Because forward always means north no matter what","Because each turn changes which direction 'forward' means for the next step","Because turning makes the robot go slower","Order never matters for any kind of route"],"answer":1,"explain":"Unlike fixed compass moves, a turn changes your current facing — so swapping the order sends you down a totally different path."}]},{"id":"ma-boss","title":"The Cartographer's Challenge","icon":"👑","kind":"boss","story":"At the heart of the Grid Kingdom stands the Master Cartographer, guardian of every map ever drawn. To earn your title as a true Map Reader, you must prove you can handle coordinates, turns, relative directions, and route algorithms — all at once.","boss":{"name":"Grandmaster Wanderwrong","taunt":"You think a few blocks and a compass can out-map me? Let's see you find your way, little navigator!"},"teach":[{"title":"Putting It All Together","body":"Great map readers combine every skill: reading coordinates, tracking turns, comparing relative directions, and tracing algorithms step by step. Stay careful and methodical, and no map can trick you.","visual":"👑"}],"questions":[{"kind":"numeric","prompt":"The tower is 6 blocks east of the fort. The bridge is 6 blocks east and 4 blocks north of the fort. How many blocks north of the tower is the bridge?","answer":4,"explain":"The tower and bridge share the same east position, so the difference is just the bridge's north value: 4."},{"kind":"mcq","prompt":"You face North. You turn right, then right, then right again (three right turns in total). Which direction do you face now?","options":["East","North","West","South"],"answer":2,"explain":"Three right turns from North goes East, then South, then West."},{"kind":"mcq","prompt":"Camp X is north of Camp Y. Camp Z is east of Camp X. In which direction is Camp Z with respect to Camp Y?","options":["South-West","North-West","North-East","South-East"],"answer":2,"explain":"Z is north of Y (through X) and also east, so combined that makes Z north-east of Y."},{"kind":"numeric","prompt":"Follow this route from home: North 5, East 3, South 2, East 1. How many blocks EAST of home is the final position?","answer":4,"explain":"Adding the east moves: 3 + 1 = 4 blocks east."},{"kind":"numeric","prompt":"Using the same route (North 5, East 3, South 2, East 1), how many blocks NORTH of home is the final position?","answer":3,"explain":"Combining the north and south moves: 5 - 2 = 3 blocks north."},{"kind":"mcq","prompt":"Clues for a hidden key: (1) it's in an odd-numbered row. (2) the row number is less than 3. (3) it's in column A. Which box holds the key (columns A-E, rows 1-5)?","options":["A1","B1","A3","A2"],"answer":0,"explain":"The only odd row number less than 3 is row 1, and the column is given as A, so the box is A1."},{"kind":"mcq","prompt":"Two robots start at the same spot facing North. Robot 1 does: forward, right turn, forward. Robot 2 does: right turn, forward, forward. Do they end up in the same place?","options":["No, because the order of turns and moves changes the path","Yes, they always end up in the same place","Yes, because both robots take the same number of steps","No, because Robot 2 is faster"],"answer":0,"explain":"Robot 1 moves forward before turning while Robot 2 turns first, so their paths — and final spots — end up different."}]}]},{"id":"datathroughpictures5","index":14,"name":"Data Through Pictures","subtitle":"Computational Thinking — Chapter 15","emoji":"📊","palette":{"from":"#a78bfa","to":"#4c1d95"},"lessons":[{"id":"dp1","title":"Picture the Data","icon":"🖼️","kind":"lesson","story":"You step into Data Valley, where the villagers speak only in symbols. The Symbol Keeper says every little picture hides a number, and only a sharp-eyed data reader can unlock the valley's first gate.","teach":[{"title":"What Is a Pictograph?","body":"A pictograph uses small pictures or symbols to show amounts of data. A key (or legend) tells you exactly how much each symbol stands for, so always check the key first before counting anything.","visual":"🔑"},{"title":"Counting the Total","body":"To find the total a row shows, multiply the number of symbols by the value in the key. Three symbols worth 4 each means 3 times 4 = 12 in total.","visual":"✖️"}],"questions":[{"kind":"mcq","prompt":"In the Fruit Stall pictograph, the key says: one apple symbol = 4 apples. Monday's row shows 3 apple symbols. How many apples were sold on Monday?","options":["12","16","3","7"],"answer":0,"explain":"3 symbols times 4 apples each = 12 apples."},{"kind":"numeric","prompt":"Using the same key (one apple symbol = 4 apples), Tuesday's row shows 5 apple symbols. How many apples were sold on Tuesday?","answer":20,"explain":"5 symbols times 4 apples each = 20 apples."},{"kind":"numeric","prompt":"Monday sold 12 apples and Tuesday sold 20 apples. How many apples were sold in total across both days?","answer":32,"explain":"12 + 20 = 32 apples in total."},{"kind":"mcq","prompt":"Why must you always check the key of a pictograph before answering questions about it?","options":["Because the key tells you the color of the symbols","Because each symbol can stand for a different amount, like 1, 2, 5 or more items","Because every pictograph always uses the number 1 for each symbol","Because the key is just decoration and can be ignored"],"answer":1,"explain":"Symbols can represent any value the chart-maker chooses, so the key must always be checked first."}]},{"id":"dp2","title":"Reading the Rows","icon":"📈","kind":"lesson","story":"Deeper in Data Valley, two rival Kite Clubs, Club Sky and Club Cloud, have hung up rows of kite symbols to boast about their wins. Only by comparing the rows correctly can you settle their friendly rivalry and earn the second gate key.","teach":[{"title":"Comparing Two Rows","body":"When comparing two pictograph rows, first find the total for each row separately, then subtract the smaller total from the bigger one to find the difference between them.","visual":"⚖️"}],"questions":[{"kind":"numeric","prompt":"Key: one kite symbol = 3 wins. Club Sky's row shows 4 kite symbols. How many wins does Club Sky have?","answer":12,"explain":"4 symbols times 3 wins each = 12 wins."},{"kind":"numeric","prompt":"Club Cloud's row shows 6 kite symbols (same key, one kite symbol = 3 wins). How many wins does Club Cloud have?","answer":18,"explain":"6 symbols times 3 wins each = 18 wins."},{"kind":"mcq","prompt":"How many more wins does Club Cloud have than Club Sky?","options":["6","3","9","12"],"answer":0,"explain":"18 wins minus 12 wins = 6 more wins for Club Cloud."},{"kind":"numeric","prompt":"Club Sky wins 2 more matches next week. How many total wins will Club Sky have then?","answer":14,"explain":"12 + 2 = 14 wins."}]},{"id":"dp3","title":"Half a Symbol","icon":"🌳","kind":"lesson","story":"The Orchard Keeper of Data Valley only draws whole and half trees to show her harvest. She warns that a half symbol never lies, it is exactly half the value of a whole one.","teach":[{"title":"Half Symbols","body":"Sometimes a pictograph uses half of a symbol to show half the key's value. If one tree symbol = 10 trees, then half a tree symbol = 5 trees. Add the whole symbols and half symbols together to get the total.","visual":"➗"}],"questions":[{"kind":"numeric","prompt":"Key: one tree symbol = 10 trees. Team A's row shows 2 full trees and 1 half tree. How many trees does Team A have?","answer":25,"explain":"2 full trees = 20 trees, plus 1 half tree = 5 trees. 20 + 5 = 25 trees."},{"kind":"numeric","prompt":"Team B's row shows 3 full trees and 1 half tree (same key, one tree symbol = 10 trees). How many trees does Team B have?","answer":35,"explain":"3 full trees = 30 trees, plus 1 half tree = 5 trees. 30 + 5 = 35 trees."},{"kind":"mcq","prompt":"How many more trees does Team B have than Team A?","options":["5","25","15","10"],"answer":3,"explain":"35 trees minus 25 trees = 10 more trees for Team B."},{"kind":"mcq","prompt":"A row shows 1 full tree and 1 half tree, using the same key (one tree symbol = 10 trees). What is the total?","options":["5","15","20","10"],"answer":1,"explain":"1 full tree = 10 trees, plus 1 half tree = 5 trees. 10 + 5 = 15 trees."}]},{"id":"dp4","title":"Tables Tell Tales","icon":"📋","kind":"lesson","story":"You find the Keeper's Ledger, a table listing how many books each class read this month. The numbers hide a pattern, but only if you know how to read across rows and down columns.","teach":[{"title":"Reading a Data Table","body":"A data table organizes information into rows and columns. Each row is usually one item or group, and each column shows a different fact about it, like a name and a number. Read carefully to match the right row with the right fact.","visual":"📋"}],"questions":[{"kind":"numeric","prompt":"The Reading Ledger shows: Class 5A = 18 books, 5B = 24 books, 5C = 15 books, 5D = 21 books. How many books did Class 5A and 5C read together?","answer":33,"explain":"18 + 15 = 33 books."},{"kind":"mcq","prompt":"Using the same ledger, which class read the most books?","options":["5B","5A","5C","5D"],"answer":0,"explain":"5B read 24 books, the highest number in the ledger."},{"kind":"mcq","prompt":"Which class read the fewest books?","options":["5C","5D","5A","5B"],"answer":0,"explain":"5C read only 15 books, the lowest number in the ledger."},{"kind":"numeric","prompt":"What is the combined total of books read by all four classes together?","answer":78,"explain":"18 + 24 + 15 + 21 = 78 books."},{"kind":"numeric","prompt":"How many more books did 5B read than 5D?","answer":3,"explain":"24 - 21 = 3 more books."}]},{"id":"dp5","title":"Bar Charts in Words","icon":"📊","kind":"lesson","story":"At the Weather Tower, a chart tracking sunny days each month can only be described in words now, since the tower's paint washed away in the rain. Interpret it correctly to unlock the tower door.","teach":[{"title":"Bar Charts Without Pictures","body":"A bar chart can be described using just a list of category names and their values, like March: 12, April: 18. The bigger the number, the taller the bar would be, so you can compare bars just by comparing the numbers.","visual":"📊"}],"questions":[{"kind":"mcq","prompt":"Sunny days chart: March = 12, April = 18, May = 9, June = 21. Which month had the most sunny days?","options":["June","March","May","April"],"answer":0,"explain":"June had 21 sunny days, the highest value."},{"kind":"numeric","prompt":"Using the same chart, how many sunny days were there in March and May combined?","answer":21,"explain":"12 + 9 = 21 sunny days."},{"kind":"numeric","prompt":"How many more sunny days did June have than May?","answer":12,"explain":"21 - 9 = 12 more sunny days."},{"kind":"mcq","prompt":"Put the months in order from FEWEST to MOST sunny days.","options":["May, June, March, April","June, April, May, March","March, May, June, April","May, March, April, June"],"answer":3,"explain":"The values are May=9, March=12, April=18, June=21, so that is the order from fewest to most."}]},{"id":"dp6","title":"Data Detective","icon":"🕵️","kind":"lesson","story":"The valley's Snack Shop logs which treats it sells each day, but the log book got smudged. Use the clues to deduce the missing answers and prove yourself a true Data Detective.","teach":[{"title":"Deducing from Clues","body":"Some data puzzles give clues in words instead of a full table. List what you know from each clue, then combine them step by step, like solving a mini mystery, to work out the answer.","visual":"🕵️"}],"questions":[{"kind":"mcq","prompt":"The Snack Shop (Monday to Friday only) sells: Cookies on Monday, Wednesday, and Friday. Juice every day except Tuesday. Muffins only on Monday and Thursday. On which day are Cookies, Juice, AND Muffins ALL sold together?","options":["Monday","Friday","Wednesday","Thursday"],"answer":0,"explain":"Only Monday has all three: Cookies, Juice, and Muffins are all sold that day."},{"kind":"mcq","prompt":"The shop also sells Chips every day except Monday. On Friday, which treat is NOT sold?","options":["Cookies","Muffins","Chips","Juice"],"answer":1,"explain":"Muffins are only sold on Monday and Thursday, so they are not sold on Friday."},{"kind":"numeric","prompt":"Chips are sold every day except Monday. Out of the 5 days (Monday to Friday), on how many days are Chips sold?","answer":4,"explain":"5 days total minus the 1 day (Monday) they are not sold = 4 days."},{"kind":"mcq","prompt":"Counting all four treats (Cookies, Juice, Muffins, Chips) for each day, which day has the FEWEST treats sold?","options":["Friday","Tuesday","Wednesday","Monday"],"answer":1,"explain":"On Tuesday only Chips is sold, since Cookies, Juice, and Muffins are all skipped that day, so it has just 1 treat, the fewest."},{"kind":"numeric","prompt":"Counting treats sold each day (Monday=3, Tuesday=1, Wednesday=3, Thursday=3, Friday=3), what is the total number of treat-sales across all 5 days?","answer":13,"explain":"3 + 1 + 3 + 3 + 3 = 13."}]},{"id":"dp7","title":"The Capacity Puzzle","icon":"📦","kind":"lesson","story":"At the Final Storeroom, crates can only hold a set number of items. The Storekeeper needs your help figuring out how many more items can fit, or the crates will overflow!","teach":[{"title":"Working with Limits","body":"When a puzzle gives a maximum capacity, first find how many spaces are already used, then subtract that from the maximum to find how many more can be added. Always check whether the question asks about one group or several combined.","visual":"📦"}],"questions":[{"kind":"numeric","prompt":"Each crate can hold at most 9 toys. Crate B already has 4 toys in it. How many more toys can Crate B hold?","answer":5,"explain":"9 - 4 = 5 more toys can fit."},{"kind":"numeric","prompt":"Crate C already has 6 toys in it (same 9-toy limit). How many more toys can Crate C hold?","answer":3,"explain":"9 - 6 = 3 more toys can fit."},{"kind":"mcq","prompt":"How many more toys in total can be added across Crate B and Crate C combined?","options":["3","9","5","8"],"answer":3,"explain":"5 (Crate B's space) + 3 (Crate C's space) = 8 toys in total."},{"kind":"numeric","prompt":"Crate B starts with 4 toys and receives 3 more toys. How many toys does Crate B have now?","answer":7,"explain":"4 + 3 = 7 toys, which is still within the 9-toy limit."}]},{"id":"dp-boss","title":"The Grand Data Vault","icon":"👑","kind":"boss","story":"You've reached the heart of Data Valley, the Grand Data Vault, guarded by the legendary Data Sentinel. To claim your final Class 5 badge, prove you can read pictographs, tables, and bar charts all at once, and reason your way through the toughest clues in the valley.","teach":[{"title":"Becoming a Data Champion","body":"Great data readers always check the key, add up totals carefully, compare group by group, and use clues step by step. You have now used every one of these skills to master pictographs, tables, and bar charts!","visual":"🏆"}],"boss":{"name":"The Data Sentinel","taunt":"Show me you can turn pictures and numbers into answers, young data champion, and Data Valley's final gate is yours!"},"questions":[{"kind":"numeric","prompt":"Key: one cookie symbol = 6 cookies. A jar's row shows 3 cookie symbols. How many cookies are in the jar?","answer":18,"explain":"3 symbols times 6 cookies each = 18 cookies."},{"kind":"numeric","prompt":"Key: one star symbol = 8 points. A team's row shows 2 full stars and 1 half star. How many points does the team have?","answer":20,"explain":"2 full stars = 16 points, plus half a star = 4 points. 16 + 4 = 20 points."},{"kind":"mcq","prompt":"A table shows: Red Team = 14 points, Blue Team = 19 points, Green Team = 11 points. Which team scored the most points?","options":["They are tied","Green Team","Blue Team","Red Team"],"answer":2,"explain":"Blue Team scored 19 points, the highest of the three."},{"kind":"numeric","prompt":"Using the same table (Red=14, Blue=19, Green=11), what is the combined total of all three teams' points?","answer":44,"explain":"14 + 19 + 11 = 44 points."},{"kind":"mcq","prompt":"A bar chart shows visitors: Monday = 25, Tuesday = 40, Wednesday = 15. How many more visitors came on Tuesday than on Wednesday?","options":["10","40","15","25"],"answer":3,"explain":"40 - 15 = 25 more visitors."},{"kind":"mcq","prompt":"At the Vault, Door 1 opens on Monday and Friday. Door 2 opens every day except Sunday. Door 3 opens only on Friday. On which day are ALL three doors open together?","options":["Sunday","Friday","Monday","Every day"],"answer":1,"explain":"Door 1 is open on Friday (one of its two days), Door 2 is open (it is open every day except Sunday), and Door 3 is open (its only day is Friday). Friday is the only day all three match."},{"kind":"numeric","prompt":"Each shelf in the Vault can hold at most 12 scrolls. One shelf already holds 7 scrolls. How many more scrolls can that shelf hold?","answer":5,"explain":"12 - 7 = 5 more scrolls."}]}]}];